import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const getMimeType = (base64: string): string => {
  const match = base64.match(/^data:([^;]+);base64,/);
  return match ? match[1] : 'image/png';
};

const cleanBase64 = (base64: string): string => {
  return base64.includes(',') ? base64.split(',')[1] : base64;
};

/**
 * Der "Master Art Director" Schritt.
 * Nutzt Gemini 3 Pro mit Thinking Budget für psychologisch optimierte Thumbnails.
 */
const optimizePromptForCTR = async (userPrompt: string, style: string) => {
  const ai = getAI();
  const systemInstruction = `Du bist der weltweit führende Art Director für YouTube Thumbnails. 
  Deine Aufgabe ist es, einen einfachen Nutzer-Prompt in eine hochprofessionelle, klickstarke visuelle Beschreibung (in Englisch) für eine KI umzuwandeln.

  DESIGN-PRINZIPIEN FÜR DICH:
  1. SUBJECT: Ein klares Hauptmotiv, oft mit extremen Emotionen (Shock, Joy, Anger). Rim-lighting (Lichtkante) zur Abhebung vom Hintergrund.
  2. COMPOSITION: Drittel-Regel. Genügend Platz für Text (links oder rechts lassen). Keine visuellen Unklarheiten.
  3. COLOR & LIGHT: Übersteigerte Sättigung, hoher Kontrast, "Cinematic Lighting", "Studio Quality".
  4. BACKGROUND: Meist unscharf (Bokeh), um den Fokus auf das Subjekt zu lenken.
  5. ANTI-PATTERNS: Vermeide "Stock-Photo" Look. Es muss wie ein High-End YouTube Video Frame aussehen.

  STIL-LOGIK:
  - Beast: Extrem hoher Kontrast, glühende Augen/Elemente, gesättigte Farben (Cyan/Orange), Action-Elemente.
  - Gaming: Neon-Akzente, RGB-Glow, Bewegungsunschärfe (Speed Lines), Cyberpunk-Farben.
  - Clean: Studio-Beleuchtung, weiche Schatten, minimalistisch aber hochwertig, Apple-Ästhetik.
  - Minimal: Ein einziges, extrem scharfes Objekt vor einem texturierten, dezenten Hintergrund.

  ANTWORTE NUR ALS JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Erstelle eine professionelle Thumbnail-Beschreibung für: "${userPrompt}" im Stil "${style}".`,
      config: {
        thinkingConfig: { thinkingBudget: 4000 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            optimizedPrompt: { 
              type: Type.STRING, 
              description: "Der finale, detaillierte englische Prompt für den Bildgenerator." 
            },
            strategy: { 
              type: Type.STRING, 
              description: "Kurze Erklärung der psychologischen Klick-Strategie." 
            }
          },
          required: ["optimizedPrompt", "strategy"]
        }
      }
    });
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Art Direction failed:", e);
    return { optimizedPrompt: userPrompt, strategy: "Standard-Generierung" };
  }
};

/**
 * Kern-Funktion zur Bilderzeugung mit modernster Thumbnail-Architektur.
 */
export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9") => {
  const ai = getAI();

  // 1. Art Direction & Strategie-Check
  const { optimizedPrompt, strategy } = await optimizePromptForCTR(prompt, style);

  // 2. Technischer Wrapper für Thumbnail-Ästhetik
  const thumbnailWrapper = `Professional YouTube Thumbnail, 4K, Highly Detailed, Hyper-realistic, 
    Vibrant Colors, Cinematic Masterpiece, Bold Lighting, Depth of Field, 
    ${optimizedPrompt}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: thumbnailWrapper }] },
      config: { 
        imageConfig: { aspectRatio: aspectRatio as any } 
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return {
        url: `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`,
        optimizedPrompt: strategy // Wir zeigen dem User die Strategie statt den rohen Prompt
      };
    }
    throw new Error("Kein Bild generiert.");
  } catch (e: any) {
    throw new Error(e.message || "Fehler bei der Bilderzeugung.");
  }
};

/**
 * Überarbeitet ein bestehendes Thumbnail mit Fokus auf CTR-Details.
 */
export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();

  const instruction = `THUMBNAIL REFINEMENT: Modify the provided thumbnail by applying: "${adjustmentPrompt}". 
  Crucial: Maintain the same face, identity, and overall composition. 
  Improve lighting, add rim-light to the subject, increase color intensity on the modified part. 
  Output as a professional YouTube asset.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: instruction }
        ]
      },
      config: {
        imageConfig: { aspectRatio: "16:9" }
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`;
    }
    throw new Error("Refinement fehlgeschlagen.");
  } catch (e) {
    throw new Error("Fehler beim Refinement.");
  }
};

/**
 * Übernimmt den künstlerischen Stil eines Referenzbildes.
 */
export const cloneStyle = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();

  const instruction = `THUMBNAIL STYLE TRANSFER: Use the provided image as a strict aesthetic reference 
  (color grading, lighting style, grain, background blur level). 
  Generate a COMPLETELY NEW thumbnail motif: "${adjustmentPrompt}". 
  It must look like it was made by the same designer as the reference. 
  Ensure 4K professional YouTube quality.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: instruction }
        ]
      },
      config: {
        imageConfig: { aspectRatio: "16:9" }
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`;
    }
    throw new Error("Style Clone fehlgeschlagen.");
  } catch (e) {
    throw new Error("Fehler beim Style Clone.");
  }
};

export const analyzeThumbnailImage = async (base64Image: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: cleanBase64(base64Image), mimeType: getMimeType(base64Image) } },
        { text: "Analysiere Score (0-10) basierend auf YouTube CTR Best-Practices (Mimik, Kontrast, Lesbarkeit) und gib 3 präzise Profi-Tipps in JSON Deutsch." }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          score: { type: Type.NUMBER },
          feedback: { type: Type.STRING },
          suggestions: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["score", "feedback", "suggestions"]
      }
    }
  });
  return JSON.parse(response.text || '{}');
};

export const analyzeYoutubeChannel = async (channelUrl: string) => {
  const ai = getAI();
  const researchResponse = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Führe ein Branding Audit für "${channelUrl}" durch. Fokus auf die visuelle Strategie der Thumbnails und Branding-Konsistenz.`,
    config: { tools: [{ googleSearch: {} }] }
  });
  const extractionResponse = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Strukturiere als JSON: ${researchResponse.text}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          channelName: { type: Type.STRING },
          identitySummary: { type: Type.STRING },
          strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
          weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
          actionPlan: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["channelName", "identitySummary", "strengths", "weaknesses", "actionPlan"]
      }
    }
  });
  return JSON.parse(extractionResponse.text || '{}');
};

import { Wand2, Sparkles, Loader2, Download, Coins, Monitor, Smartphone, Square, Heart, Send, Zap, MessageSquare, ArrowRight, Info, Image as ImageIcon, Lightbulb } from 'lucide-react';
import React, { useState, useEffect } from 'react';
import { generateThumbnail, remakeThumbnail } from '../services/geminiService';
import { ThumbnailStyle, User, Design } from '../types';

interface StudioGenerateProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  onGoToPricing?: () => void;
  onSaveDesign?: (design: Design) => void;
}

const STYLE_SUGGESTIONS: Record<ThumbnailStyle, string[]> = {
  [ThumbnailStyle.CLEAN]: ["Apple-Look", "Studio Softbox", "Pastell", "4K-Face"],
  [ThumbnailStyle.BEAST]: ["Shocked Face", "Glow Effect", "Action-Pfeile", "Dramatischer Zoom"],
  [ThumbnailStyle.MINIMAL]: ["Negative Space", "Dezente Textur", "Fokus-Spotlight"],
  [ThumbnailStyle.GAMING]: ["Neon RGB", "Speed Lines", "Cyberpunk", "Gaming-Peripherie"]
};

const ASPECT_RATIOS = [
  { id: '16:9', label: 'Video (16:9)', icon: Monitor },
  { id: '9:16', label: 'Shorts (9:16)', icon: Smartphone },
  { id: '1:1', label: 'Post (1:1)', icon: Square },
];

interface GeneratedResult {
  id: string;
  url: string;
  prompt: string;
  optimizedPrompt: string;
  isSaved?: boolean;
  isRefining?: boolean;
  refinementText?: string;
}

export const StudioGenerate: React.FC<StudioGenerateProps> = ({ useCredits, user, onGoToPricing, onSaveDesign }) => {
  const [prompt, setPrompt] = useState('');
  const [style, setStyle] = useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [aspectRatio, setAspectRatio] = useState('16:9');
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 3;
          if (prev < 70) return prev + 1.5;
          if (prev < 95) return prev + 0.5;
          return prev;
        });
        const texts = ["Art Direction checkt Prompt...", "CTR-Strategie wird berechnet...", "Thumbnail wird gerendert...", "Licht-Korrekturen laufen..."];
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress]);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    const cost = 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt } = await generateThumbnail(prompt, style, aspectRatio);
      useCredits(cost);
      setResults(prev => [{
        id: `res-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        url,
        prompt: prompt,
        optimizedPrompt: optimizedPrompt, // Hier steckt nun die Strategie drin
        refinementText: ''
      }, ...prev]);
      setPrompt('');
      setProgress(100);
    } catch (err) {
      alert("Generierung fehlgeschlagen.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

  const handleRefine = async (resultId: string) => {
    const result = results.find(r => r.id === resultId);
    if (!result || !result.refinementText?.trim()) return;

    const cost = 5;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setResults(prev => prev.map(r => r.id === resultId ? { ...r, isRefining: true } : r));

    try {
      const refinedUrl = await remakeThumbnail(result.url, result.refinementText);
      useCredits(cost);
      setResults(prev => prev.map(r => r.id === resultId ? { 
        ...r, 
        url: refinedUrl, 
        isRefining: false, 
        refinementText: '',
        prompt: `${r.prompt} (+ ${result.refinementText})`
      } : r));
    } catch (err) {
      alert("Fehler beim Refinement.");
      setResults(prev => prev.map(r => r.id === resultId ? { ...r, isRefining: false } : r));
    }
  };

  const handleSave = (res: GeneratedResult) => {
    onSaveDesign?.({
      id: res.id,
      imageUrl: res.url,
      prompt: res.prompt,
      createdAt: new Date().toISOString(),
      style,
      aspectRatio
    });
    setResults(prev => prev.map(r => r.id === res.id ? { ...r, isSaved: true } : r));
  };

  return (
    <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-12 animate-in fade-in duration-500">

      {/* Configuration Sidebar (Sticky) */}
      <div className="w-full lg:w-[420px] space-y-6">
        <div className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl sticky top-28 gpu-accelerated">
          <div className="flex justify-between items-center mb-8">
            <h2 className="text-2xl font-black flex items-center gap-3 text-slate-900 dark:text-white">
              <Wand2 className="w-6 h-6 text-orange-500" /> Designer Lab
            </h2>
            <div className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full bg-amber-500/10 text-amber-500 border border-amber-500/10">
              <Coins className="w-3.5 h-3.5" /> 10 Credits
            </div>
          </div>

          <div className="space-y-6">
            <div>
              <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-3">Deine Video-Idee</label>
              <textarea 
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Beschreibe das Hauptmotiv (z.B. Creator testet krasses Gadget)..."
                className="w-full h-36 bg-slate-50 dark:bg-slate-800/50 border border-black/5 dark:border-white/5 rounded-3xl p-5 focus:ring-2 focus:ring-orange-500 outline-none transition-all resize-none text-sm font-medium"
              />
              <div className="flex flex-wrap gap-2 mt-4">
                {STYLE_SUGGESTIONS[style].map((s, i) => (
                  <button key={i} onClick={() => setPrompt(prev => prev + " " + s)} className="px-3 py-1.5 bg-slate-100 dark:bg-slate-800 rounded-xl text-[10px] font-black text-slate-500 hover:bg-orange-500 hover:text-white transition-colors">+ {s}</button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-3">
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500">Video Format</label>
                <div className="grid grid-cols-3 gap-2">
                  {ASPECT_RATIOS.map(r => (
                    <button key={r.id} onClick={() => setAspectRatio(r.id)} className={`p-2.5 rounded-xl border flex flex-col items-center gap-1 transition-all ${aspectRatio === r.id ? 'bg-orange-600 border-orange-600 text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-800 border-transparent text-slate-400'}`}>
                      <r.icon className="w-4 h-4" />
                      <span className="text-[8px] font-black">{r.id}</span>
                    </button>
                  ))}
                </div>
              </div>
              <div className="space-y-3">
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500">Thumbnail Stil</label>
                <select value={style} onChange={(e) => setStyle(e.target.value as ThumbnailStyle)} className="w-full h-[52px] bg-slate-50 dark:bg-slate-800/50 border border-black/5 rounded-xl px-4 text-xs font-black uppercase outline-none">
                  {Object.values(ThumbnailStyle).map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
            </div>

            <div className="pt-4">
              {loading ? (
                <div className="space-y-3 animate-in fade-in">
                  <div className="flex justify-between text-[10px] font-black uppercase text-orange-600 tracking-widest">
                    <span className="flex items-center gap-2"><Loader2 className="w-3 h-3 animate-spin" /> {statusText}</span>
                    <span>{Math.round(progress)}%</span>
                  </div>
                  <div className="h-1.5 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                    <div className="h-full bg-orange-600 transition-all duration-300" style={{ width: `${progress}%` }} />
                  </div>
                </div>
              ) : (
                <button 
                  onClick={handleGenerate}
                  disabled={!prompt.trim() || isLowCredits(10)}
                  className="w-full py-5 bg-orange-600 hover:bg-orange-700 text-white rounded-[2rem] font-black text-lg shadow-xl shadow-orange-600/20 flex items-center justify-center gap-3 transition-all active:scale-[0.98] disabled:opacity-50"
                >
                  <Zap className="w-6 h-6 fill-current" /> Thumbnail schmieden
                </button>
              )}
            </div>

            <div className="p-4 bg-orange-500/5 dark:bg-orange-500/10 rounded-2xl border border-orange-500/10 flex items-start gap-3">
               <Lightbulb className="w-4 h-4 text-orange-500 shrink-0 mt-0.5" />
               <p className="text-[10px] text-slate-500 leading-relaxed font-bold italic">
                 "ThumbCraft AI erstellt keine einfachen Bilder. Wir nutzen YouTube-Klick-Psychologie für dein Design."
               </p>
            </div>
          </div>
        </div>
      </div>

      {/* Results Feed */}
      <div className="flex-1 space-y-10 min-h-[500px]">
        {results.length > 0 ? (
          results.map((res) => (
            <div key={res.id} className="bg-white dark:bg-slate-900 rounded-[3.5rem] border border-black/5 dark:border-white/5 p-8 shadow-2xl animate-in fade-in duration-500 relative group/card content-auto gpu-accelerated">
              <div className="flex flex-col md:flex-row gap-10">

                {/* Image Section */}
                <div className="flex-1 space-y-6">
                  <div className="relative aspect-video rounded-[2.5rem] overflow-hidden bg-slate-100 dark:bg-slate-800 group/img shadow-2xl border-4 border-white dark:border-slate-800">
                    <img src={res.url} className="w-full h-full object-cover" alt="Ergebnis" loading="lazy" />
                    {res.isRefining && (
                      <div className="absolute inset-0 bg-black/50 backdrop-blur-md flex flex-col items-center justify-center text-white gap-3">
                        <Loader2 className="w-10 h-10 animate-spin" />
                        <span className="text-[10px] font-black uppercase tracking-widest">Wird optimiert...</span>
                      </div>
                    )}
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center gap-3">
                      <button onClick={() => handleSave(res)} className={`p-4 rounded-2xl transition-all ${res.isSaved ? 'bg-rose-500 text-white' : 'bg-white text-rose-500 hover:scale-110'}`}><Heart className={`w-6 h-6 ${res.isSaved ? 'fill-current' : ''}`} /></button>
                      <button onClick={() => { const a = document.createElement('a'); a.href = res.url; a.download = 'thumb.png'; a.click(); }} className="p-4 bg-white text-slate-900 rounded-2xl hover:scale-110 transition-all shadow-xl"><Download className="w-6 h-6" /></button>
                    </div>
                    <div className="absolute top-6 left-6 px-4 py-2 bg-emerald-500 text-white text-[9px] font-black uppercase rounded-full shadow-lg flex items-center gap-2">
                       <Sparkles className="w-3 h-3 fill-current" /> High-End Render
                    </div>
                  </div>

                  <div className="p-5 bg-emerald-500/5 dark:bg-emerald-500/10 rounded-3xl border border-emerald-500/10">
                     <div className="flex items-center gap-2 mb-2">
                        <Target className="w-3.5 h-3.5 text-emerald-500" />
                        <span className="text-[10px] font-black uppercase text-emerald-600">CTR-Strategie der KI</span>
                     </div>
                     <p className="text-xs font-bold text-slate-700 dark:text-slate-300 italic leading-relaxed">"{res.optimizedPrompt}"</p>
                  </div>
                </div>

                {/* Refinement Panel */}
                <div className="w-full md:w-64 flex flex-col justify-between">
                  <div className="space-y-4">
                    <div className="flex items-center gap-2">
                      <Zap className="w-4 h-4 text-orange-600" />
                      <h4 className="text-[11px] font-black uppercase text-slate-400 tracking-widest leading-none">Feinschliff</h4>
                    </div>
                    <textarea 
                      value={res.refinementText}
                      onChange={(e) => setResults(prev => prev.map(r => r.id === res.id ? { ...r, refinementText: e.target.value } : r))}
                      placeholder="z.B. Mehr Glanz auf dem Produkt..."
                      className="w-full h-32 bg-slate-50 dark:bg-slate-800/50 border border-black/5 rounded-[2rem] p-5 text-xs font-bold outline-none focus:ring-2 focus:ring-orange-500 resize-none transition-all"
                    />
                    <div className="flex items-center justify-between px-2">
                       <span className="text-[9px] font-black uppercase text-orange-600">5 Credits</span>
                       <button 
                        onClick={() => handleRefine(res.id)}
                        disabled={res.isRefining || !res.refinementText?.trim() || isLowCredits(5)}
                        className="p-3 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-2xl shadow-xl active:scale-[0.98] disabled:opacity-30 transition-all"
                      >
                        <ArrowRight className="w-5 h-5" />
                      </button>
                    </div>
                  </div>

                  <div className="mt-8 pt-6 border-t border-black/5 dark:border-white/10 opacity-40 group-hover/card:opacity-100 transition-opacity">
                     <p className="text-[9px] font-black uppercase text-slate-400 mb-1">Deine Idee</p>
                     <p className="text-[10px] font-bold text-slate-900 dark:text-white truncate">"{res.prompt}"</p>
                  </div>
                </div>
              </div>
            </div>
          ))
        ) : (
          <div className="h-[500px] flex flex-col items-center justify-center text-center p-12 bg-slate-100/50 dark:bg-slate-900/20 rounded-[4rem] border-4 border-dashed border-black/5">
            <div className="w-24 h-24 bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-xl flex items-center justify-center mb-8 gpu-accelerated">
              <ImageIcon className="w-12 h-12 text-slate-300" />
            </div>
            <h3 className="text-3xl font-black mb-4 text-slate-900 dark:text-white">Studio bereit</h3>
            <p className="text-slate-500 dark:text-slate-400 text-lg max-w-sm font-medium leading-relaxed">
              Deine Designs werden hier mit YouTube-optimierter Ästhetik gerendert.
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

import { Wand2, Sparkles, Loader2, Download, Coins, Monitor, Smartphone, Square, Heart, Send, Zap, MessageSquare, ArrowRight, Info, Image as ImageIcon, Lightbulb, Target } from 'lucide-react';
import React, { useState, useEffect } from 'react';
import { generateThumbnail, remakeThumbnail } from '../services/geminiService';
import { ThumbnailStyle, User, Design } from '../types';

interface StudioGenerateProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  onGoToPricing?: () => void;
  onSaveDesign?: (design: Design) => void;
