};

const cleanBase64 = (base64: string): string => {
  return base64.includes(',') ? base64.split(',')[1] : base64;
};

/**
 * Der "Market-Aware Art Director" Schritt.
 * Nutzt Google Search um Trends in der Nische zu finden.
 */
const optimizePromptWithMarketResearch = async (userPrompt: string, style: string, useSearch: boolean) => {
  const ai = getAI();

  let researchData = "";
  let searchSources: any[] = [];

  if (useSearch) {
    // Phase 1: Recherche erfolgreicher Thumbnails in der Nische
    const searchResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Suche nach den aktuell erfolgreichsten YouTube Thumbnails und visuellen Trends für das Thema: "${userPrompt}". 
      Welche Farben, Gesichtsausdrücke und Layouts dominieren gerade?`,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });
    researchData = searchResponse.text;
    searchSources = searchResponse.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Trend Quelle',
      url: chunk.web?.uri || ''
    })).filter((s: any) => s.url) || [];
  }

  // Phase 2: Prompt-Optimierung basierend auf Recherche
  const systemInstruction = `Du bist ein Senior YouTube Art Director. 
  Deine Aufgabe: Erstelle einen Bild-Prompt (Englisch) basierend auf Nutzer-Input und Markttrends.

  RECHERCHE-ERGEBNISSE (falls vorhanden):
  ${researchData}

  DESIGN-REGELN:
  1. ORIENTIERUNG: Wenn Recherche-Daten vorliegen, adaptiere die Farbstimmung und Komposition der Marktführer.
  2. SUBJECT: Zentrales Motiv mit Rim-Lighting und extremer Emotion.
  3. COMPOSITION: Klare Drittel-Regel, Platz für Text.
  4. ANTI-STOCK: Vermeide künstlich wirkende Stock-Fotos. Erzeuge YouTube-Native Ästhetik.

  ANTWORTE NUR ALS JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Erstelle eine Markt-optimierte Thumbnail-Beschreibung für: "${userPrompt}" im Stil "${style}".`,
      config: {
        systemInstruction,
        thinkingConfig: { thinkingBudget: 4000 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            optimizedPrompt: { type: Type.STRING },
            strategy: { type: Type.STRING }
          },
          required: ["optimizedPrompt", "strategy"]
        }
      }
    });
    const parsed = JSON.parse(response.text || '{}');
    return { ...parsed, sources: searchSources };
  } catch (e) {
    console.error("Market Research failed:", e);
    return { optimizedPrompt: userPrompt, strategy: "Standard-Generierung", sources: [] };
  }
};

/**
 * Kern-Funktion zur Bilderzeugung mit modernster Thumbnail-Architektur.
 */
export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9", useMarketResearch: boolean = false) => {
  const ai = getAI();

  // 1. Art Direction & Markt-Check
  const { optimizedPrompt, strategy, sources } = await optimizePromptWithMarketResearch(prompt, style, useMarketResearch);

  // 2. Technischer Wrapper für Thumbnail-Ästhetik
  const thumbnailWrapper = `Professional YouTube Thumbnail, 4K, Highly Detailed, Hyper-realistic, 
    Vibrant Colors, Cinematic Masterpiece, Bold Lighting, Depth of Field, 
    ${optimizedPrompt}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: thumbnailWrapper }] },
      config: { 
        imageConfig: { aspectRatio: aspectRatio as any } 
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return {
        url: `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`,
        optimizedPrompt: strategy,
        sources: sources
      };
    }
    throw new Error("Kein Bild generiert.");
  } catch (e: any) {
    throw new Error(e.message || "Fehler bei der Bilderzeugung.");
  }
};

// ... Rest des Services bleibt gleich ...
export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();
  const instruction = `THUMBNAIL REFINEMENT: Modify the provided thumbnail by applying: "${adjustmentPrompt}". 
  Maintain identity and composition. Improve lighting and rim-light.`;
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: instruction }
        ]
      },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return imagePart?.inlineData ? `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}` : null;
  } catch (e) { return null; }
};

