import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const getMimeType = (base64: string): string => {
  const match = base64.match(/^data:([^;]+);base64,/);
  return match ? match[1] : 'image/png';
};

const cleanBase64 = (base64: string): string => {
  return base64.includes(',') ? base64.split(',')[1] : base64;
};

/**
 * Der "Market-Aware Art Director" Schritt.
 * Nutzt Google Search um Trends und die visuelle Sprache von Top-Creatoren in der Nische zu finden.
 */
const optimizePromptWithMarketResearch = async (userPrompt: string, style: string, useSearch: boolean) => {
  const ai = getAI();

  let researchData = "";
  let searchSources: any[] = [];

  if (useSearch) {
    // Phase 1: Deep Benchmarking - Suche nach den erfolgreichsten Thumbnails in dieser spezifischen Nische
    const searchQuery = `Current viral YouTube thumbnail trends and successful visual patterns for: "${userPrompt}" in 2024/2025`;
    const searchResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: searchQuery,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });
    researchData = searchResponse.text;
    searchSources = searchResponse.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Trend Benchmark',
      url: chunk.web?.uri || ''
    })).filter((s: any) => s.url) || [];
  }

  // Phase 2: Art Direction - Dekonstruktion der Marktführer und Erstellung des neuen Konzepts
  const systemInstruction = `Du bist ein Senior YouTube Art Director und Spezialist für visuelle Psychologie. 
  Deine Aufgabe ist es, einen professionellen Bild-Prompt (Englisch) zu erstellen, der sich an den erfolgreichsten Thumbnails der Branche orientiert.

  RECHERCHE-DATEN DER KONKURRENZ (Benchmarking):
  ${researchData || "Keine spezifischen Marktdaten vorhanden - nutze allgemeine YouTube Best-Practices."}

  STRATEGIE-DIREKTIVEN:
  1. COMPETITIVE MIRRORING: Analysiere die Recherche-Daten. Wenn Top-Videos z.B. knallgelbe Hintergründe oder extreme Close-ups nutzen, integriere diese Muster in den neuen Prompt.
  2. VISUAL HOOK: Erzeuge ein Motiv, das sofort die Aufmerksamkeit stoppt. Rim-Lighting (Glow an Kanten) ist Pflicht zur Abgrenzung.
  3. EMOTIONAL INTENSITY: Gesichter müssen extreme, fast übersteigerte Emotionen zeigen (Micro-Expressions).
  4. LAYOUT: Halte Platz für Text frei (meist linke oder rechte Seite).
  5. QUALITY: Erzwinge "8K resolution, Unreal Engine 5 render style, cinematic lighting, hyper-realistic skin textures".

  ANTWORTE STRENG ALS JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Erstelle eine Markt-optimierte Thumbnail-Strategie und einen detaillierten Bild-Prompt für: "${userPrompt}" im Stil "${style}".`,
      config: {
        systemInstruction,
        thinkingConfig: { thinkingBudget: 4000 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            optimizedPrompt: { 
              type: Type.STRING, 
              description: "Der finale, extrem detaillierte englische Prompt für den Bildgenerator." 
            },
            strategy: { 
              type: Type.STRING, 
              description: "Kurze Erklärung (Deutsch), warum dieses Design basierend auf dem Markt-Benchmark gewählt wurde." 
            }
          },
          required: ["optimizedPrompt", "strategy"]
        }
      }
    });
    const parsed = JSON.parse(response.text || '{}');
    return { ...parsed, sources: searchSources };
  } catch (e) {
    console.error("Market Research failed:", e);
    return { 
      optimizedPrompt: `Professional YouTube Thumbnail for ${userPrompt}, high quality, cinematic lighting`, 
      strategy: "Basierend auf bewährten YouTube Standards (Hoher Kontrast & Subjekt-Fokus).", 
      sources: [] 
    };
  }
};

/**
 * Kern-Funktion zur Bilderzeugung mit modernster Thumbnail-Architektur.
 */
export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9", useMarketResearch: boolean = false) => {
  const ai = getAI();

  // 1. Art Direction & Markt-Check (Benchmarking)
  const { optimizedPrompt, strategy, sources } = await optimizePromptWithMarketResearch(prompt, style, useMarketResearch);

  // 2. Technischer Wrapper für Thumbnail-Ästhetik
  const thumbnailWrapper = `Professional Viral YouTube Thumbnail Frame, Masterpiece Quality, 
    Extreme Detail, Vibrant Cinematic Colors, Studio Lighting, Rim-Light, 
    ${optimizedPrompt}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: thumbnailWrapper }] },
      config: { 
        imageConfig: { aspectRatio: aspectRatio as any } 
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return {
        url: `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`,
        optimizedPrompt: strategy,
        sources: sources
      };
    }
    throw new Error("Kein Bild generiert.");
  } catch (e: any) {
    throw new Error(e.message || "Fehler bei der Bilderzeugung.");
  }
};

/**
 * Überarbeitet ein bestehendes Thumbnail mit Fokus auf CTR-Details.
 */
export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();
  const instruction = `THUMBNAIL REFINEMENT: Enhance the provided YouTube thumbnail. 
  Modification: "${adjustmentPrompt}". 
  Ensure consistent face/identity. Improve rim-lighting, saturation, and contrast for better mobile readability. 
  Maintain the 16:9 professional cinematic composition.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: instruction }
        ]
      },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
    }
    return null;
  } catch (e) { return null; }
};

/**
 * Übernimmt den künstlerischen Stil eines Referenzbildes.
 */
export const cloneStyle = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();
  const instruction = `THUMBNAIL STYLE TRANSFER: Use the uploaded image as a strict VISUAL REFERENCE for lighting, color grading, and composition style. 
  Subject matter of the NEW image: "${adjustmentPrompt}". 
  The new image must look like it belongs to the same high-end YouTube channel as the reference. 
  Ensure 4K professional output.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: instruction }
        ]
      },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`;
    }
    return null;
  } catch (e) { return null; }
};

