import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const getMimeType = (base64: string): string => {
  const match = base64.match(/^data:([^;]+);base64,/);
  return match ? match[1] : 'image/png';
};

const cleanBase64 = (base64: string): string => {
  return base64.includes(',') ? base64.split(',')[1] : base64;
};

/**
 * Schnelle Optimierung für Echtzeit-Vorschläge.
 * Ziel: Einen einfachen User-Text in einen High-CTR Thumbnail-Prompt verwandeln.
 */
export const getQuickRefinement = async (userPrompt: string, style: string) => {
  if (userPrompt.trim().length < 3) return "";

  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Handle als "YouTube Thumbnail Prompt Engineer". 
      Transformiere die Idee: "${userPrompt}" in einen extrem visuellen, professionellen Thumbnail-Prompt (Englisch).

      KRITERIEN FÜR THUMBNAILS:
      - Nutze Begriffe wie: "extreme close-up", "vibrant cinematic lighting", "rim lighting", "hyper-realistic textures".
      - Erzeuge emotionale Tiefe: "shocked expression", "intense focus", "aggressive action".
      - Achte auf Bild-Tiefe: "blurred background", "bokeh", "foreground object scale".
      - Stil: "${style}".
      - Länge: Max 30 Wörter.
      - Regel: Antworte NUR mit dem Prompt-Text.`,
    });
    return response.text?.replace(/^"|"$/g, '') || "";
  } catch (e) {
    return "";
  }
};

/**
 * Der "Market-Aware Art Director" Schritt.
 * Tiefe Analyse der Markt-Trends zur Erzeugung konkurrenzfähiger Designs.
 */
const optimizePromptWithMarketResearch = async (userPrompt: string, style: string, useSearch: boolean) => {
  const ai = getAI();

  let researchData = "";
  let searchSources: any[] = [];

  if (useSearch) {
    const searchQuery = `Viral YouTube thumbnail visual trends and click-patterns for niche: "${userPrompt}" 2024 2025`;
    const searchResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: searchQuery,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });
    researchData = searchResponse.text;
    searchSources = searchResponse.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Market Insight',
      url: chunk.web?.uri || ''
    })).filter((s: any) => s.url) || [];
  }

  const systemInstruction = `Du bist ein Master-Designer für YouTube Thumbnails mit Fokus auf CTR-Psychologie.
  Deine Aufgabe: Erstelle eine Design-Strategie und einen Bild-Prompt, der Klicks erzwingt.

  THUMBNAIL-GESETZE (STRENG EINHALTEN):
  1. SUBJEKT-DOMINANZ: Das Hauptmotiv muss groß und scharf im Vordergrund stehen.
  2. RIM-LIGHTING: Das Subjekt braucht ein leuchtendes Konturlicht zur Abhebung vom Hintergrund.
  3. KOMPOSITION: Lass Platz für Text (links oder rechts). Nutze "Rule of Thirds".
  4. FARBEN: Nutze komplementäre Kontraste (z.B. Blau/Orange).
  5. EMOTION: Wenn Menschen im Bild sind, müssen Gesichtsausdrücke überzeichnet und intensiv sein.
  6. QUALITÄT: Nutze Begriffe wie "8k photo, Unreal Engine 5 style, cinematic color grading, sharp focus".

  KONTEXT DER KONKURRENZ:
  ${researchData || "Nutze allgemeine High-End YouTube Standards."}

  ANTWORTE STRENG ALS JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Erstelle einen klickstarken Thumbnail-Prompt für: "${userPrompt}" (Stil: ${style}).`,
      config: {
        systemInstruction,
        thinkingConfig: { thinkingBudget: 4000 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            optimizedPrompt: { type: Type.STRING },
            strategy: { type: Type.STRING }
          },
          required: ["optimizedPrompt", "strategy"]
        }
      }
    });
    const parsed = JSON.parse(response.text || '{}');
    return { ...parsed, sources: searchSources };
  } catch (e) {
    return { 
      optimizedPrompt: `Professional YouTube Thumbnail, ${userPrompt}, high quality, cinematic`, 
      strategy: "Optimiert für Standard-CTR.", 
      sources: [] 
    };
  }
};

/**
 * Finaler Generierungsprozess.
 */
export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9", useMarketResearch: boolean = false) => {
  const ai = getAI();

  const { optimizedPrompt, strategy, sources } = await optimizePromptWithMarketResearch(prompt, style, useMarketResearch);

  // Der finale Master-Wrapper, der die technische Exzellenz garantiert.
  const finalThumbnailPrompt = `Masterpiece Professional YouTube Thumbnail, Cinematic 8k photography, 
    Extreme Detail, Vibrant saturated colors, Studio Lighting, 3D Render Style, 
    Hyper-realistic textures, Sharp focus on main subject, ${optimizedPrompt}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: finalThumbnailPrompt }] },
      config: { 
        imageConfig: { aspectRatio: aspectRatio as any } 
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return {
        url: `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`,
        optimizedPrompt: strategy,
        sources: sources
      };
    }
    throw new Error("Generierung fehlgeschlagen.");
  } catch (e: any) {
    throw new Error(e.message || "Bilderzeugungs-Fehler.");
  }
};

export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();
  const instruction = `ENHANCE YOUTUBE THUMBNAIL: Modify the image. Adjustment: "${adjustmentPrompt}". 
  Ensure extreme professional quality, better rim-lighting, and vibrant colors suitable for YouTube CTR. 
  Keep the main subject consistent.`;
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: instruction }
        ]
      },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return imagePart?.inlineData ? `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}` : null;
  } catch (e) { return null; }
};

