import React, { useState, useEffect } from 'react';
import { User, Design, SavedPrompt } from './types';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { Pricing } from './components/Pricing';
import { Reviews } from './components/Reviews';
import { AuthModal } from './components/AuthModal';
import { Examples } from './components/Examples';
import { StudioSelection } from './components/StudioSelection';
import { StudioGenerate } from './components/StudioGenerate';
import { StudioChannelAnalyze } from './components/StudioChannelAnalyze';
import { StudioAnalyze } from './components/StudioAnalyze';
import { StudioRemake } from './components/StudioRemake';
import { StudioFavorites } from './components/StudioFavorites';
import { HowItWorks } from './components/HowItWorks';
import { ThumbnailShowcase } from './components/ThumbnailShowcase';
import { ComparisonTable } from './components/ComparisonTable';
import { Sidebar } from './components/Sidebar';
import { StudioTour } from './components/StudioTour';
import { Footer } from './components/Footer';
import { CheckCircle, ArrowLeft } from 'lucide-react';
import { PricingPlan } from './constants';

type MainView = 'home' | 'pricing' | 'reviews' | 'examples' | 'studio';
type StudioView = 'dashboard' | 'generate' | 'channel' | 'analyze' | 'clone' | 'favorites';

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [studioView, setStudioView] = React.useState<StudioView>('dashboard');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [purchaseSuccess, setPurchaseSuccess] = useState<{ planName: string, amount: number } | null>(null);
  const [showTour, setShowTour] = useState(false);
  const [isNavigating, setIsNavigating] = useState(false);
  const [prefilledImageForRemake, setPrefilledImageForRemake] = useState<string | null>(null);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') setIsDarkMode(false);

    // Load state from local storage
    const savedUser = localStorage.getItem('thumbcraft_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  // Sync user state to localStorage
  useEffect(() => {
    if (user) {
      localStorage.setItem('thumbcraft_user', JSON.stringify(user));
    }
  }, [user]);

  const handleLogin = (email: string) => {
    const newUser: User = { 
      id: '1', 
      email: email, 
      name: email.split('@')[0], 
      credits: 30, 
      isLoggedIn: true,
      plan: 'Starter',
      savedDesigns: [],
      savedPrompts: []
    };
    setUser(newUser);
    setIsAuthOpen(false);
    setCurrentView('studio');
    setStudioView('dashboard');

    const hasSeenTour = localStorage.getItem('hasSeenStudioTour');
    if (!hasSeenTour) {
      setTimeout(() => setShowTour(true), 1500);
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('thumbcraft_user');
    setCurrentView('home');
    setStudioView('dashboard');
    setShowTour(false);
  };

  const toggleTheme = () => setIsDarkMode(prev => !prev);

  const useCredits = (amount: number): boolean => {
    if (!user || user.credits < amount) {
      setCurrentView('pricing');
      return false;
    }
    setUser({ ...user, credits: user.credits - amount });
    return true;
  };

  const handlePurchase = (plan: PricingPlan) => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    setUser({ ...user, credits: user.credits + plan.credits, plan: plan.name as any });
    setPurchaseSuccess({ planName: plan.name, amount: plan.credits });
    setTimeout(() => setPurchaseSuccess(null), 5000);
    setCurrentView('studio');
  };

  const handleSaveDesign = (design: Design) => {
    if (!user) return;
    const favorites = user.savedDesigns || [];
    if (favorites.some(f => f.id === design.id)) return;

    setUser({
      ...user,
      savedDesigns: [...favorites, design]
    });
  };

  const handleSavePrompt = (promptText: string, style: string) => {
    if (!user || !promptText.trim()) return;
    const saved = user.savedPrompts || [];
    if (saved.some(p => p.text === promptText)) return;

    const newPrompt: SavedPrompt = {
      id: Math.random().toString(36).substr(2, 9),
      text: promptText,
      style: style,
      createdAt: new Date().toISOString()
    };

    setUser({
      ...user,
      savedPrompts: [newPrompt, ...saved]
    });
  };

  const handleDeletePrompt = (id: string) => {
    if (!user) return;
    setUser({
      ...user,
      savedPrompts: (user.savedPrompts || []).filter(p => p.id !== id)
    });
  };

  const handleRemoveFavorite = (id: string) => {
    if (!user) return;
    setUser({
      ...user,
      savedDesigns: (user.savedDesigns || []).filter(d => d.id !== id)
    });
  };

  const handleModifyFavorite = (design: Design) => {
    setPrefilledImageForRemake(design.imageUrl);
    setStudioView('clone');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleNavigate = (view: MainView) => {
    if (view === currentView) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    if (view === 'studio' && !user) {
      setIsAuthOpen(true);
      return;
    }

    setIsNavigating(true);
    setTimeout(() => {
      setCurrentView(view);
      if (view === 'studio') {
        setStudioView('dashboard');
        const hasSeenTour = localStorage.getItem('hasSeenStudioTour');
        if (user && !hasSeenTour) {
          setTimeout(() => setShowTour(true), 1000);
        }
      } else {
        setShowTour(false);
      }
      window.scrollTo({ top: 0, behavior: 'smooth' });
      setIsNavigating(false);
    }, 200);
  };

  const handleBack = () => {
    if (currentView === 'studio' && studioView !== 'dashboard') {
      setStudioView('dashboard');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
      handleNavigate('home');
    }
  };

  const handleStartCreating = () => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    handleNavigate('studio');
  };

  const handleSelectStudioTool = (tool: StudioView) => {
    setStudioView(tool);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const completeTour = () => {
    setShowTour(false);
    localStorage.setItem('hasSeenStudioTour', 'true');
  };

  return (
    <div className={`min-h-screen transition-colors duration-500 selection:bg-teal-500 selection:text-white ${isDarkMode ? 'bg-[#020617] text-slate-100' : 'bg-slate-50 text-slate-900'} relative`}>

      <div className="mesh-gradient opacity-80"></div>

      <Navbar 
        user={user} 
        currentView={currentView}
        onNavigate={handleNavigate} 
        onLoginClick={() => setIsAuthOpen(true)} 
        onLogout={handleLogout}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
      />

      <main className={`relative z-10 transition-all duration-300 ${currentView === 'studio' ? 'lg:pl-72' : ''} ${isNavigating ? 'opacity-0 blur-sm' : 'opacity-100 blur-0'}`}>

        {/* Global Back Button */}
        {currentView !== 'home' && (
          <div className="fixed top-28 right-4 lg:right-12 z-50 animate-in fade-in slide-in-from-right-4 duration-500">
            <button 
              onClick={handleBack}
              className="flex items-center gap-2 px-5 py-2.5 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border border-black/5 dark:border-white/10 rounded-2xl shadow-xl hover:shadow-teal-500/10 hover:border-teal-500/30 group transition-all active:scale-95"
            >
              <ArrowLeft className="w-4 h-4 text-teal-600 group-hover:-translate-x-1 transition-transform" />
              <span className="text-xs font-black uppercase tracking-widest text-slate-900 dark:text-white">Zurück</span>
            </button>
          </div>
        )}

        {currentView === 'home' && (
          <div className="animate-in fade-in duration-500">
            <Hero onStartCreating={handleStartCreating} onViewPricing={() => handleNavigate('pricing')} />
            <HowItWorks onExplore={() => handleNavigate('examples')} />
            <ThumbnailShowcase onStartCreating={handleStartCreating} />
            <ComparisonTable />
            <Reviews />
            <Pricing onPurchase={handlePurchase} />
            <Footer />
          </div>
        )}

        {currentView === 'studio' && (
          <div className="pt-24 min-h-screen">
            <Sidebar 
              activeView={studioView} 
              onSelect={setStudioView} 
              user={user}
              onUpgrade={() => handleNavigate('pricing')}
            />

            <div className="p-4 lg:p-12 pb-32">
              <div key={studioView} className="animate-in fade-in slide-up duration-400">
                {studioView === 'dashboard' && (
                  <StudioSelection 
                    user={user} 
                    onSelectMode={(mode) => handleSelectStudioTool(mode as StudioView)} 
                    onGoToPricing={() => handleNavigate('pricing')}
                  />
                )}

                {studioView === 'generate' && (
                  <StudioGenerate 
                    useCredits={useCredits} 
                    user={user} 
                    onGoToPricing={() => handleNavigate('pricing')} 
                    onSaveDesign={handleSaveDesign}
                    onSavePrompt={handleSavePrompt}
                    onDeletePrompt={handleDeletePrompt}
                  />
                )}

                {studioView === 'clone' && (
                  <StudioRemake 
                    useCredits={useCredits} 
                    user={user} 
                    isCloneMode={true} 
                    prefilledImage={prefilledImageForRemake}
                    onSaveDesign={handleSaveDesign}
                  />
                )}

                {studioView === 'analyze' && (
                  <StudioAnalyze useCredits={useCredits} user={user} />
                )}

                {studioView === 'channel' && (
                  <StudioChannelAnalyze useCredits={useCredits} user={user} />
                )}

                {studioView === 'favorites' && (
                  <StudioFavorites 
                    designs={user?.savedDesigns || []} 
                    onRemove={handleRemoveFavorite}
                    onModify={handleModifyFavorite}
                  />
                )}
              </div>
            </div>
          </div>
        )}

        {currentView === 'pricing' && (
          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Pricing onPurchase={handlePurchase} />
            <Footer />
          </div>
        )}

        {currentView === 'reviews' && (
          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Reviews />
            <Footer />
          </div>
        )}

        {currentView === 'examples' && (
          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Examples onNavigateToStudio={handleStartCreating} />
            <Footer />
          </div>
        )}
      </main>

      {showTour && currentView === 'studio' && <StudioTour onComplete={completeTour} />}

      {isAuthOpen && (
        <AuthModal 
          isOpen={isAuthOpen} 
          onClose={() => setIsAuthOpen(false)} 
          onLogin={handleLogin} 
        />
      )}

      {purchaseSuccess && (
        <div className="fixed bottom-12 left-1/2 -translate-x-1/2 z-[100] bg-emerald-600 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-bottom-8 duration-500">
          <CheckCircle className="w-6 h-6" />
          <div>
            <p className="text-sm font-black uppercase tracking-widest">Kauf erfolgreich!</p>
            <p className="text-xs font-bold opacity-80">{purchaseSuccess.amount} Credits zum {purchaseSuccess.planName}-Plan hinzugefügt.</p>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

import { Wand2, Sparkles, Loader2, Download, Coins, Monitor, Smartphone, Square, Heart, Send, Zap, MessageSquare, ArrowRight, Info, Image as ImageIcon, Lightbulb, Target, Globe, ExternalLink, Search, Stars, Bookmark, Trash2, History } from 'lucide-react';
import React, { useState, useEffect, useRef } from 'react';
import { generateThumbnail, remakeThumbnail, getQuickRefinement } from '../services/geminiService';
import { ThumbnailStyle, User, Design } from '../types';

interface StudioGenerateProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  onGoToPricing?: () => void;
  onSaveDesign?: (design: Design) => void;
  onSavePrompt?: (text: string, style: string) => void;
  onDeletePrompt?: (id: string) => void;
}

const STYLE_SUGGESTIONS: Record<ThumbnailStyle, string[]> = {
  [ThumbnailStyle.CLEAN]: ["Apple-Look", "Studio Softbox", "Pastell", "4K-Face"],
  [ThumbnailStyle.BEAST]: ["Shocked Face", "Glow Effect", "Action-Pfeile", "Dramatischer Zoom"],
  [ThumbnailStyle.MINIMAL]: ["Negative Space", "Dezente Textur", "Fokus-Spotlight"],
  [ThumbnailStyle.GAMING]: ["Neon RGB", "Speed Lines", "Cyberpunk", "Gaming-Peripherie"],
  [ThumbnailStyle.TECH]: ["Makro-Shot", "Aluminium-Textur", "Blueprint-Elemente", "Anodized Finish"],
  [ThumbnailStyle.VLOG]: ["Golden Hour", "Authentisch", "Film-Grain", "Warme Hauttöne", "Selfie-Style"],
  [ThumbnailStyle.REACTION]: ["Extreme Mimik", "Rote Pfeile", "Mouth-Open", "Starker Kontrast"],
  [ThumbnailStyle.FITNESS]: ["Sweat Texture", "Harte Schatten", "Gym-Atmosphäre", "Grit & Determination"],
  [ThumbnailStyle.BUSINESS]: ["Office Background", "Seriöses Lighting", "Autoritärer Look", "Stock-Market Chart"]
};

const ASPECT_RATIOS = [
  { id: '16:9', label: 'Video (16:9)', icon: Monitor },
  { id: '9:16', label: 'Shorts (9:16)', icon: Smartphone },
  { id: '1:1', label: 'Post (1:1)', icon: Square },
];

interface GeneratedResult {
  id: string;
  url: string;
  prompt: string;
  optimizedPrompt: string;
  isSaved?: boolean;
  isPromptSaved?: boolean;
  isRefining?: boolean;
  refinementText?: string;
  sources?: {title: string, url: string}[];
}

export const StudioGenerate: React.FC<StudioGenerateProps> = ({ useCredits, user, onGoToPricing, onSaveDesign, onSavePrompt, onDeletePrompt }) => {
  const [prompt, setPrompt] = useState('');
  const [aiSuggestion, setAiSuggestion] = useState('');
  const [isSuggesting, setIsSuggesting] = useState(false);
  const [style, setStyle] = useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [aspectRatio, setAspectRatio] = useState('16:9');
  const [useMarketResearch, setUseMarketResearch] = useState(false);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);

  const suggestionTimeoutRef = useRef<any>(null);

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  // Real-time Refinement Logic (Debounced)
  useEffect(() => {
    if (suggestionTimeoutRef.current) clearTimeout(suggestionTimeoutRef.current);

    if (prompt.trim().length < 5) {
      setAiSuggestion('');
      return;
    }

    setIsSuggesting(true);
    suggestionTimeoutRef.current = setTimeout(async () => {
      const refined = await getQuickRefinement(prompt, style);
      setAiSuggestion(refined);
      setIsSuggesting(false);
    }, 800);

    return () => {
      if (suggestionTimeoutRef.current) clearTimeout(suggestionTimeoutRef.current);
    };
  }, [prompt, style]);

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 3;
          if (prev < 70) return prev + 1.5;
          if (prev < 95) return prev + 0.5;
          return prev;
        });

        const normalTexts = ["Art Direction checkt Prompt...", "CTR-Strategie wird berechnet...", "Thumbnail wird gerendert...", "Licht-Korrekturen laufen..."];
        const researchTexts = ["Markt-Benchmarking läuft...", "Analysiere Top-Creatoren...", "Kopiere visuelle Trends...", "Optimiere Nischen-CTR...", "Rendere Finales Design..."];

        const texts = useMarketResearch ? researchTexts : normalTexts;
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress, useMarketResearch]);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    const cost = useMarketResearch ? 25 : 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt, sources } = await generateThumbnail(prompt, style, aspectRatio, useMarketResearch);
      useCredits(cost);
      setResults(prev => [{
        id: `res-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        url,
        prompt: prompt,
        optimizedPrompt: optimizedPrompt,
        sources: sources,
        refinementText: '',
        isPromptSaved: false
      }, ...prev]);
      // setPrompt(''); // Wir lassen den Prompt stehen, falls der User ihn speichern will
      setProgress(100);
    } catch (err) {
      alert("Generierung fehlgeschlagen.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

  const handleRefine = async (resultId: string) => {
    const result = results.find(r => r.id === resultId);
    if (!result || !result.refinementText?.trim()) return;

    const cost = 5;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setResults(prev => prev.map(r => r.id === resultId ? { ...r, isRefining: true } : r));

    try {
      const refinedUrl = await remakeThumbnail(result.url, result.refinementText);
      useCredits(cost);
      if (refinedUrl) {
        setResults(prev => prev.map(r => r.id === resultId ? { 
          ...r, 
          url: refinedUrl, 
          isRefining: false, 
          refinementText: '',
          prompt: `${r.prompt} (+ ${result.refinementText})`
        } : r));
      }
    } catch (err) {
      alert("Fehler beim Refinement.");
      setResults(prev => prev.map(r => r.id === resultId ? { ...r, isRefining: false } : r));
    }
  };

  const handleSave = (res: GeneratedResult) => {
    onSaveDesign?.({
      id: res.id,
      imageUrl: res.url,
      prompt: res.prompt,
      createdAt: new Date().toISOString(),
      style,
      aspectRatio
    });
    setResults(prev => prev.map(r => r.id === res.id ? { ...r, isSaved: true } : r));
  };

  const handlePromptLibrarySave = (promptToSave: string, styleToSave: string, resultId?: string) => {
    onSavePrompt?.(promptToSave, styleToSave);
    if (resultId) {
      setResults(prev => prev.map(r => r.id === resultId ? { ...r, isPromptSaved: true } : r));
    }
  };

  const applyAiSuggestion = () => {
    if (aiSuggestion) {
      setPrompt(aiSuggestion);
      setAiSuggestion('');
    }
  };

  const loadSavedPrompt = (saved: any) => {
    setPrompt(saved.text);
    setStyle(saved.style as ThumbnailStyle);
  };

  return (
    <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-12 animate-in fade-in duration-500">

      {/* Configuration Sidebar */}
      <div className="w-full lg:w-[420px] space-y-6">
        <div className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl sticky top-28 gpu-accelerated overflow-hidden">
          <div className="flex justify-between items-center mb-8">
            <h2 className="text-2xl font-black flex items-center gap-3 text-slate-900 dark:text-white">
              <Wand2 className="w-6 h-6 text-orange-500" /> Designer Lab
            </h2>
            <div className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full bg-amber-500/10 text-amber-500 border border-amber-500/10">
              <Coins className="w-3.5 h-3.5" /> {useMarketResearch ? '25' : '10'} Credits
            </div>
          </div>

          <div className="space-y-6">

            {/* SAVED PROMPTS LIBRARY SECTION */}
            {user?.savedPrompts && user.savedPrompts.length > 0 && (
              <div className="animate-in slide-in-from-top-2 duration-300">
                <div className="flex items-center justify-between mb-3 px-1">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">
                    <Bookmark className="w-3 h-3 text-orange-500 fill-current" /> Meine Bibliothek
                  </label>
                  <span className="text-[8px] font-bold text-slate-300">{user.savedPrompts.length} Vorlagen</span>
                </div>
                <div className="flex gap-3 overflow-x-auto pb-4 no-scrollbar -mx-2 px-2 snap-x">
                  {user.savedPrompts.map((p) => (
                    <button 
                      key={p.id}
                      onClick={() => loadSavedPrompt(p)}
                      className="flex-shrink-0 w-48 p-4 bg-slate-50 dark:bg-slate-800/80 border border-black/5 dark:border-white/5 rounded-2xl hover:border-orange-500/50 transition-all text-left group/lib snap-center relative"
                    >
                      <p className="text-[10px] font-bold text-slate-700 dark:text-slate-300 line-clamp-2 leading-relaxed mb-2">"{p.text}"</p>
                      <div className="flex items-center justify-between mt-auto">
                        <span className="text-[8px] font-black uppercase px-2 py-0.5 bg-orange-500/10 text-orange-600 rounded-md">{p.style}</span>
                        <button 
                          onClick={(e) => { e.stopPropagation(); onDeletePrompt?.(p.id); }}
                          className="p-1.5 text-slate-300 hover:text-red-500 opacity-0 group-hover/lib:opacity-100 transition-opacity"
                        >
                          <Trash2 className="w-3 h-3" />
                        </button>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div>
              <div className="flex items-center justify-between mb-3 px-1">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Deine Video-Idee</label>
                {prompt.length > 10 && (
                   <button 
                    onClick={() => handlePromptLibrarySave(prompt, style)}
                    className="text-[9px] font-black uppercase tracking-widest text-orange-600 flex items-center gap-1 hover:underline"
                   >
                     <Bookmark className="w-3 h-3" /> Als Vorlage sichern
                   </button>
                )}
              </div>
              <div className="relative group/prompt">
                <textarea 
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  placeholder="Beschreibe das Hauptmotiv (z.B. Creator testet krasses Gadget)..."
                  className="w-full h-40 bg-slate-50 dark:bg-slate-800/50 border border-black/5 dark:border-white/5 rounded-3xl p-5 focus:ring-2 focus:ring-orange-500 outline-none transition-all resize-none text-sm font-medium shadow-inner"
                />

                {/* AI REAL-TIME SUGGESTION FIELD */}
                {(isSuggesting || aiSuggestion) && (
                  <div className="mt-3 animate-in slide-in-from-top-2 duration-300">
                    <button 
                      onClick={applyAiSuggestion}
                      disabled={isSuggesting}
                      className={`w-full p-4 rounded-2xl border flex flex-col items-start gap-2 transition-all relative overflow-hidden group/sug ${
                        isSuggesting 
                          ? 'bg-slate-50 dark:bg-slate-800 border-dashed border-slate-200 dark:border-slate-700 opacity-60' 
                          : 'bg-indigo-600/5 dark:bg-indigo-500/10 border-indigo-500/30 hover:bg-indigo-600/10 hover:border-indigo-500 shadow-lg shadow-indigo-500/5'
                      }`}
                    >
                      <div className="flex items-center gap-2">
                        {isSuggesting ? (
                          <Loader2 className="w-3 h-3 text-indigo-500 animate-spin" />
                        ) : (
                          <Stars className="w-3.5 h-3.5 text-indigo-500 fill-indigo-500" />
                        )}
                        <span className="text-[10px] font-black uppercase tracking-widest text-indigo-600 dark:text-indigo-400">KI-Optimierter Prompt</span>
                        {!isSuggesting && (
                          <span className="text-[8px] font-bold text-slate-400 ml-auto group-hover/sug:text-indigo-500 transition-colors">KLICK ZUM ÜBERNEHMEN</span>
                        )}
                      </div>

                      {isSuggesting ? (
                        <div className="w-full space-y-2">
                          <div className="h-2 w-3/4 bg-slate-200 dark:bg-slate-700 rounded-full animate-pulse" />
                          <div className="h-2 w-1/2 bg-slate-200 dark:bg-slate-700 rounded-full animate-pulse" />
                        </div>
                      ) : (
                        <p className="text-[11px] font-bold text-slate-700 dark:text-slate-300 text-left italic leading-relaxed line-clamp-2">
                          "{aiSuggestion}"
                        </p>
                      )}
                    </button>
                  </div>
                )}
              </div>

              <div className="flex flex-wrap gap-2 mt-4">
                {STYLE_SUGGESTIONS[style].map((s, i) => (
                  <button key={i} onClick={() => setPrompt(prev => prev + " " + s)} className="px-3 py-1.5 bg-slate-100 dark:bg-slate-800 rounded-xl text-[10px] font-black text-slate-500 hover:bg-orange-500 hover:text-white transition-colors">+ {s}</button>
                ))}
              </div>
            </div>

            <div className={`p-4 border rounded-2xl flex items-center justify-between transition-all ${useMarketResearch ? 'bg-blue-600/10 border-blue-500/50' : 'bg-slate-500/5 border-black/5'}`}>
              <div className="flex items-center gap-3">
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${useMarketResearch ? 'bg-blue-600 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}`}>
                  <Search className="w-5 h-5" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[10px] font-black uppercase tracking-widest text-slate-900 dark:text-white">Trend-Benchmarking</span>
                  <span className="text-[9px] text-slate-500 font-bold">Wettbewerber-Stile kopieren</span>
                </div>
              </div>
              <button 
                onClick={() => setUseMarketResearch(!useMarketResearch)}
                className={`w-12 h-6 rounded-full transition-all relative ${useMarketResearch ? 'bg-orange-600' : 'bg-slate-200 dark:bg-slate-700'}`}
              >
                <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${useMarketResearch ? 'left-7' : 'left-1'}`} />
              </button>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-3">
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500">Format</label>
                <div className="grid grid-cols-3 gap-2">
                  {ASPECT_RATIOS.map(r => (
                    <button key={r.id} onClick={() => setAspectRatio(r.id)} className={`p-2.5 rounded-xl border flex flex-col items-center gap-1 transition-all ${aspectRatio === r.id ? 'bg-orange-600 border-orange-600 text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-800 border-transparent text-slate-400'}`}>
                      <r.icon className="w-4 h-4" />
                      <span className="text-[8px] font-black">{r.id}</span>
                    </button>
                  ))}
                </div>
              </div>
              <div className="space-y-3">
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500">Stil</label>
                <select value={style} onChange={(e) => setStyle(e.target.value as ThumbnailStyle)} className="w-full h-[52px] bg-slate-50 dark:bg-slate-800/50 border border-black/5 rounded-xl px-4 text-xs font-black uppercase outline-none">
                  {Object.values(ThumbnailStyle).map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
            </div>

            <div className="pt-4">
              {loading ? (
                <div className="space-y-3 animate-in fade-in">
                  <div className="flex justify-between text-[10px] font-black uppercase text-orange-600 tracking-widest">
                    <span className="flex items-center gap-2"><Loader2 className="w-3 h-3 animate-spin" /> {statusText}</span>
                    <span>{Math.round(progress)}%</span>
                  </div>
                  <div className="h-1.5 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                    <div className="h-full bg-orange-600 transition-all duration-300" style={{ width: `${progress}%` }} />
                  </div>
                </div>
              ) : (
                <button 
                  onClick={handleGenerate}
                  disabled={!prompt.trim() || isLowCredits(useMarketResearch ? 25 : 10)}
                  className="w-full py-5 bg-orange-600 hover:bg-orange-700 text-white rounded-[2rem] font-black text-lg shadow-xl shadow-orange-600/20 flex items-center justify-center gap-3 transition-all active:scale-[0.98] disabled:opacity-50"
                >
                  <Zap className="w-6 h-6 fill-current" /> Thumbnail schmieden
                </button>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Results Feed */}
      <div className="flex-1 space-y-10 min-h-[500px]">
        {results.length > 0 ? (
          results.map((res) => (
            <div key={res.id} className="bg-white dark:bg-slate-900 rounded-[3.5rem] border border-black/5 dark:border-white/5 p-8 shadow-2xl animate-in fade-in duration-500 relative group/card content-auto gpu-accelerated">
              <div className="flex flex-col md:flex-row gap-10">

                {/* Image Section */}
                <div className="flex-1 space-y-6">
                  <div className="relative aspect-video rounded-[2.5rem] overflow-hidden bg-slate-100 dark:bg-slate-800 group/img shadow-2xl border-4 border-white dark:border-slate-800">
                    <img src={res.url} className="w-full h-full object-cover" alt="Ergebnis" loading="lazy" />
                    {res.isRefining && (
                      <div className="absolute inset-0 bg-black/50 backdrop-blur-md flex flex-col items-center justify-center text-white gap-3">
                        <Loader2 className="w-10 h-10 animate-spin" />
                        <span className="text-[10px] font-black uppercase tracking-widest">Wird optimiert...</span>
                      </div>
                    )}
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center gap-3">
                      <button 
                        onClick={() => handleSave(res)} 
                        className={`p-4 rounded-2xl transition-all ${res.isSaved ? 'bg-rose-500 text-white' : 'bg-white text-rose-500 hover:scale-110'}`}
                        title="In Design-Favoriten speichern"
                      >
                        <Heart className={`w-6 h-6 ${res.isSaved ? 'fill-current' : ''}`} />
                      </button>

                      <button 
                        onClick={() => handlePromptLibrarySave(res.prompt, style, res.id)} 
                        className={`p-4 rounded-2xl transition-all ${res.isPromptSaved ? 'bg-orange-500 text-white' : 'bg-white text-orange-500 hover:scale-110'}`}
                        title="Prompt in Bibliothek sichern"
                      >
                        <Bookmark className={`w-6 h-6 ${res.isPromptSaved ? 'fill-current' : ''}`} />
                      </button>

                      <button onClick={() => { const a = document.createElement('a'); a.href = res.url; a.download = 'thumb.png'; a.click(); }} className="p-4 bg-white text-slate-900 rounded-2xl hover:scale-110 transition-all shadow-xl" title="Download"><Download className="w-6 h-6" /></button>
                    </div>
                  </div>

                  <div className="p-6 bg-emerald-500/5 dark:bg-emerald-500/10 rounded-3xl border border-emerald-500/10 relative overflow-hidden">
                     <div className="absolute top-0 right-0 p-4 opacity-5"><Target className="w-20 h-20" /></div>
                     <div className="flex items-center gap-2 mb-3">
                        <Sparkles className="w-4 h-4 text-emerald-500" />
                        <span className="text-[10px] font-black uppercase text-emerald-600 tracking-widest">Design-Strategie (Benchmark)</span>
                     </div>
                     <p className="text-xs font-bold text-slate-700 dark:text-slate-300 italic leading-relaxed relative z-10">
                       {res.optimizedPrompt}
                     </p>
                  </div>

                  {res.sources && res.sources.length > 0 && (
                    <div className="p-6 bg-blue-500/5 dark:bg-blue-500/10 rounded-3xl border border-blue-500/10">
                       <div className="flex items-center gap-2 mb-4">
                          <Globe className="w-4 h-4 text-blue-500" />
                          <span className="text-[10px] font-black uppercase text-blue-600 tracking-widest">Nischen-Analysen & Referenzen</span>
                       </div>
                       <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                          {res.sources.map((s, i) => (
                            <a key={i} href={s.url} target="_blank" className="px-4 py-2.5 bg-white dark:bg-slate-800 rounded-xl text-[9px] font-bold flex items-center justify-between border border-black/5 hover:border-blue-500 hover:shadow-lg transition-all group/link">
