           <div className="p-8 bg-white dark:bg-slate-900 glass-card rounded-[3rem] flex items-center gap-6 group hover:neon-glow-orange transition-all duration-500">
              <div className="w-14 h-14 bg-orange-600 text-white rounded-[1.5rem] flex items-center justify-center shadow-2xl group-hover:scale-110 transition-transform">
                 <TrendingUp className="w-7 h-7" />
              </div>
              <div>
                 <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">CTR Durchschnitt</p>
                 <p className="text-3xl font-black text-slate-900 dark:text-white">+4.2% <span className="text-emerald-500 text-sm">▲</span></p>
              </div>
           </div>
        </div>
      </div>

      <div className="grid md:grid-cols-2 gap-10">
        {suiteModes.map((mode, idx) => {
          const hasPlanPermission = checkPlanPermission(mode.planRequired);
          const hasCredits = userCredits >= mode.cost;
          const isLocked = !hasPlanPermission || !hasCredits;

          return (
            <button
              key={mode.id}
              onClick={() => {
                if (!hasPlanPermission || !hasCredits) onGoToPricing?.();
                else onSelectMode(mode.id);
              }}
              style={{ animationDelay: `${idx * 150}ms` }}
              className={`group relative flex flex-col p-12 bg-white/50 dark:bg-slate-900/40 glass-card rounded-[4rem] text-left transition-all duration-500 card-hover-effect overflow-hidden ${mode.glow} ${
                isLocked ? 'opacity-70 saturate-[0.3]' : ''
              }`}
            >
              <div className={`absolute top-0 right-0 w-80 h-80 bg-gradient-to-br ${mode.color} opacity-0 group-hover:opacity-[0.15] blur-[80px] rounded-full transition-opacity duration-700`} />

              <div className="absolute top-10 right-10 flex flex-col items-end gap-3 z-20">
                <div className={`px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 border shadow-sm ${
                  !hasCredits ? 'bg-red-500/10 text-red-500 border-red-500/20' : 'bg-amber-500/10 text-amber-500 border-amber-500/10'
                }`}>
                   <Coins className="w-4 h-4" /> {mode.cost} Credits
                </div>
                {!hasPlanPermission && (
                   <div className="px-4 py-2 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2">
                     <Lock className="w-3.5 h-3.5" /> {mode.planRequired}
                   </div>
                )}
              </div>

              <div className="relative z-10 flex flex-col h-full">
                <div className={`w-24 h-24 rounded-[2.5rem] bg-gradient-to-br ${mode.color} text-white flex items-center justify-center mb-10 shadow-2xl ${mode.shadow} group-hover:scale-110 group-hover:rotate-6 transition-all duration-500`}>
                  {mode.icon}
                </div>

                <div className="inline-block w-fit px-4 py-1.5 rounded-xl bg-slate-100 dark:bg-white/5 text-slate-500 dark:text-white/40 text-[10px] font-black uppercase tracking-[0.3em] mb-6">
                  {mode.badge}
                </div>

                <h3 className="text-4xl font-black mb-6 text-slate-900 dark:text-white group-hover:text-orange-500 transition-colors tracking-tight">
                  {mode.title}
                </h3>
                <p className="text-lg text-slate-500 dark:text-slate-400 font-bold leading-relaxed mb-12 flex-1">
                  {mode.description}
                </p>

                <div className={`inline-flex items-center gap-4 font-black text-sm uppercase tracking-[0.3em] transition-all ${
                  isLocked ? 'text-orange-600' : 'text-slate-900 dark:text-white group-hover:gap-8 group-hover:text-orange-500'
                }`}>
                   {isLocked ? (
                     <span className="flex items-center gap-3">
                       <Zap className="w-5 h-5 fill-current" /> Upgraden
                     </span>
                   ) : 'Tool starten'} <ArrowUpRight className="w-6 h-6" />
                </div>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { User as UserType } from '../types';
