  isActive: boolean
}) => (
  <button 
    onClick={onClick} 
    className={`transition-all text-xs font-black flex items-center gap-3 px-6 py-3 rounded-2xl active:scale-95 group ${
      isActive 
        ? 'bg-orange-600 text-white shadow-[0_10px_20px_rgba(249,115,22,0.3)]' 
