export const Navbar: React.FC<NavbarProps> = ({ user, currentView, onNavigate, onLoginClick, onLogout, isDarkMode, toggleTheme }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const profileRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
        setIsProfileOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getInitials = (name: string) => name.charAt(0).toUpperCase();

  return (
    <nav className={`fixed top-0 left-0 right-0 z-[60] transition-all duration-500 ${scrolled ? 'py-4' : 'py-8'}`}>
      <div className="max-w-[1400px] mx-auto px-6">
        <div className={`glass-card rounded-[2.5rem] px-8 h-20 flex justify-between items-center transition-all ${scrolled ? 'shadow-2xl' : ''}`}>

          <div 
            className="flex items-center gap-4 cursor-pointer group" 
            onClick={() => onNavigate('home')}
          >
            <div className="bg-orange-600 p-2.5 rounded-[1rem] shadow-[0_0_20px_rgba(249,115,22,0.4)] group-hover:scale-110 group-hover:rotate-12 transition-all">
              <Zap className="w-6 h-6 text-white fill-white" />
            </div>
            <span className="text-2xl font-black tracking-tighter text-slate-900 dark:text-white hidden md:block">
              ThumbCraft <span className="text-orange-600 animate-shimmer bg-clip-text">AI</span>
            </span>
          </div>

          <div className="hidden lg:flex items-center gap-1 bg-black/5 dark:bg-white/5 p-1 rounded-[1.5rem] absolute left-1/2 -translate-x-1/2">
            <NavLink isActive={currentView === 'home'} onClick={() => onNavigate('home')} icon={Home}>Start</NavLink>
            <NavLink isActive={currentView === 'studio'} onClick={() => onNavigate('studio')} icon={LayoutGrid}>Studio</NavLink>
            <NavLink isActive={currentView === 'pricing'} onClick={() => onNavigate('pricing')} icon={Coins}>Preise</NavLink>
            <NavLink isActive={currentView === 'examples'} onClick={() => onNavigate('examples')} icon={Sparkles}>Inspo</NavLink>
          </div>

          <div className="flex items-center gap-4">
            <button
              onClick={toggleTheme}
              className="w-12 h-12 flex items-center justify-center rounded-2xl bg-black/5 dark:bg-white/5 hover:bg-orange-600 hover:text-white transition-all active:scale-90 group"
            >
              {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>

            {user ? (
              <div className="relative" ref={profileRef}>
                <button 
                  onClick={() => setIsProfileOpen(!isProfileOpen)}
                  className="w-12 h-12 rounded-2xl bg-gradient-to-br from-orange-500 to-indigo-600 p-[2px] hover:scale-110 active:scale-95 transition-all shadow-xl"
                >
                  <div className="w-full h-full bg-slate-900 rounded-[14px] flex items-center justify-center text-white font-black">
                    {getInitials(user.name)}
                  </div>
                </button>
                {isProfileOpen && (
                  <div className="absolute right-0 mt-6 w-80 glass-card rounded-[2.5rem] p-6 animate-in zoom-in-95 duration-200">
                     <div className="flex items-center gap-4 mb-6">
                        <div className="w-14 h-14 bg-orange-600 rounded-2xl flex items-center justify-center text-white text-2xl font-black">{getInitials(user.name)}</div>
                        <div className="min-w-0">
                           <p className="font-black text-slate-900 dark:text-white truncate">{user.name}</p>
                           <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{user.plan}</p>
                        </div>
                     </div>
                     <div className="space-y-2">
                        <button className="w-full text-left px-5 py-3 rounded-xl hover:bg-orange-600 hover:text-white font-bold text-sm transition-all flex items-center gap-3"><UserIcon className="w-4 h-4" /> Profil</button>
                        <button className="w-full text-left px-5 py-3 rounded-xl hover:bg-orange-600 hover:text-white font-bold text-sm transition-all flex items-center gap-3"><Settings className="w-4 h-4" /> Settings</button>
                        <div className="h-px bg-white/10 my-2" />
                        <button onClick={onLogout} className="w-full text-left px-5 py-3 rounded-xl hover:bg-red-600 hover:text-white font-bold text-sm text-red-500 transition-all flex items-center gap-3"><LogOut className="w-4 h-4" /> Logout</button>
                     </div>
                  </div>
                )}
              </div>
            ) : (
              <button 
                onClick={onLoginClick}
                className="btn-primary px-8 py-3 bg-orange-600 hover:bg-orange-500 text-white rounded-2xl font-black shadow-xl shadow-orange-600/30 transition-all active:scale-95 text-sm uppercase tracking-widest"
              >
                Login
              </button>
            )}

            <button className="lg:hidden w-12 h-12 bg-black/5 dark:bg-white/5 rounded-2xl flex items-center justify-center" onClick={() => setIsOpen(!isOpen)}>
              {isOpen ? <X /> : <Menu />}
            </button>
          </div>
        </div>
      </div>
    </nav>
  );
};

