  [ThumbnailStyle.FITNESS]: ["Sweat Detail", "Dramatic Shadows", "Muscular Definition", "Intense Action"],
  [ThumbnailStyle.BUSINESS]: ["Corporate Bokeh", "Stock Market Glow", "Authority Pose", "Success Aesthetic"]
};

const ASPECT_RATIOS = [
  { id: '16:9', label: 'Video (16:9)', icon: Monitor },
  { id: '9:16', label: 'Shorts (9:16)', icon: Smartphone },
  { id: '1:1', label: 'Post (1:1)', icon: Square },
];

interface GeneratedResult {
  id: string;
  url: string;
  prompt: string;
  optimizedPrompt: string;
  isSaved?: boolean;
  isPromptSaved?: boolean;
  isRefining?: boolean;
  refinementText?: string;
  sources?: {title: string, url: string}[];
}

export const StudioGenerate: React.FC<StudioGenerateProps> = ({ useCredits, user, onGoToPricing, onSaveDesign, onSavePrompt, onDeletePrompt }) => {
  const [prompt, setPrompt] = useState('');
  const [aiSuggestion, setAiSuggestion] = useState('');
  const [isSuggesting, setIsSuggesting] = useState(false);
  const [style, setStyle] = useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [aspectRatio, setAspectRatio] = useState('16:9');
  const [useMarketResearch, setUseMarketResearch] = useState(false);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);

  const suggestionTimeoutRef = useRef<any>(null);

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    if (suggestionTimeoutRef.current) clearTimeout(suggestionTimeoutRef.current);
    if (prompt.trim().length < 5) {
      setAiSuggestion('');
      return;
    }
    setIsSuggesting(true);
    suggestionTimeoutRef.current = setTimeout(async () => {
      const refined = await getQuickRefinement(prompt, style);
      setAiSuggestion(refined);
      setIsSuggesting(false);
    }, 800);
    return () => {
      if (suggestionTimeoutRef.current) clearTimeout(suggestionTimeoutRef.current);
    };
  }, [prompt, style]);

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 4;
          if (prev < 70) return prev + 2;
          if (prev < 95) return prev + 0.5;
          return prev;
        });

        const normalTexts = [
          "Analysiere Design-Metriken...", 
          "Berechne optimale Beleuchtung...", 
          "Erstelle High-End Render...", 
          "Feinschliff an Texturen..."
        ];
        const researchTexts = [
          "Scanne virale YouTube-Trends...", 
          "Analysiere Top-Performer Nische...", 
          "Extrahiere visuelle Hooks...", 
          "Optimiere psychologische Trigger...", 
          "Render-Prozess gestartet..."
        ];

        const texts = useMarketResearch ? researchTexts : normalTexts;
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress, useMarketResearch]);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;
    const cost = useMarketResearch ? 25 : 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt, sources } = await generateThumbnail(prompt, style, aspectRatio, useMarketResearch);
      useCredits(cost);
      setResults(prev => [{
        id: `res-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        url,
        prompt: prompt,
        optimizedPrompt: optimizedPrompt,
        sources: sources,
        refinementText: '',
        isPromptSaved: false
      }, ...prev]);
      setProgress(100);
    } catch (err) {
      alert("Generierung fehlgeschlagen. Bitte versuche es erneut.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

  const handleRefine = async (resultId: string) => {
    const result = results.find(r => r.id === resultId);
    if (!result || !result.refinementText?.trim()) return;
    const cost = 5;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }
    setResults(prev => prev.map(r => r.id === resultId ? { ...r, isRefining: true } : r));
    try {
      const refinedUrl = await remakeThumbnail(result.url, result.refinementText);
      useCredits(cost);
      if (refinedUrl) {
        setResults(prev => prev.map(r => r.id === resultId ? { 
          ...r, 
          url: refinedUrl, 
          isRefining: false, 
          refinementText: '',
          prompt: `${r.prompt} (+ ${result.refinementText})`
        } : r));
      }
    } catch (err) {
      alert("Fehler beim Refinement.");
      setResults(prev => prev.map(r => r.id === resultId ? { ...r, isRefining: false } : r));
    }
  };

  const handleSave = (res: GeneratedResult) => {
    onSaveDesign?.({
      id: res.id,
      imageUrl: res.url,
      prompt: res.prompt,
      createdAt: new Date().toISOString(),
      style,
      aspectRatio
    });
    setResults(prev => prev.map(r => r.id === res.id ? { ...r, isSaved: true } : r));
  };

  const applyAiSuggestion = () => {
    if (aiSuggestion) {
      setPrompt(aiSuggestion);
      setAiSuggestion('');
    }
  };

  return (
    <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-12 animate-in fade-in duration-500">
      {/* Configuration Sidebar */}
      <div className="w-full lg:w-[420px] space-y-6">
        <div className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl sticky top-28 gpu-accelerated overflow-hidden">
          <div className="flex justify-between items-center mb-8">
            <h2 className="text-2xl font-black flex items-center gap-3 text-slate-900 dark:text-white">
              <Wand2 className="w-6 h-6 text-orange-500" /> Designer Lab
            </h2>
            <div className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full bg-amber-500/10 text-amber-500 border border-amber-500/10">
              <Coins className="w-3.5 h-3.5" /> {useMarketResearch ? '25' : '10'} Credits
            </div>
          </div>

          <div className="space-y-6">
            {user?.savedPrompts && user.savedPrompts.length > 0 && (
              <div className="animate-in slide-in-from-top-2 duration-300">
                <div className="flex items-center justify-between mb-3 px-1">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">
                    <Bookmark className="w-3 h-3 text-orange-500 fill-current" /> Vorlagen
                  </label>
                </div>
                <div className="flex gap-3 overflow-x-auto pb-4 no-scrollbar -mx-2 px-2 snap-x">
                  {user.savedPrompts.map((p) => (
                    <button key={p.id} onClick={() => {setPrompt(p.text); setStyle(p.style as ThumbnailStyle);}} className="flex-shrink-0 w-48 p-4 bg-slate-50 dark:bg-slate-800/80 border border-black/5 dark:border-white/5 rounded-2xl hover:border-orange-500/50 transition-all text-left group/lib snap-center">
                      <p className="text-[10px] font-bold text-slate-700 dark:text-slate-300 line-clamp-2 leading-relaxed mb-2">"{p.text}"</p>
                      <span className="text-[8px] font-black uppercase px-2 py-0.5 bg-orange-500/10 text-orange-600 rounded-md">{p.style}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div>
              <div className="flex items-center justify-between mb-3 px-1">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-500">Video Konzept</label>
              </div>
              <div className="relative group/prompt">
                <textarea 
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  placeholder="Beschreibe dein Motiv (z.B. Creator im Weltraum, blickend auf glühenden Planeten)..."
                  className="w-full h-40 bg-slate-50 dark:bg-slate-800/50 border border-black/5 dark:border-white/5 rounded-3xl p-5 focus:ring-2 focus:ring-orange-500 outline-none transition-all resize-none text-sm font-medium shadow-inner"
                />
                {(isSuggesting || aiSuggestion) && (
                  <div className="mt-3 animate-in slide-in-from-top-2 duration-300">
                    <button onClick={applyAiSuggestion} disabled={isSuggesting} className={`w-full p-4 rounded-2xl border flex flex-col items-start gap-2 transition-all group/sug ${isSuggesting ? 'bg-slate-50 dark:bg-slate-800 border-dashed border-slate-200 dark:border-slate-700 opacity-60' : 'bg-indigo-600/5 dark:bg-indigo-500/10 border-indigo-500/30 hover:bg-indigo-600/10 hover:border-indigo-500 shadow-lg'}`}>
                      <div className="flex items-center gap-2">
                        {isSuggesting ? <Loader2 className="w-3 h-3 text-indigo-500 animate-spin" /> : <Stars className="w-3.5 h-3.5 text-indigo-500 fill-indigo-500" />}
                        <span className="text-[10px] font-black uppercase tracking-widest text-indigo-600 dark:text-indigo-400">Pro-Level Optimierung</span>
                      </div>
                      {!isSuggesting && <p className="text-[11px] font-bold text-slate-700 dark:text-slate-300 text-left italic leading-relaxed line-clamp-2">"{aiSuggestion}"</p>}
                    </button>
                  </div>
                )}
              </div>
              <div className="flex flex-wrap gap-2 mt-4">
                {STYLE_SUGGESTIONS[style].map((s, i) => (
                  <button key={i} onClick={() => setPrompt(prev => prev + (prev ? ", " : "") + s)} className="px-3 py-1.5 bg-slate-100 dark:bg-slate-800 rounded-xl text-[10px] font-black text-slate-500 hover:bg-orange-500 hover:text-white transition-colors">+ {s}</button>
                ))}
              </div>
            </div>

            <div className={`p-4 border rounded-2xl flex items-center justify-between transition-all ${useMarketResearch ? 'bg-blue-600/10 border-blue-500/50 shadow-lg' : 'bg-slate-500/5 border-black/5'}`}>
              <div className="flex items-center gap-3">
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${useMarketResearch ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 dark:bg-slate-800 text-slate-400'}`}>
                  <Search className="w-5 h-5" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[10px] font-black uppercase tracking-widest text-slate-900 dark:text-white">Trend-Audit</span>
                  <span className="text-[9px] text-slate-500 font-bold">Inkl. Markt-Recherche</span>
                </div>
              </div>
              <button onClick={() => setUseMarketResearch(!useMarketResearch)} className={`w-12 h-6 rounded-full transition-all relative ${useMarketResearch ? 'bg-orange-600' : 'bg-slate-200 dark:bg-slate-700'}`}>
                <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${useMarketResearch ? 'left-7' : 'left-1'}`} />
              </button>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-3">
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500">Format</label>
                <div className="grid grid-cols-3 gap-2">
                  {ASPECT_RATIOS.map(r => (
                    <button key={r.id} onClick={() => setAspectRatio(r.id)} className={`p-2.5 rounded-xl border flex flex-col items-center gap-1 transition-all ${aspectRatio === r.id ? 'bg-orange-600 border-orange-600 text-white shadow-lg' : 'bg-slate-50 dark:bg-slate-800 border-transparent text-slate-400'}`}>
                      <r.icon className="w-4 h-4" />
                      <span className="text-[8px] font-black">{r.id}</span>
                    </button>
                  ))}
                </div>
              </div>
              <div className="space-y-3">
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500">Stil</label>
                <select value={style} onChange={(e) => setStyle(e.target.value as ThumbnailStyle)} className="w-full h-[52px] bg-slate-50 dark:bg-slate-800/50 border border-black/5 rounded-xl px-4 text-xs font-black uppercase outline-none">
                  {Object.values(ThumbnailStyle).map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
            </div>

            <div className="pt-4">
              {loading ? (
                <div className="space-y-3 animate-in fade-in">
                  <div className="flex justify-between text-[10px] font-black uppercase text-orange-600 tracking-widest">
                    <span className="flex items-center gap-2"><Loader2 className="w-3 h-3 animate-spin" /> {statusText}</span>
                    <span>{Math.round(progress)}%</span>
                  </div>
                  <div className="h-1.5 w-full bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                    <div className="h-full bg-orange-600 transition-all duration-300" style={{ width: `${progress}%` }} />
                  </div>
                </div>
              ) : (
                <button onClick={handleGenerate} disabled={!prompt.trim() || isLowCredits(useMarketResearch ? 25 : 10)} className="w-full py-5 bg-orange-600 hover:bg-orange-700 text-white rounded-[2rem] font-black text-lg shadow-xl shadow-orange-600/20 flex items-center justify-center gap-3 transition-all active:scale-[0.98] disabled:opacity-50">
                  <Zap className="w-6 h-6 fill-current" /> Thumbnail schmieden
                </button>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Results Feed */}
      <div className="flex-1 space-y-10 min-h-[500px]">
        {results.length > 0 ? (
          results.map((res) => (
            <div key={res.id} className="bg-white dark:bg-slate-900 rounded-[3.5rem] border border-black/5 dark:border-white/5 p-8 shadow-2xl animate-in fade-in duration-500 relative group/card gpu-accelerated">
              <div className="flex flex-col md:flex-row gap-10">
                <div className="flex-1 space-y-6">
                  <div className="relative aspect-video rounded-[2.5rem] overflow-hidden bg-slate-100 dark:bg-slate-800 group/img shadow-2xl border-4 border-white dark:border-slate-800">
                    <img src={res.url} className="w-full h-full object-cover" alt="Ergebnis" loading="lazy" />
                    {res.isRefining && (
                      <div className="absolute inset-0 bg-black/50 backdrop-blur-md flex flex-col items-center justify-center text-white gap-3">
                        <Loader2 className="w-10 h-10 animate-spin" />
                        <span className="text-[10px] font-black uppercase tracking-widest">Wird optimiert...</span>
                      </div>
                    )}
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center gap-3">
                      <button onClick={() => handleSave(res)} className={`p-4 rounded-2xl transition-all ${res.isSaved ? 'bg-rose-500 text-white shadow-lg' : 'bg-white text-rose-500 hover:scale-110 shadow-xl'}`} title="Favorit">
                        <Heart className={`w-6 h-6 ${res.isSaved ? 'fill-current' : ''}`} />
                      </button>
                      <button onClick={() => { const a = document.createElement('a'); a.href = res.url; a.download = 'thumb.png'; a.click(); }} className="p-4 bg-white text-slate-900 rounded-2xl hover:scale-110 transition-all shadow-xl" title="Download"><Download className="w-6 h-6" /></button>
                    </div>
                  </div>
                  <div className="p-6 bg-emerald-500/5 dark:bg-emerald-500/10 rounded-3xl border border-emerald-500/10">
                     <div className="flex items-center gap-2 mb-3">
                        <Sparkles className="w-4 h-4 text-emerald-500" />
                        <span className="text-[10px] font-black uppercase text-emerald-600 tracking-widest">KI Strategie</span>
                     </div>
                     <p className="text-xs font-bold text-slate-700 dark:text-slate-300 italic leading-relaxed">"{res.optimizedPrompt}"</p>
                  </div>
                  {res.sources && res.sources.length > 0 && (
                    <div className="p-6 bg-blue-500/5 dark:bg-blue-500/10 rounded-3xl border border-blue-500/10">
                       <div className="flex items-center gap-2 mb-4">
                          <Globe className="w-4 h-4 text-blue-500" />
                          <span className="text-[10px] font-black uppercase text-blue-600 tracking-widest">Marktdaten-Quellen</span>
                       </div>
                       <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                          {res.sources.map((s, i) => (
                            <a key={i} href={s.url} target="_blank" className="px-4 py-2.5 bg-white dark:bg-slate-800 rounded-xl text-[9px] font-bold flex items-center justify-between border border-black/5 hover:border-blue-500 transition-all">
                              <span className="truncate flex-1 pr-2">{s.title}</span>
                              <ExternalLink className="w-3 h-3 text-slate-300 shrink-0" />
                            </a>
                          ))}
                       </div>
                    </div>
                  )}
                </div>
                <div className="w-full md:w-64 flex flex-col justify-between">
                  <div className="space-y-4">
                    <div className="flex items-center gap-2">
                      <Zap className="w-4 h-4 text-orange-600" />
                      <h4 className="text-[11px] font-black uppercase text-slate-400 tracking-widest">Manueller Schliff</h4>
                    </div>
                    <textarea 
                      value={res.refinementText}
                      onChange={(e) => setResults(prev => prev.map(r => r.id === res.id ? { ...r, refinementText: e.target.value } : r))}
                      placeholder="z.B. Mehr Rim-Light..."
                      className="w-full h-32 bg-slate-50 dark:bg-slate-800/50 border border-black/5 rounded-[2rem] p-5 text-xs font-bold focus:ring-2 focus:ring-orange-500 resize-none transition-all"
                    />
                    <div className="flex items-center justify-between px-2">
                       <span className="text-[9px] font-black uppercase text-orange-600">5 Credits</span>
                       <button onClick={() => handleRefine(res.id)} disabled={res.isRefining || !res.refinementText?.trim() || isLowCredits(5)} className="p-3 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-2xl shadow-xl active:scale-[0.98] hover:bg-orange-600 hover:text-white transition-all">
                        <ArrowRight className="w-5 h-5" />
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))
        ) : (
          <div className="h-[500px] flex flex-col items-center justify-center text-center p-12 bg-slate-100/50 dark:bg-slate-900/20 rounded-[4rem] border-4 border-dashed border-black/5">
            <div className="w-24 h-24 bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-xl flex items-center justify-center mb-8">
              <ImageIcon className="w-12 h-12 text-slate-300" />
            </div>
            <h3 className="text-3xl font-black mb-4 text-slate-900 dark:text-white">Studio bereit</h3>
            <p className="text-slate-500 dark:text-slate-400 text-lg max-w-sm font-medium leading-relaxed">Deine Entwürfe werden hier mit modernsten YouTube-Aesthetic-Algorithmen gerendert.</p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User as UserType } from '../types';
import { Zap, Menu, X, Sun, Moon, LogOut, Settings, User as UserIcon } from 'lucide-react';

interface NavbarProps {
  user: UserType | null;
  currentView: string;
  onNavigate: (view: any) => void;
  onLoginClick: () => void;
  onLogout: () => void;
  isDarkMode: boolean;
  toggleTheme: () => void;
}

