    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed top-0 left-0 right-0 z-[100] transition-all duration-500 flex justify-center ${scrolled ? 'pt-4' : 'pt-6'}`}>
      <div className={`w-[95%] max-w-7xl pl-5 pr-8 py-5 flex justify-between items-center transition-all duration-500 rounded-[2.5rem] border ${
        scrolled 
          ? 'bg-white/95 dark:bg-slate-900/95 backdrop-blur-xl shadow-[0_25px_60px_rgba(0,0,0,0.25)] border-black/5 dark:border-white/10 scale-[1.01]' 
          : 'bg-white/60 dark:bg-slate-900/40 backdrop-blur-md border-transparent shadow-none'
      }`}>
        {/* Brand / Logo - Slightly shifted left by pl-5 instead of px-8 */}
        <div 
          className="flex items-center gap-3 cursor-pointer group" 
          onClick={() => onNavigate('home')}
        >
          <div className="bg-orange-600 p-2.5 rounded-xl group-hover:scale-110 transition-transform shadow-lg shadow-orange-600/20">
            <Zap className="w-6 h-6 text-white fill-white" />
          </div>
          <span className="text-2xl font-black tracking-tighter text-slate-900 dark:text-white">
            ThumbCraft <span className="text-orange-600">AI</span>
          </span>
        </div>

        {/* Reordered Navigation Links - Larger Text */}
        <div className="hidden md:flex items-center gap-8 lg:gap-12">
          <button 
            onClick={() => onNavigate('studio')} 
            className={`text-sm font-black uppercase tracking-widest transition-all hover:scale-105 ${currentView === 'studio' ? 'text-orange-600' : 'text-slate-500 hover:text-slate-900 dark:hover:text-white'}`}
          >
            Studio
          </button>
          <button 
            onClick={() => onNavigate('pricing')} 
            className={`text-sm font-black uppercase tracking-widest transition-all hover:scale-105 ${currentView === 'pricing' ? 'text-orange-600' : 'text-slate-500 hover:text-slate-900 dark:hover:text-white'}`}
          >
            Preise
          </button>

          {/* Centered Start Button - Larger Padding & Font */}
          <button 
            onClick={() => onNavigate('home')} 
            className={`px-10 py-3 rounded-full text-base font-black transition-all ${
              currentView === 'home' 
                ? 'bg-orange-600 text-white shadow-xl shadow-orange-600/30 scale-105' 
                : 'bg-slate-100 dark:bg-white/5 text-slate-600 dark:text-slate-300 hover:bg-orange-600 hover:text-white'
            }`}
          >
            Home
          </button>

          <button 
            onClick={() => onNavigate('reviews')} 
            className={`text-sm font-black uppercase tracking-widest transition-all hover:scale-105 ${currentView === 'reviews' ? 'text-orange-600' : 'text-slate-500 hover:text-slate-900 dark:hover:text-white'}`}
          >
            Bewertungen
          </button>
          <button 
            onClick={() => onNavigate('examples')} 
            className={`text-sm font-black uppercase tracking-widest transition-all hover:scale-105 ${currentView === 'examples' ? 'text-orange-600' : 'text-slate-500 hover:text-slate-900 dark:hover:text-white'}`}
          >
            Beispiele
          </button>
        </div>

        {/* Actions */}
        <div className="flex items-center gap-4">
          <button 
            onClick={toggleTheme} 
            className="p-3 rounded-xl bg-slate-100 dark:bg-white/5 text-slate-500 hover:text-orange-600 transition-all active:scale-90"
          >
            {isDarkMode ? <Sun className="w-6 h-6" /> : <Moon className="w-6 h-6" />}
          </button>

          {user ? (
            <div className="flex items-center gap-4">
              <button 
                onClick={onLogout} 
                className="hidden lg:flex items-center gap-2 px-4 py-2 text-sm font-black uppercase tracking-widest text-slate-500 hover:text-red-500 transition-colors"
              >
                <LogOut className="w-5 h-5" />
              </button>
              <div className="w-12 h-12 rounded-full bg-gradient-to-tr from-orange-600 to-orange-400 flex items-center justify-center text-white font-black shadow-xl border-2 border-white dark:border-slate-800">
                {user.name.charAt(0).toUpperCase()}
