          )}

          <button className="md:hidden p-2 text-slate-500" onClick={() => setIsMenuOpen(!isMenuOpen)}>
            {isMenuOpen ? <X size={28} /> : <Menu size={28} />}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      {isMenuOpen && (
        <div className="absolute top-full left-0 right-0 mt-4 mx-4 md:hidden bg-white dark:bg-slate-900 border border-black/5 dark:border-white/10 p-10 rounded-[3rem] shadow-2xl space-y-8 animate-in slide-in-from-top-4">
          <button onClick={() => { onNavigate('home'); setIsMenuOpen(false); }} className="block w-full text-left font-black uppercase tracking-widest text-lg text-orange-600">Home</button>
          <button onClick={() => { onNavigate('studio'); setIsMenuOpen(false); }} className="block w-full text-left font-black uppercase tracking-widest text-lg">Studio</button>
          <button onClick={() => { onNavigate('pricing'); setIsMenuOpen(false); }} className="block w-full text-left font-black uppercase tracking-widest text-lg">Preise</button>
          <button onClick={() => { onNavigate('reviews'); setIsMenuOpen(false); }} className="block w-full text-left font-black uppercase tracking-widest text-lg">Bewertungen</button>
          <button onClick={() => { onNavigate('examples'); setIsMenuOpen(false); }} className="block w-full text-left font-black uppercase tracking-widest text-lg">Beispiele</button>
