import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const getMimeType = (base64: string): string => {
  const match = base64.match(/^data:([^;]+);base64,/);
  return match ? match[1] : 'image/png';
};

const cleanBase64 = (base64: string): string => {
  return base64.includes(',') ? base64.split(',')[1] : base64;
};

/**
 * Optimiert den Nutzer-Prompt in Echtzeit für die UI.
 */
export const getQuickRefinement = async (userPrompt: string, style: string) => {
  if (userPrompt.trim().length < 3) return "";

  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Handle als "Senior YouTube Thumbnail Designer". 
      Deine Aufgabe: Optimiere NUR DIE TECHNISCHE BESCHREIBUNG des Prompts: "${userPrompt}" für den Stil "${style}".

      STRIKTE REGELN:
      - Behalte das Kern-Motiv bei.
      - Ergänze Fachbegriffe: "dramatic rim lighting", "high-octane render", "vibrant color palette", "razor sharp focus", "cinematic composition".
      - Antworte NUR mit dem optimierten Prompt-Text.`,
    });
    return response.text?.replace(/^"|"$/g, '') || "";
  } catch (e) {
    return "";
  }
};

/**
 * Erstellt eine tiefgreifende Design-Strategie unter Einbeziehung von Markttrends.
 */
const optimizePromptWithMarketResearch = async (userPrompt: string, style: string, useSearch: boolean) => {
  const ai = getAI();

  let searchSources: any[] = [];
  let promptContext = "";

  if (useSearch) {
    const searchResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Current viral visual hooks and thumbnail trends for the topic: "${userPrompt}"`,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });
    promptContext = `SEARCH INSIGHTS: ${searchResponse.text}`;
    searchSources = searchResponse.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Trend Report',
      url: chunk.web?.uri || ''
    })).filter((s: any) => s.url) || [];
  }

  const systemInstruction = `Du bist ein Elite-Thumbnail-Stratege für Kanäle wie MrBeast.
  Nutze psychologische Trigger (Curiosity Gap, Negativity Bias, Contrast) und technische Exzellenz.

  Ziele für "${userPrompt}":
  1. Identifiziere den stärksten visuellen "Hook".
  2. Erstelle einen extrem detaillierten Bild-Prompt für eine KI-Generierung.
  3. Berücksichtige Drittel-Regel, Komplementärfarben und "Rim-Lighting".

  Antworte IMMER im JSON Format.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Erstelle eine unschlagbare Thumbnail-Strategie für: "${userPrompt}" (Stil: ${style}). 
      Beziehe diese Marktdaten ein: ${promptContext}`,
      config: {
        systemInstruction,
        thinkingConfig: { thinkingBudget: 32768 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            optimizedPrompt: { type: Type.STRING, description: "Der technische Prompt für die Bild-KI." },
            strategy: { type: Type.STRING, description: "Warum dieses Design klicken wird (psychologisch)." }
          },
          required: ["optimizedPrompt", "strategy"]
        }
      }
    });
    const parsed = JSON.parse(response.text || '{}');
    return { ...parsed, sources: searchSources };
  } catch (e) {
    return { 
      optimizedPrompt: `${userPrompt}, highly detailed, professional lighting, 8k resolution`, 
      strategy: "Technische Umsetzung ohne tiefere Markt-Analyse.", 
      sources: [] 
    };
  }
};

/**
 * Die finale Bildgenerierung mit optimierten Parametern.
 */
export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9", useMarketResearch: boolean = false) => {
  const ai = getAI();

  const { optimizedPrompt, strategy, sources } = await optimizePromptWithMarketResearch(prompt, style, useMarketResearch);

  const finalInstruction = `YOU ARE A PROFESSIONAL YOUTUBE THUMBNAIL DESIGNER.
    YOUR GOAL IS CTR, NOT ART.

    STRICT STYLE RULES:
    - DO NOT CREATE AI-ART OR ILLUSTRATIONS.
    - LOOKS LIKE MADE IN PHOTOSHOP.
    - MAIN SUBJECT: ${optimizedPrompt}
    - STYLE: ${style}
    - COMPOSITION: Strong outlines and masks (cutout look), extreme clarity.
    - LIGHTING: Dramatic rim lighting (orange/blue), cinematic high-contrast.
    - BACKGROUND: Simple and blurred (extreme depth of field) to isolate the subject.
    - COLOR: Highly saturated, vibrant, popping colors.
    - CHARACTER: Exaggerated expressions, high-energy vibes.
    - TEXT PLACEHOLDER: If needed, use bold "BIG TEXT HERE".
    - FINISH: High clarity, razor sharp focus, zero artifacts.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: finalInstruction }] },
      config: { 
        imageConfig: { 
          aspectRatio: aspectRatio as any,
          imageSize: "1K"
        } 
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return {
        url: `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`,
        optimizedPrompt: strategy,
        sources: sources
      };
    }
    throw new Error("Kein Bild generiert.");
  } catch (e: any) {
    throw new Error(e.message || "Fehler in der Bildschmiede.");
  }
};

export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();
  const instruction = `AS A PROFESSIONAL PHOTO EDITOR: 
    Modify this thumbnail strictly following professional YouTube aesthetic.
    TASK: "${adjustmentPrompt}".
    RULES: High-contrast cutouts, rim lighting, blurred background, saturated colors. No AI-Art style. Keep professional Photoshop-level clarity.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { 
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: instruction }
        ] 
      },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`;
    }
    return null;
  } catch (e) {
    return null;
  }
};

