export const analyzeThumbnailImage = async (base64: string) => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { inlineData: { data: cleanBase64(base64), mimeType: getMimeType(base64) } },
        { text: "Analysiere dieses YouTube Thumbnail auf Klick-Potenzial (CTR). Gib einen Score von 1-10, detailliertes Feedback und 3 Verbesserungsvorschläge. Antworte im JSON Format." }
