export const StudioGenerate: React.FC<StudioGenerateProps> = ({ useCredits, user, onGoToPricing, onSaveDesign, onSavePrompt, onDeletePrompt }) => {
  const [prompt, setPrompt] = useState('');
  const [mode, setMode] = useState<'free' | 'guided'>('free');
  const [guidedStep, setGuidedStep] = useState(0);
  const [guidedAnswers, setGuidedAnswers] = useState({
    title: '',
    emotion: '',
    style: '',
    text: ''
  });

  const [aiSuggestion, setAiSuggestion] = useState('');
  const [isSuggesting, setIsSuggesting] = useState(false);
  const [style, setStyle] = useState<ThumbnailStyle>(ThumbnailStyle.CLEAN);
  const [aspectRatio, setAspectRatio] = useState('16:9');
  const [useMarketResearch, setUseMarketResearch] = useState(false);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);

  const suggestionTimeoutRef = useRef<any>(null);

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    if (suggestionTimeoutRef.current) clearTimeout(suggestionTimeoutRef.current);
    if (prompt.trim().length < 5) {
      setAiSuggestion('');
      return;
    }
    setIsSuggesting(true);
    suggestionTimeoutRef.current = setTimeout(async () => {
      const refined = await getQuickRefinement(prompt, style);
      setAiSuggestion(refined);
      setIsSuggesting(false);
    }, 800);
    return () => {
      if (suggestionTimeoutRef.current) clearTimeout(suggestionTimeoutRef.current);
    };
  }, [prompt, style]);

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 4;
          if (prev < 70) return prev + 2;
          if (prev < 95) return prev + 0.5;
          return prev;
        });

        const texts = [
          "Analysiere Design-Metriken...", 
          "Berechne optimale Beleuchtung...", 
          "Erstelle High-End Render...", 
          "CTR-Optimierung läuft...",
          "Feinschliff an Texturen..."
        ];
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress]);

  const handleGenerate = async () => {
    let finalPrompt = prompt;
    if (mode === 'guided') {
      finalPrompt = `Video Topic: ${guidedAnswers.title}, Emotion: ${guidedAnswers.emotion}, Reference Style: ${guidedAnswers.style}, Overlay Text: ${guidedAnswers.text}`;
    }

    if (!finalPrompt.trim()) return;
    const cost = useMarketResearch ? 25 : 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt, sources } = await generateThumbnail(finalPrompt, style, aspectRatio, useMarketResearch);
      useCredits(cost);
      setResults(prev => [{
        id: `res-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        url,
        prompt: finalPrompt,
        optimizedPrompt: optimizedPrompt,
        sources: sources,
        refinementText: '',
        isPromptSaved: false
      }, ...prev]);
      setProgress(100);
    } catch (err) {
      alert("Generierung fehlgeschlagen. Bitte versuche es erneut.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

  const handleSave = (res: GeneratedResult) => {
    onSaveDesign?.({
      id: res.id,
      imageUrl: res.url,
      prompt: res.prompt,
      createdAt: new Date().toISOString(),
      style,
      aspectRatio
    });
    setResults(prev => prev.map(r => r.id === res.id ? { ...r, isSaved: true } : r));
  };

  const guidedSteps = [
    { key: 'title', label: 'Was ist dein Video-Thema?', placeholder: 'z.B. Minecraft Survival in 100 Tagen...' },
    { key: 'emotion', label: 'Welche Emotion soll es auslösen?', placeholder: 'z.B. Schock, Neugier, Hype...' },
    { key: 'style', label: 'Welcher Creator-Stil?', placeholder: 'z.B. MrBeast, Cinematic, Tech...' },
    { key: 'text', label: 'Text auf dem Thumbnail? (max. 3-5 Wörter)', placeholder: 'z.B. DIE WAHRHEIT, FAST VERLOREN...' }
  ];

  return (
    <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-12 animate-in fade-in duration-500">
      {/* Configuration Sidebar */}
      <div className="w-full lg:w-[420px] space-y-6">
        <div className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-2xl sticky top-28 overflow-hidden">
