export const StudioGenerate: React.FC<StudioGenerateProps> = ({ useCredits, user, onGoToPricing, onSaveDesign, onSavePrompt, onDeletePrompt }) => {
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState({
    title: '',
    emotion: '',
    style: '',
    text: ''
  });

  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 4;
          if (prev < 70) return prev + 2;
          if (prev < 95) return prev + 0.5;
          return prev;
        });

        const texts = [
          "Strategie wird entworfen...", 
          "Visuelle Hierarchie wird optimiert...", 
          "Photoshop-Style wird angewendet...", 
          "CTR-Maximierung läuft...",
          "High-Resolution Export..."
        ];
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress]);

  const handleGenerate = async () => {
    const finalPrompt = `Video Topic: ${answers.title}, Emotion: ${answers.emotion}, Style: ${answers.style}, Text Overlay: ${answers.text}`;

    const cost = 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt, sources } = await generateThumbnail(finalPrompt, answers.style as any, '16:9', false);
      useCredits(cost);
      setResults(prev => [{
        id: `res-${Date.now()}`,
        url,
        prompt: finalPrompt,
        optimizedPrompt: optimizedPrompt,
        sources: sources,
        refinementText: '',
        isPromptSaved: false
      }, ...prev]);
      setProgress(100);
      setStep(0); // Reset for next use
      setAnswers({ title: '', emotion: '', style: '', text: '' });
    } catch (err) {
      alert("Generierung fehlgeschlagen. Bitte versuche es erneut.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

  const emotions = ['Schock', 'Neugier', 'Lustig', 'Hype', 'Luxus'];
  const styles = ['Gaming', 'Business', 'Tutorial', 'MrBeast', 'Cinematic'];

  const steps = [
    { 
