          {!loading ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
              <div className="space-y-4">
                <div className="flex justify-between items-center px-1">
                  <span className="text-[10px] font-black uppercase tracking-[0.2em] text-orange-600">Schritt {step + 1} von 4</span>
                  <div className="flex gap-1">
                    {steps.map((_, i) => (
                      <div key={i} className={`h-1.5 rounded-full transition-all ${i === step ? 'w-6 bg-orange-600' : 'w-1.5 bg-slate-200 dark:bg-slate-700'}`} />
