import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const getMimeType = (base64: string): string => {
  const match = base64.match(/^data:([^;]+);base64,/);
  return match ? match[1] : 'image/png';
};

const cleanBase64 = (base64: string): string => {
  return base64.includes(',') ? base64.split(',')[1] : base64;
};

/**
 * Optimiert den Nutzer-Prompt in Echtzeit für die UI.
 */
export const getQuickRefinement = async (userPrompt: string, style: string) => {
  if (userPrompt.trim().length < 3) return "";

  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `ACT AS AN ELITE YOUTUBE THUMBNAIL DESIGNER. 
      Optimiere NUR DIE TECHNISCHE BESCHREIBUNG des Prompts: "${userPrompt}" für den Stil "${style}".

      STRIKTE REGELN:
      - KEINE Illustrationen, kein "AI Art" Look.
      - Erstelle eine Photoshop-Komposition.
      - Nutze: "High-contrast volumetric lighting", "razor sharp subject focus", "hyper-realistic skin textures", "neon rim light", "vivid saturated colors", "blurred motion backgrounds".
      - Antworte NUR mit dem optimierten Prompt-Text.`,
    });
    return response.text?.replace(/^"|"$/g, '') || "";
  } catch (e) {
    return "";
  }
};

/**
 * Erstellt eine tiefgreifende Design-Strategie unter Einbeziehung von Markttrends.
 */
const optimizePromptWithMarketResearch = async (userPrompt: string, style: string, useSearch: boolean) => {
  const ai = getAI();

  let searchSources: any[] = [];
  let promptContext = "";

  if (useSearch) {
    const searchResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Identify high-CTR visual hooks, current color trends, and dominant thumbnail layouts for the niche: "${userPrompt}"`,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });
    promptContext = `MARKET RESEARCH DATA: ${searchResponse.text}`;
    searchSources = searchResponse.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Market Trend Analysis',
      url: chunk.web?.uri || ''
    })).filter((s: any) => s.url) || [];
  }

  const systemInstruction = `You are the World's Best YouTube Thumbnail Strategist. 
  Your goal is to engineer the highest possible Click-Through-Rate (CTR).

  CORE STRATEGIC PILLARS:
  1. MOBILE FIRST: Elements must be huge, clear, and readable on a 5-inch screen.
  2. PSYCHOLOGICAL TRIGGERS: Exaggerated facial expressions, high-contrast "Before/After" vibes, and curiosity gaps.
  3. COMPOSITION: Professional Photoshop look (Composite photography). Heavy Bokeh (f/1.8) on backgrounds.
  4. LIGHTING: Dominant Rim Lighting (Glow on edges) to separate the subject.
  5. COLOR: Aggressive saturation and professional cinematic color grading (Orange/Teal or Vibrant Primaries).

  Avoid all "painterly" or "fuzzy" AI tropes. Focus on hard edges and sharp detail.

  Respond ONLY in JSON format.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Develop a high-conversion visual strategy for: "${userPrompt}" in the style of "${style}". 
      Incorporate these research insights: ${promptContext}`,
      config: {
        systemInstruction,
        thinkingConfig: { thinkingBudget: 32768 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            optimizedPrompt: { type: Type.STRING, description: "Highly technical prompt for the image AI including lighting and composition specifics." },
            strategy: { type: Type.STRING, description: "The psychological reasoning behind this visual setup." }
          },
          required: ["optimizedPrompt", "strategy"]
        }
      }
    });
    const parsed = JSON.parse(response.text || '{}');
    return { ...parsed, sources: searchSources };
  } catch (e) {
    return { 
      optimizedPrompt: `${userPrompt}, hyper-realistic, professional lighting, octane render, 8k, vibrant colors`, 
      strategy: "Optimiert auf Basis von Branchen-Standard Best-Practices.", 
      sources: [] 
    };
  }
};

/**
 * Die finale Bildgenerierung mit optimierten Parametern.
 */
export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9", useMarketResearch: boolean = false) => {
  const ai = getAI();

  const { optimizedPrompt, strategy, sources } = await optimizePromptWithMarketResearch(prompt, style, useMarketResearch);

  const finalInstruction = `
    TASK: GENERATE A HIGH-CTR YOUTUBE THUMBNAIL COMPOSITE.
    STYLE: ${style} Professional Studio Aesthetic.

    CRITICAL QUALITY DIRECTIVES:
    - PHOTOREALISM: Use "Octane Render", "8k UHD", "Unreal Engine 5 quality", "Ray-traced lighting".
    - SUBJECT DOMINANCE: The main character/object must take up 60% of the frame.
    - RIM LIGHTING: Intense backlight glow on the subject's edges for a "3D pop" effect.
    - TEXTURE: Razor sharp focus. Visible skin pores or high-detail metallic/material textures.
    - BACKGROUND: Heavy "Depth of Field" (f/1.8 bokeh) to isolate the subject.
    - COLORS: Vivid, ultra-saturated, cinematic color grading. 
    - NO SMOOTHNESS: Avoid the "plastic" AI look. Aim for sharp, professional photography with digital grit.

    SCENE DESCRIPTION: ${optimizedPrompt}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: finalInstruction }] },
      config: { 
        imageConfig: { 
          aspectRatio: aspectRatio as any,
          imageSize: "1K"
        } 
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return {
        url: `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`,
        optimizedPrompt: strategy,
        sources: sources
      };
    }
    throw new Error("Generierung fehlgeschlagen.");
  } catch (e: any) {
    throw new Error(e.message || "Fehler in der Bildschmiede.");
  }
};

export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();
  const instruction = `
    PROFESSIONAL RETOUCHING TASK: 
    Modify this existing thumbnail while strictly adhering to high-end YouTube aesthetics.

    REQUIRED ENHANCEMENTS:
    - Increase overall contrast and color saturation.
    - Apply intense rim-lighting to the modified elements.
    - Ensure razor-sharp focus on the primary subject.
    - Blur the background further to increase depth.
    - COMPOSITE STYLE: Elements should look perfectly integrated into a Photoshop-level production.

    MODIFICATION: "${adjustmentPrompt}"`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { 
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: instruction }
        ] 
      },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
