import { Wand2, Sparkles, Loader2, Download, Coins, Monitor, Smartphone, Square, Heart, Send, Zap, MessageSquare, ArrowRight, Info, Image as ImageIcon, Lightbulb, Target, Globe, ExternalLink, Search, Stars, Bookmark, Trash2, History, ChevronRight, ChevronLeft, Layout, UserCircle, BrainCircuit } from 'lucide-react';
import React, { useState, useEffect, useRef } from 'react';
import { generateThumbnail, remakeThumbnail, getQuickRefinement } from '../services/geminiService';
import { ThumbnailStyle, User, Design } from '../types';

interface StudioGenerateProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  onGoToPricing?: () => void;
  onSaveDesign?: (design: Design) => void;
  onSavePrompt?: (text: string, style: string) => void;
  onDeletePrompt?: (id: string) => void;
}

interface GeneratedResult {
  id: string;
  url: string;
  prompt: string;
  optimizedPrompt: string;
  isSaved?: boolean;
  isPromptSaved?: boolean;
  isRefining?: boolean;
  refinementText?: string;
  sources?: {title: string, url: string}[];
}

export const StudioGenerate: React.FC<StudioGenerateProps> = ({ useCredits, user, onGoToPricing, onSaveDesign, onSavePrompt, onDeletePrompt }) => {
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState({
    topic: '',
    subject: '',
    emotion: '',
    style: '',
    text: ''
  });

  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 4;
          if (prev < 70) return prev + 2;
          if (prev < 95) return prev + 0.5;
          return prev;
        });

        const texts = [
          "Markttrends werden analysiert...", 
          "Visuelle Hierarchie wird berechnet...", 
          "Fokuspunkt auf Hauptmotiv setzen...", 
          "Psychologische Farbkorrektur...",
          "High-CTR Rendering..."
        ];
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress]);

  const handleGenerate = async () => {
    const finalPrompt = `Topic: ${answers.topic}, Primary Subject: ${answers.subject}, Emotion: ${answers.emotion}, Aesthetic: ${answers.style}, Text: ${answers.text}`;

    const cost = 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt, sources } = await generateThumbnail(finalPrompt, answers.style as any, '16:9', false);
      useCredits(cost);
      setResults(prev => [{
        id: `res-${Date.now()}`,
        url,
        prompt: finalPrompt,
        optimizedPrompt: optimizedPrompt,
        sources: sources,
        refinementText: '',
        isPromptSaved: false
      }, ...prev]);
      setProgress(100);
      setStep(0);
      setAnswers({ topic: '', subject: '', emotion: '', style: '', text: '' });
    } catch (err) {
      alert("Generierung fehlgeschlagen. Bitte versuche es erneut.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

  const emotions = ['Extreme Angst', 'Pure Neugier', 'Hype / Adrenalin', 'Tiefe Trauer', 'Luxus / Status'];
  const styles = ['MrBeast (Dramatisch)', 'Minimalistisch (Edel)', 'Gaming (Neon/Action)', 'Doku (Cinematic)', 'Vlog (Authentisch)'];

  const steps = [
    { 
      id: 'topic', 
      label: 'Was ist der "Hook" deines Videos?', 
      placeholder: 'z.B. Ich habe 100 Stunden in der Wüste überlebt...',
      icon: <Target className="w-5 h-5" />,
      type: 'input'
    },
    { 
      id: 'subject', 
      label: 'Wer oder was ist das Hauptmotiv?', 
      placeholder: 'z.B. Mein Gesicht mit riesigen Augen, ein Lamborghini...',
      icon: <UserCircle className="w-5 h-5" />,
      type: 'input'
    },
    { 
      id: 'emotion', 
      label: 'Welche Emotion soll triggern?', 
      options: emotions,
      icon: <BrainCircuit className="w-5 h-5" />,
      type: 'select'
    },
    { 
      id: 'style', 
      label: 'Welcher Brand-Vibe passt?', 
      options: styles,
      icon: <Sparkles className="w-5 h-5" />,
      type: 'select'
    },
    { 
      id: 'text', 
      label: 'Text-Hook (Max. 3 Wörter)', 
      placeholder: 'z.B. NIEMALS WIEDER...',
      icon: <MessageSquare className="w-5 h-5" />,
      type: 'input'
    }
  ];

  const currentStep = steps[step];

  return (
    <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-12 animate-in fade-in duration-500">
      {/* Configuration Sidebar */}
      <div className="w-full lg:w-[420px] space-y-6">
        <div className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 dark:border-white/5 shadow-2xl sticky top-28 overflow-hidden">
          <div className="flex justify-between items-center mb-8">
            <h2 className="text-xl font-black flex items-center gap-3 text-slate-900 dark:text-white">
              <Sparkles className="w-6 h-6 text-orange-500" /> Strategie-Wizard
            </h2>
            <div className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full bg-orange-500/10 text-orange-500 border border-orange-500/10">
              <Coins className="w-3.5 h-3.5" /> 10 Credits
            </div>
          </div>

          {!loading ? (
            <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
              <div className="space-y-4">
                <div className="flex justify-between items-center px-1">
                  <span className="text-[10px] font-black uppercase tracking-[0.2em] text-orange-600">Schritt {step + 1} von 5</span>
                  <div className="flex gap-1">
                    {steps.map((_, i) => (
                      <div key={i} className={`h-1.5 rounded-full transition-all ${i === step ? 'w-6 bg-orange-600' : 'w-1.5 bg-slate-200 dark:bg-slate-700'}`} />
