                    value={(answers as any)[currentStep.id]}
                    onChange={(e) => setAnswers({...answers, [currentStep.id]: e.target.value})}
                    placeholder={currentStep.placeholder}
                    className="w-full bg-slate-50 dark:bg-slate-800 border border-black/5 dark:border-white/5 rounded-2xl py-4 px-5 text-sm font-bold focus:ring-2 focus:ring-orange-500 outline-none transition-all"
