                        className={`w-full py-3 px-5 rounded-xl border text-left text-sm font-bold transition-all ${
                          (answers as any)[currentStep.id] === opt 
                            ? 'bg-orange-600 border-orange-600 text-white shadow-lg' 
                            : 'bg-slate-50 dark:bg-slate-800 border-black/5 dark:border-white/5 text-slate-600 dark:text-slate-300 hover:border-orange-500/30'
                        }`}
                      >
                        {opt}
                      </button>
                    ))}
                  </div>
                )}
              </div>

              <div className="flex gap-3 pt-4">
                <button 
                  disabled={step === 0}
                  onClick={() => setStep(s => s - 1)}
                  className="p-4 bg-slate-100 dark:bg-slate-800 rounded-2xl text-slate-400 disabled:opacity-30 hover:text-slate-600 transition-colors"
                >
                  <ChevronLeft className="w-6 h-6" />
                </button>
                {step < 4 ? (
                  <button 
                    disabled={!(answers as any)[currentStep.id]}
                    onClick={() => setStep(s => s + 1)}
                    className="flex-1 py-4 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-2 disabled:opacity-40 transition-all hover:scale-[1.02]"
                  >
                    Weiter <ChevronRight className="w-4 h-4" />
                  </button>
                ) : (
                  <button 
                    disabled={!(answers as any)[currentStep.id] || isLowCredits(10)}
                    onClick={handleGenerate}
                    className="flex-1 py-4 bg-orange-600 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-2 shadow-xl shadow-orange-600/20 hover:bg-orange-700 transition-all"
                  >
                    Thumbnail schmieden <Zap className="w-4 h-4 fill-current" />
                  </button>
                )}
              </div>
            </div>
          ) : (
            <div className="py-12 flex flex-col items-center text-center space-y-6">
              <div className="relative">
                <div className="w-20 h-20 bg-orange-600/10 rounded-[2rem] flex items-center justify-center">
                  <Loader2 className="w-10 h-10 text-orange-600 animate-spin" />
                </div>
                <div className="absolute inset-0 bg-orange-500/20 blur-2xl rounded-full animate-pulse"></div>
              </div>
              <div className="space-y-2">
                <h3 className="text-sm font-black uppercase tracking-widest text-slate-900 dark:text-white">{statusText}</h3>
                <div className="w-48 h-1.5 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden mx-auto">
                  <div className="h-full bg-orange-600 transition-all duration-300" style={{ width: `${progress}%` }} />
