  useCredits: (amount: number) => boolean;
  user: User | null;
  onGoToPricing?: () => void;
  onSaveDesign?: (design: Design) => void;
}

interface GeneratedResult {
  id: string;
  url: string;
  prompt: string;
  optimizedPrompt: string;
  isSaved?: boolean;
  sources?: {title: string, url: string}[];
}

export const StudioGenerate: React.FC<StudioGenerateProps> = ({ useCredits, user, onGoToPricing, onSaveDesign }) => {
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState({
    topic: '',
    subject: '',
    emotion: '',
    style: '',
    text: ''
  });

  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 4;
          if (prev < 70) return prev + 2;
          if (prev < 95) return prev + 0.5;
          return prev;
        });

        const texts = [
          "Strategie-Analyse...", 
          "Visuelle Hierarchie wird berechnet...", 
          "Rim-Lighting wird vorbereitet...", 
          "Psychologische Farbkorrektur...",
          "High-CTR Rendering läuft..."
        ];
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress]);

  const handleGenerate = async () => {
    // Kombiniert die 5 Antworten zu einem hochqualitativen Prompt-String
    const finalPrompt = `
      THEMA: ${answers.topic}. 
      FOKUS-MOTIV: ${answers.subject}. 
      EMOTIONALER TRIGGER: ${answers.emotion}. 
      VISUELLER STIL: ${answers.style}. 
      TEXT-OVERLAY-INHALT: ${answers.text}.
    `;

    const cost = 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt, sources } = await generateThumbnail(finalPrompt, answers.style as any, '16:9', false);
      useCredits(cost);
      setResults(prev => [{
        id: `res-${Date.now()}`,
        url,
        prompt: finalPrompt,
        optimizedPrompt: optimizedPrompt,
        sources: sources
      }, ...prev]);
      setProgress(100);
      setStep(0);
      setAnswers({ topic: '', subject: '', emotion: '', style: '', text: '' });
    } catch (err) {
      alert("Generierung fehlgeschlagen. Bitte versuche es erneut.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

