                        className={`w-full py-4 px-6 rounded-2xl border text-left text-sm font-bold transition-all flex items-center justify-between group/opt ${
                          (answers as any)[currentStep.id] === opt.value 
                            ? 'bg-orange-600 border-orange-600 text-white shadow-xl shadow-orange-600/20' 
                            : 'bg-slate-50 dark:bg-slate-800/50 border-black/5 dark:border-white/10 text-slate-600 dark:text-slate-300 hover:border-orange-500/30'
                        }`}
                      >
                        <span className="flex items-center gap-3">
                          <span className="text-xl">{opt.icon}</span>
                          {opt.label}
                        </span>
                        <ChevronRight className={`w-4 h-4 transition-transform ${ (answers as any)[currentStep.id] === opt.value ? 'translate-x-1 opacity-100' : 'opacity-0'}`} />
                      </button>
                    ))}
                  </div>
                )}
              </div>

              {/* Navigation */}
              <div className="flex gap-3 pt-6">
                <button 
                  disabled={step === 0}
