  const handleGenerate = async () => {
    const finalPrompt = `
      STORY: ${answers.topic}. 
      MOTIV: ${answers.subject}. 
      VIBE: ${answers.emotion}. 
      LOOK: ${answers.style}. 
      OVERLAY: ${answers.text}.
