      const { url, optimizedPrompt, sources } = await generateThumbnail(finalPrompt, answers.style as any, '16:9', false);
      useCredits(cost);
      setResults(prev => [{
        id: `res-${Date.now()}`,
        url,
        prompt: finalPrompt,
        optimizedPrompt: optimizedPrompt,
        sources: sources
      }, ...prev]);
      setProgress(100);
      setStep(0);
      setAnswers({ topic: '', subject: '', emotion: '', style: '', text: '' });
