type MainView = 'home' | 'pricing' | 'reviews' | 'examples' | 'studio';
type StudioView = 'dashboard' | 'generate' | 'channel' | 'analyze' | 'clone' | 'favorites';

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [studioView, setStudioView] = React.useState<StudioView>('dashboard');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [purchaseSuccess, setPurchaseSuccess] = useState<{ planName: string, amount: number } | null>(null);
  const [showTour, setShowTour] = useState(false);
  const [isNavigating, setIsNavigating] = useState(false);
  const [prefilledImageForRemake, setPrefilledImageForRemake] = useState<string | null>(null);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') {
      setIsDarkMode(false);
    } else {
      setIsDarkMode(true);
    }

    const savedUser = localStorage.getItem('thumbcraft_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      document.documentElement.classList.remove('light');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      document.documentElement.classList.add('light');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  useEffect(() => {
    if (user) {
      localStorage.setItem('thumbcraft_user', JSON.stringify(user));
    }
  }, [user]);

  const handleLogin = (email: string) => {
    const newUser: User = { 
      id: '1', 
      email: email, 
      name: email.split('@')[0], 
      credits: 30, 
      isLoggedIn: true,
      plan: 'Starter',
      savedDesigns: [],
      savedPrompts: []
    };
    setUser(newUser);
    setIsAuthOpen(false);
    setCurrentView('studio');
    setStudioView('dashboard');

    const hasSeenTour = localStorage.getItem('hasSeenStudioTour');
    if (!hasSeenTour) {
      setTimeout(() => setShowTour(true), 1500);
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('thumbcraft_user');
    setCurrentView('home');
    setStudioView('dashboard');
    setShowTour(false);
  };

  const toggleTheme = () => setIsDarkMode(prev => !prev);

  const useCredits = (amount: number): boolean => {
    if (!user || user.credits < amount) {
      setCurrentView('pricing');
      return false;
    }
    setUser({ ...user, credits: user.credits - amount });
    return true;
  };

  const handlePurchase = (plan: PricingPlan) => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    setUser({ ...user, credits: user.credits + plan.credits, plan: plan.name as any });
    setPurchaseSuccess({ planName: plan.name, amount: plan.credits });
    setTimeout(() => setPurchaseSuccess(null), 5000);
    setCurrentView('studio');
  };

  const handleSaveDesign = (design: Design) => {
    if (!user) return;
    const favorites = user.savedDesigns || [];
    if (favorites.some(f => f.id === design.id)) return;

    setUser({
      ...user,
      savedDesigns: [...favorites, design]
    });
  };

  const handleSavePrompt = (promptText: string, style: string) => {
    if (!user || !promptText.trim()) return;
    const saved = user.savedPrompts || [];
    if (saved.some(p => p.text === promptText)) return;

    const newPrompt: SavedPrompt = {
      id: Math.random().toString(36).substr(2, 9),
      text: promptText,
      style: style,
      createdAt: new Date().toISOString()
    };

    setUser({
      ...user,
      savedPrompts: [newPrompt, ...saved]
    });
  };

  const handleDeletePrompt = (id: string) => {
    if (!user) return;
    setUser({
      ...user,
      savedPrompts: (user.savedPrompts || []).filter(p => p.id !== id)
    });
  };

  const handleRemoveFavorite = (id: string) => {
    if (!user) return;
    setUser({
      ...user,
      savedDesigns: (user.savedDesigns || []).filter(d => d.id !== id)
    });
  };

  const handleModifyFavorite = (design: Design) => {
    setPrefilledImageForRemake(design.imageUrl);
    setStudioView('clone');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleNavigate = (view: MainView) => {
    if (view === currentView) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    if (view === 'studio' && !user) {
      setIsAuthOpen(true);
      return;
    }

    setIsNavigating(true);
    setTimeout(() => {
      setCurrentView(view);
      if (view === 'studio') {
        setStudioView('dashboard');
        const hasSeenTour = localStorage.getItem('hasSeenStudioTour');
        if (user && !hasSeenTour) {
          setTimeout(() => setShowTour(true), 1000);
        }
      } else {
        setShowTour(false);
      }
      window.scrollTo({ top: 0, behavior: 'smooth' });
      setIsNavigating(false);
    }, 200);
  };

  const handleBack = () => {
    if (currentView === 'studio' && studioView !== 'dashboard') {
      setStudioView('dashboard');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
      handleNavigate('home');
    }
  };

  const handleStartCreating = () => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    handleNavigate('studio');
  };

  const handleSelectStudioTool = (tool: StudioView) => {
    setStudioView(tool);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const completeTour = () => {
    setShowTour(false);
    localStorage.setItem('hasSeenStudioTour', 'true');
  };

  return (
    <div className={`min-h-screen transition-all duration-500 selection:bg-orange-500 selection:text-white bg-slate-950 dark:text-slate-100 relative`}>

      {/* Immersives Hintergrundbild für die Home Page - Originalzustand wiederhergestellt */}
      {currentView === 'home' && (
        <div className="fixed inset-0 -z-50 pointer-events-none overflow-hidden">
          <img 
            src="https://i.postimg.cc/R0Zm8Z08/IMG-7382.jpg" 
            className="w-full h-full object-cover scale-105" 
            alt="ThumbCraft AI Background" 
          />
          <div className="absolute inset-0 bg-slate-900/40 dark:bg-slate-950/60 backdrop-blur-[2px]" />
          <div className="absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-slate-950 via-slate-950/20 to-transparent" />
        </div>
      )}

      <main className={`relative z-10 transition-all duration-300 ${currentView === 'studio' ? 'lg:pl-72' : ''} ${isNavigating ? 'opacity-0 blur-sm' : 'opacity-100 blur-0'}`}>

        <Navbar 
          user={user} 
          currentView={currentView}
          onNavigate={handleNavigate} 
          onLoginClick={() => setIsAuthOpen(true)} 
          onLogout={handleLogout}
          isDarkMode={isDarkMode}
          toggleTheme={toggleTheme}
        />

        {/* Global Back Button */}
        {currentView !== 'home' && (
          <div className="fixed top-28 right-4 lg:right-12 z-50 animate-in fade-in slide-in-from-right-4 duration-500">
            <button 
              onClick={handleBack}
              className="flex items-center gap-2 px-5 py-2.5 bg-white/10 dark:bg-slate-800/80 backdrop-blur-md border border-white/10 rounded-2xl shadow-xl hover:shadow-orange-500/10 hover:border-orange-500/30 group transition-all active:scale-95"
            >
              <ArrowLeft className="w-4 h-4 text-orange-600 group-hover:-translate-x-1 transition-transform" />
              <span className="text-xs font-black uppercase tracking-widest text-white">Zurück</span>
            </button>
          </div>
        )}

        {currentView === 'home' && (
          <div className="animate-in fade-in duration-500">
            <Hero onStartCreating={handleStartCreating} onViewPricing={() => handleNavigate('pricing')} />
            <PlatformOverview />
            <HowItWorks onExplore={() => handleNavigate('examples')} />
            <ThumbnailShowcase onStartCreating={handleStartCreating} />
            <ComparisonTable />
            <Reviews />
            <Pricing onPurchase={handlePurchase} />
            <Footer />
          </div>
        )}

        {currentView === 'studio' && (
          <div className="pt-24 min-h-screen">
            <Sidebar 
              activeView={studioView} 
              onSelect={setStudioView} 
              user={user}
              onUpgrade={() => handleNavigate('pricing')}
            />

            <div className="p-4 lg:p-12 pb-32">
              <div key={studioView} className="animate-in fade-in slide-up duration-400">
                {studioView === 'dashboard' && (
                  <StudioSelection 
                    user={user} 
                    onSelectMode={(mode) => handleSelectStudioTool(mode as StudioView)} 
                    onGoToPricing={() => handleNavigate('pricing')}
                  />
                )}

                {studioView === 'generate' && (
                  <StudioGenerate 
                    useCredits={useCredits} 
                    user={user} 
                    onGoToPricing={() => handleNavigate('pricing')} 
                    onSaveDesign={handleSaveDesign}
                    onSavePrompt={handleSavePrompt}
                    onDeletePrompt={handleDeletePrompt}
                  />
                )}

                {studioView === 'clone' && (
                  <StudioRemake 
                    useCredits={useCredits} 
                    user={user} 
                    isCloneMode={true} 
                    prefilledImage={prefilledImageForRemake}
                    onSaveDesign={handleSaveDesign}
                  />
                )}

                {studioView === 'analyze' && (
                  <StudioAnalyze useCredits={useCredits} user={user} />
                )}

                {studioView === 'channel' && (
                  <StudioChannelAnalyze useCredits={useCredits} user={user} />
                )}

                {studioView === 'favorites' && (
                  <StudioFavorites 
                    designs={user?.savedDesigns || []} 
                    onRemove={handleRemoveFavorite}
                    onModify={handleModifyFavorite}
                  />
                )}
              </div>
            </div>
          </div>
        )}

        {currentView === 'pricing' && (
          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Pricing onPurchase={handlePurchase} />
            <Footer />
          </div>
        )}

        {currentView === 'reviews' && (
          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Reviews />
            <Footer />
          </div>
        )}

        {currentView === 'examples' && (
          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Examples onNavigateToStudio={handleStartCreating} />
            <Footer />
          </div>
        )}
      </main>

      {showTour && currentView === 'studio' && <StudioTour onComplete={completeTour} />}

      {isAuthOpen && (
        <AuthModal 
          isOpen={isAuthOpen} 
          onClose={() => setIsAuthOpen(false)} 
          onLogin={handleLogin} 
        />
      )}

      {purchaseSuccess && (
        <div className="fixed bottom-12 left-1/2 -translate-x-1/2 z-[100] bg-orange-600 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-bottom-8 duration-500">
          <CheckCircle className="w-6 h-6" />
          <div>
            <p className="text-sm font-black uppercase tracking-widest">Kauf erfolgreich!</p>
            <p className="text-xs font-bold opacity-80">{purchaseSuccess.amount} Credits zum {purchaseSuccess.planName}-Plan hinzugefügt.</p>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const getMimeType = (base64: string): string => {
  const match = base64.match(/^data:([^;]+);base64,/);
  return match ? match[1] : 'image/png';
};

const cleanBase64 = (base64: string): string => {
  return base64.includes(',') ? base64.split(',')[1] : base64;
};

/**
 * Optimiert den Nutzer-Prompt in Echtzeit für die UI.
 */
export const getQuickRefinement = async (userPrompt: string, style: string) => {
  if (userPrompt.trim().length < 3) return "";

  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `ACT AS AN ELITE YOUTUBE THUMBNAIL DESIGNER. 
      Optimiere NUR DIE TECHNISCHE BESCHREIBUNG des Prompts: "${userPrompt}" für den Stil "${style}".

      STRIKTE REGELN:
      - KEINE Illustrationen, kein "AI Art" Look.
      - Erstelle eine Photoshop-Komposition.
      - Nutze: "High-contrast volumetric lighting", "razor sharp subject focus", "hyper-realistic skin textures", "neon rim light", "vivid saturated colors", "blurred motion backgrounds".
      - Integriere visuelle Platzhalter für Text-Elemente.
      - Antworte NUR mit dem optimierten Prompt-Text.`,
    });
    return response.text?.replace(/^"|"$/g, '') || "";
  } catch (e) {
    return "";
  }
};

/**
 * Erstellt eine tiefgreifende Design-Strategie unter Einbeziehung von Markttrends.
 */
const optimizePromptWithMarketResearch = async (userPrompt: string, style: string, useSearch: boolean) => {
  const ai = getAI();

  let searchSources: any[] = [];
  let promptContext = "";

  if (useSearch) {
    const searchResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Identify high-CTR visual hooks, current color trends, and dominant thumbnail layouts for the niche: "${userPrompt}"`,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });
    promptContext = `MARKET RESEARCH DATA: ${searchResponse.text}`;
    searchSources = searchResponse.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Market Trend Analysis',
      url: chunk.web?.uri || ''
    })).filter((s: any) => s.url) || [];
  }

  const systemInstruction = `You are the World's Best YouTube Thumbnail Strategist. 
  Your goal is to engineer the highest possible Click-Through-Rate (CTR).

  CORE STRATEGIC PILLARS:
  1. MOBILE FIRST: Elements and TEXT must be huge, clear, and readable on a 5-inch screen.
  2. PSYCHOLOGICAL TRIGGERS: Exaggerated facial expressions, curiosity gaps.
  3. COMPOSITION: Professional Photoshop look (Composite photography).
  4. LIGHTING: Dominant Rim Lighting to separate the subject.
  5. TEXT RENDERING: Typography must be massive, bold, and high-impact. Use professional Photoshop-style text effects (strokes, shadows, gradients).

  Respond ONLY in JSON format.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Develop a high-conversion visual strategy for: "${userPrompt}" in the style of "${style}". 
      Incorporate these research insights: ${promptContext}`,
      config: {
        systemInstruction,
        thinkingConfig: { thinkingBudget: 32768 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            optimizedPrompt: { type: Type.STRING, description: "Highly technical prompt for the image AI including lighting, composition and typography specifics." },
            strategy: { type: Type.STRING, description: "The psychological reasoning behind this visual setup." }
          },
          required: ["optimizedPrompt", "strategy"]
        }
      }
    });
    const parsed = JSON.parse(response.text || '{}');
    return { ...parsed, sources: searchSources };
  } catch (e) {
    return { 
      optimizedPrompt: `${userPrompt}, hyper-realistic, professional lighting, octane render, 8k, vibrant colors`, 
      strategy: "Optimiert auf Basis von Branchen-Standard Best-Practices.", 
      sources: [] 
    };
  }
};

/**
 * Die finale Bildgenerierung mit optimierten Parametern.
 */
export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9", useMarketResearch: boolean = false, overlayText: string = "") => {
  const ai = getAI();

  const { optimizedPrompt, strategy, sources } = await optimizePromptWithMarketResearch(prompt, style, useMarketResearch);

  const textDirective = overlayText ? `
    TYPOGRAPHY DIRECTIVE: 
    - Render the text "${overlayText.toUpperCase()}" in a massive, ultra-bold, high-impact Sans-Serif font.
    - APPLY a thick black outline (stroke) and a heavy drop shadow for maximum readability.
    - USE a contrasting color for the font (e.g., Bright Yellow or White) against the background.
    - POSITION the text strategically so it does not cover the main subject but is the primary hook.
    - FONT STYLE: Professional Photoshop Graphic Design style.
  ` : '';

  const finalInstruction = `
    TASK: GENERATE A HIGH-CTR YOUTUBE THUMBNAIL COMPOSITE.
    STYLE: ${style} Professional Studio Aesthetic.

    CRITICAL QUALITY DIRECTIVES:
    - PHOTOREALISM: Use "Octane Render", "8k UHD", "Unreal Engine 5 quality".
    - SUBJECT DOMINANCE: The main character/object must take up 60% of the frame.
    - RIM LIGHTING: Intense backlight glow on the subject's edges.
    - TEXTURES: Razor sharp focus on details.
    ${textDirective}
    - COLORS: Vivid, ultra-saturated, cinematic color grading. 
    - NO SMOOTHNESS: Avoid the "plastic" AI look.

    SCENE DESCRIPTION: ${optimizedPrompt}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: finalInstruction }] },
      config: { 
        imageConfig: { 
          aspectRatio: aspectRatio as any,
          imageSize: "1K"
        } 
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return {
        url: `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`,
        optimizedPrompt: strategy,
        sources: sources
      };
    }
    throw new Error("Generierung fehlgeschlagen.");
  } catch (e: any) {
