export const analyzeYoutubeChannel = async (channelUrl: string) => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Führe ein professionelles YouTube Audit für den Kanal "${channelUrl}" durch. 
      Analysiere Branding, Thumbnail-Konsistenz, Zielgruppen-Ansprache und aktuelle Wettbewerbs-Trends in dieser Nische.
      Nutze Google Search, um aktuelle Viral-Trends für dieses Thema zu finden.
      Erstelle einen messbaren Aktionsplan zur Steigerung der Gesamt-CTR des Kanals.`,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            channelName: { type: Type.STRING },
            identitySummary: { type: Type.STRING },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
            weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
            actionPlan: { type: Type.ARRAY, items: { type: Type.STRING } },
            sources: { 
              type: Type.ARRAY, 
              items: { 
                type: Type.OBJECT, 
                properties: { title: { type: Type.STRING }, url: { type: Type.STRING } } 
              } 
            }
          },
          required: ["channelName", "identitySummary", "strengths", "weaknesses", "actionPlan"]
        }
      }
    });
    const parsed = JSON.parse(response.text || '{}');
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Audit Insight Source',
      url: chunk.web?.uri || ''
    })).filter((s: any) => s.url) || [];

    return { ...parsed, sources };
  } catch (e) {
    throw new Error("Kanal-Audit fehlgeschlagen.");
  }
};

