import { Wand2, Sparkles, Loader2, Download, Coins, Heart, Zap, MessageSquare, Target, ChevronRight, ChevronLeft, Layout, UserCircle, BrainCircuit, Eye, MousePointer2, HelpCircle, Type as TypeIcon } from 'lucide-react';
import React, { useState, useEffect } from 'react';
import { generateThumbnail } from '../services/geminiService';
import { User, Design } from '../types';

// Define the interface for props passed to StudioGenerate
interface StudioGenerateProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  onGoToPricing?: () => void;
  onSaveDesign?: (design: Design) => void;
  onSavePrompt?: (promptText: string, style: string) => void;
  onDeletePrompt?: (id: string) => void;
}

interface GeneratedResult {
  id: string;
  url: string;
  prompt: string;
  optimizedPrompt: string;
  isSaved?: boolean;
  sources?: {title: string, url: string}[];
}

// Fixed the error by including onSavePrompt and onDeletePrompt in component destructuring
export const StudioGenerate: React.FC<StudioGenerateProps> = ({ 
  useCredits, 
  user, 
  onGoToPricing, 
  onSaveDesign,
  onSavePrompt,
  onDeletePrompt
}) => {
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState({
    topic: '',
    subject: '',
    emotion: '',
    style: '',
    text: ''
  });

  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 4;
          if (prev < 70) return prev + 2;
          if (prev < 95) return prev + 0.5;
          return prev;
        });

        const texts = [
          "Strategie wird analysiert...", 
          "Visuelle Hierarchie wird berechnet...", 
          "Typografie-Setup wird vorbereitet...",
          "Licht-Setup wird gerendert...", 
          "Psychologische Farbkorrektur...",
          "High-CTR Finish wird aufgetragen..."
        ];
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress]);

  const handleGenerate = async () => {
    const finalPrompt = `
      THEMA/STORY: ${answers.topic}. 
      HAUPT-ELEMENT: ${answers.subject}. 
      GEFÜHL: ${answers.emotion}. 
      DESIGN-STIL: ${answers.style}. 
    `;

    const cost = 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt, sources } = await generateThumbnail(
        finalPrompt, 
        answers.style as any, 
        '16:9', 
        false,
        answers.text // Titel wird hier übergeben
      );
      useCredits(cost);
      setResults(prev => [{
        id: `res-${Date.now()}`,
        url,
        prompt: finalPrompt,
        optimizedPrompt: optimizedPrompt,
        sources: sources
      }, ...prev]);
      setProgress(100);
      setStep(0);
      setAnswers({ topic: '', subject: '', emotion: '', style: '', text: '' });
    } catch (err) {
      alert("Generierung fehlgeschlagen. Bitte versuche es erneut.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

  const emotions = [
    { label: 'Schock & Staunen', icon: '😱', value: 'Extreme shock, jaw drop, wide eyes, surprise' },
    { label: 'Neugier & Geheimnis', icon: '🤫', value: 'Intense mystery, hidden objects, curious look' },
    { label: 'Hype & Energie', icon: '🔥', value: 'High energy, action, glowing particles, power' },
    { label: 'Erfolg & Reichtum', icon: '💰', value: 'Luxury, winners vibe, money, achievement' },
    { label: 'Entspannt & Clean', icon: '✨', value: 'Aesthetic, minimalist, peaceful, high quality' }
  ];

  const styles = [
    { label: 'MrBeast Style', icon: '🔴', value: 'Aggressive saturation, giant objects, high contrast, viral look' },
    { label: 'Profi Studio', icon: '📸', value: 'High-end photography, cinematic lighting, soft background' },
    { label: 'Gaming / Neon', icon: '⚡', value: 'Cyberpunk glow, epic rim lighting, intense action colors' },
    { label: 'Story / Doku', icon: '📽️', value: 'Deep shadows, atmospheric, dramatic cinematic feeling' },
    { label: 'Vlog / Real', icon: '🤳', value: 'Natural but vivid, sharp focus on faces, lifestyle vibe' }
  ];

  const steps = [
    { 
      id: 'topic', 
      label: 'Was passiert im Video?', 
      description: 'Beschreibe kurz die Story oder den krassesten Moment.',
      placeholder: 'z.B. Ich habe 24h im Eis überlebt...',
      icon: <Target className="w-5 h-5" />,
      type: 'input'
    },
    { 
      id: 'subject', 
      label: 'Wer oder was ist der "Star"?', 
      description: 'Was soll man als Erstes sehen? (z.B. Dein Gesicht, ein Auto)',
      placeholder: 'z.B. Mein schockiertes Gesicht ganz nah...',
      icon: <UserCircle className="w-5 h-5" />,
      type: 'input'
    },
    { 
      id: 'emotion', 
      label: 'Wie sollen Leute sich fühlen?', 
      description: 'Wähle den emotionalen "Hook", der zum Klick führt.',
      options: emotions,
      icon: <BrainCircuit className="w-5 h-5" />,
      type: 'select'
    },
    { 
      id: 'style', 
      label: 'Welchen Look willst du?', 
      description: 'Wähle den Stil, der am besten zu deinem Kanal passt.',
      options: styles,
      icon: <Sparkles className="w-5 h-5" />,
      type: 'select'
    },
    { 
      id: 'text', 
      label: 'Der Thumbnail-Titel', 
      description: 'Welchen Text schreiben wir? (Nutze kurze, "laute" Wörter für CTR)',
      placeholder: 'z.B. NIE WIEDER! oder UNMÖGLICH',
      icon: <TypeIcon className="w-5 h-5" />,
      type: 'input'
    }
  ];

  const currentStep = steps[step];

  return (
    <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-12 animate-in fade-in duration-500">

      {/* Wizard Sidebar */}
      <div className="w-full lg:w-[420px] space-y-6">
        <div className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 dark:border-white/5 shadow-2xl sticky top-28 overflow-hidden">

          {/* Header */}
          <div className="flex justify-between items-center mb-10">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-orange-600 rounded-lg shadow-lg shadow-orange-600/20">
                <Zap className="w-5 h-5 text-white fill-current" />
              </div>
              <h2 className="text-xl font-black text-slate-900 dark:text-white">Studio Wizard</h2>
            </div>
            <div className="px-3 py-1 rounded-full bg-orange-600/10 text-[10px] font-black uppercase tracking-widest text-orange-600 flex items-center gap-2">
              <Coins className="w-3.5 h-3.5" /> 10 Credits
            </div>
          </div>

          {!loading ? (
            <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">

              {/* Progress */}
              <div className="space-y-4">
                <div className="flex justify-between items-center px-1">
                  <span className="text-[10px] font-black uppercase tracking-[0.2em] text-orange-600">Schritt {step + 1} von 5</span>
                  <div className="flex gap-1.5">
                    {steps.map((_, i) => (
                      <div key={i} className={`h-1.5 rounded-full transition-all duration-500 ${i === step ? 'w-8 bg-orange-600' : (i < step ? 'w-1.5 bg-orange-600/30' : 'w-1.5 bg-slate-200 dark:bg-slate-700')}`} />
                    ))}
                  </div>
                </div>

                <div className="space-y-1">
                  <h3 className="text-lg font-black text-slate-900 dark:text-white leading-tight">
                    {currentStep.label}
                  </h3>
                  <p className="text-xs font-medium text-slate-500 dark:text-slate-400">{currentStep.description}</p>
                </div>

                {currentStep.type === 'input' ? (
                  <div className="relative group">
                    <input 
                      type="text"
                      value={(answers as any)[currentStep.id]}
                      onChange={(e) => setAnswers({...answers, [currentStep.id]: e.target.value})}
                      placeholder={currentStep.placeholder}
                      className="w-full bg-slate-50 dark:bg-slate-800/50 border border-black/5 dark:border-white/10 rounded-2xl py-5 px-6 text-sm font-bold focus:ring-2 focus:ring-orange-600 outline-none transition-all group-hover:border-orange-500/30"
                      autoFocus
                    />
                    <div className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300">
                      {currentStep.icon}
                    </div>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 gap-2.5">
                    {currentStep.options?.map((opt: any) => (
                      <button
                        key={opt.label}
                        onClick={() => setAnswers({...answers, [currentStep.id]: opt.value})}
                        className={`w-full py-4 px-6 rounded-2xl border text-left text-sm font-bold transition-all flex items-center justify-between group/opt ${
                          (answers as any)[currentStep.id] === opt.value 
                            ? 'bg-orange-600 border-orange-600 text-white shadow-xl shadow-orange-600/20' 
                            : 'bg-slate-50 dark:bg-slate-800/50 border-black/5 dark:border-white/10 text-slate-600 dark:text-slate-300 hover:border-orange-500/30'
                        }`}
                      >
                        <span className="flex items-center gap-3">
                          <span className="text-xl">{opt.icon}</span>
                          {opt.label}
                        </span>
                        <ChevronRight className={`w-4 h-4 transition-transform ${ (answers as any)[currentStep.id] === opt.value ? 'translate-x-1 opacity-100' : 'opacity-0'}`} />
                      </button>
                    ))}
                  </div>
                )}
              </div>

              {/* Navigation */}
              <div className="flex gap-3 pt-6">
                <button 
                  disabled={step === 0}
                  onClick={() => setStep(s => s - 1)}
                  className="p-5 bg-slate-100 dark:bg-slate-800 rounded-2xl text-slate-400 disabled:opacity-30 hover:text-slate-600 transition-colors flex items-center justify-center"
                >
                  <ChevronLeft className="w-6 h-6" />
                </button>
                {step < 4 ? (
                  <button 
                    disabled={!(answers as any)[currentStep.id]}
                    onClick={() => setStep(s => s + 1)}
                    className="flex-1 py-5 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 disabled:opacity-40 transition-all hover:scale-[1.02] active:scale-95"
                  >
                    Weiter <ChevronRight className="w-4 h-4" />
                  </button>
                ) : (
                  <button 
                    disabled={!(answers as any)[currentStep.id] || isLowCredits(10)}
                    onClick={handleGenerate}
                    className="flex-1 py-5 bg-orange-600 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 shadow-xl shadow-orange-600/20 hover:bg-orange-700 transition-all active:scale-95"
                  >
                    Bild schmieden <Zap className="w-4 h-4 fill-current" />
                  </button>
                )}
              </div>
            </div>
          ) : (
            <div className="py-20 flex flex-col items-center text-center space-y-8 animate-in zoom-in-95">
              <div className="relative">
                <div className="w-24 h-24 bg-orange-600/10 rounded-[2.5rem] flex items-center justify-center">
                  <Loader2 className="w-12 h-12 text-orange-600 animate-spin" />
                </div>
                <div className="absolute inset-0 bg-orange-500/20 blur-[30px] rounded-full animate-pulse"></div>
              </div>
              <div className="space-y-4">
                <div className="space-y-1">
                  <h3 className="text-sm font-black uppercase tracking-[0.3em] text-slate-900 dark:text-white leading-relaxed">{statusText}</h3>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Perfekte Komposition wird erstellt</p>
                </div>
                <div className="w-48 h-1.5 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden mx-auto">
                  <div className="h-full bg-orange-600 transition-all duration-300" style={{ width: `${progress}%` }} />
                </div>
                <p className="text-[10px] font-black text-orange-600 uppercase tracking-[0.2em]">{Math.round(progress)}%</p>
              </div>
            </div>
          )}
        </div>

        {/* Info Card */}
        <div className="p-6 bg-slate-100 dark:bg-slate-900/50 rounded-[2rem] border border-black/5">
           <div className="flex items-start gap-4">
              <HelpCircle className="w-6 h-6 text-slate-400 shrink-0 mt-1" />
              <div>
                <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-1">Creator Tipp</h4>
                <p className="text-[11px] font-medium text-slate-400 leading-relaxed">Thumbnails mit extremen Emotionen und hohem Kontrast haben eine bis zu 40% höhere Klickrate. Trau dich, mutig zu sein!</p>
              </div>
           </div>
        </div>
      </div>

      {/* Main Preview Area */}
      <div className="flex-1 space-y-10 min-h-[600px]">
        {results.length > 0 ? (
          <div className="space-y-10 animate-in fade-in slide-in-from-bottom-8 duration-700">
            {results.map((res) => (
              <div key={res.id} className="bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 p-8 md:p-10 shadow-2xl relative group/card overflow-hidden">
                <div className="absolute top-0 right-0 p-12 opacity-[0.03] group-hover/card:opacity-[0.06] transition-opacity">
                  <Sparkles className="w-40 h-40" />
                </div>

                <div className="flex flex-col lg:flex-row gap-10">
                  <div className="flex-1 space-y-8">
                    <div className="relative aspect-video rounded-[2.5rem] overflow-hidden bg-slate-100 dark:bg-slate-800 group/img shadow-2xl border-4 border-white dark:border-slate-800">
                      <img src={res.url} className="w-full h-full object-cover saturate-[1.1] contrast-[1.05]" alt="Ergebnis" loading="lazy" />

                      {/* Interactive Overlays */}
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center gap-4">
                        <button 
                          onClick={() => { const a = document.createElement('a'); a.href = res.url; a.download = 'thumbcraft_result.png'; a.click(); }} 
                          className="p-5 bg-white text-slate-900 rounded-[1.5rem] shadow-2xl hover:scale-110 transition-transform flex items-center gap-2 font-black text-xs uppercase"
                        >
                          <Download className="w-5 h-5" /> Download
                        </button>
                        <button 
                          onClick={() => onSaveDesign?.({ id: res.id, imageUrl: res.url, prompt: res.prompt, createdAt: new Date().toISOString() })}
                          className="p-5 bg-rose-600 text-white rounded-[1.5rem] shadow-2xl hover:scale-110 transition-transform"
                        >
                          <Heart className="w-5 h-5 fill-current" />
                        </button>
                      </div>

                      <div className="absolute bottom-6 right-6 bg-black/80 px-2 py-1 rounded text-[10px] font-black text-white z-10">10:42</div>
                      <div className="absolute bottom-0 left-0 right-0 h-1.5 bg-red-600 shadow-[0_-2px_10px_rgba(220,38,38,0.4)]"></div>
                    </div>

                    <div className="p-6 bg-emerald-500/5 dark:bg-emerald-500/10 rounded-[2rem] border border-emerald-500/10">
                       <div className="flex items-center gap-3 mb-3">
                          <div className="p-1.5 bg-emerald-500 rounded-lg">
                            <Sparkles className="w-4 h-4 text-white" />
                          </div>
                          <span className="text-[10px] font-black uppercase text-emerald-600 dark:text-emerald-400 tracking-[0.2em]">Design Strategie</span>
                       </div>
                       <p className="text-xs font-bold text-slate-600 dark:text-slate-300 italic leading-relaxed">"{res.optimizedPrompt}"</p>
                    </div>
                  </div>

                  <div className="w-full lg:w-64 flex flex-col justify-center space-y-6">
                    <div className="p-8 bg-slate-50 dark:bg-slate-800/50 rounded-[2.5rem] border border-black/5 text-center relative overflow-hidden group/stats">
                      <div className="absolute inset-0 bg-emerald-500/5 opacity-0 group-hover/stats:opacity-100 transition-opacity" />
                      <div className="text-[10px] font-black uppercase text-slate-400 mb-2 tracking-widest">CTR Potenzial</div>
                      <div className="text-5xl font-black text-emerald-500 mb-1">{(7.5 + Math.random() * 6).toFixed(1)}%</div>
                      <div className="text-[9px] font-bold text-slate-400 uppercase tracking-widest leading-tight">Mobile-Optimiert</div>
                    </div>

                    <button className="w-full py-4 bg-slate-100 dark:bg-white/5 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 hover:bg-orange-600 hover:text-white transition-all flex items-center justify-center gap-2">
                      <Eye className="w-4 h-4" /> Vollbild Vorschau
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="h-full flex flex-col items-center justify-center text-center p-16 bg-slate-50/50 dark:bg-slate-900/40 rounded-[4rem] border-4 border-dashed border-black/5 dark:border-white/10 animate-in zoom-in-95 duration-700">
            <div className="relative mb-10">
              <div className="absolute inset-0 bg-orange-600/20 blur-3xl rounded-full animate-pulse"></div>
              <div className="relative w-32 h-32 bg-white dark:bg-slate-800 rounded-[3rem] shadow-2xl flex items-center justify-center border border-black/5">
                <Layout className="w-14 h-14 text-slate-200" />
              </div>
            </div>
            <h3 className="text-3xl font-black mb-4 text-slate-900 dark:text-white tracking-tight">Deine Leinwand wartet</h3>
            <p className="text-slate-500 dark:text-slate-400 text-lg max-w-sm font-medium leading-relaxed">Vervollständige den Strategie-Check links, um dein erstes KI-gestütztes Hochleistungs-Thumbnail zu schmieden.</p>
          </div>
        )}
      </div>
    </div>
  );
};

