import React, { useState, useEffect } from 'react';
import { 
  Wand2, Sparkles, Loader2, Download, Coins, Heart, 
  Zap, Target, Eye, HelpCircle, Type as TypeIcon,
  Search, Info, History, Trash2, ArrowRight, ExternalLink
} from 'lucide-react';
import { generateThumbnail } from '../services/geminiService';
import { User, Design } from '../types';
import { Tooltip } from './Tooltip';

interface StudioGenerateProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  onGoToPricing?: () => void;
  onSaveDesign?: (design: Design) => void;
  onSavePrompt?: (promptText: string, style: string) => void;
  onDeletePrompt?: (id: string) => void;
}

interface GeneratedResult {
  id: string;
  url: string;
  prompt: string;
  optimizedPrompt: string;
  isSaved?: boolean;
  sources?: {title: string, url: string}[];
}

export const StudioGenerate: React.FC<StudioGenerateProps> = ({ 
  useCredits, 
  user, 
  onGoToPricing, 
  onSaveDesign,
  onSavePrompt,
  onDeletePrompt
}) => {
  const [prompt, setPrompt] = useState('');
  const [overlayText, setOverlayText] = useState('');
  const [selectedStyle, setSelectedStyle] = useState('MrBeast Style');
  const [useMarketResearch, setUseMarketResearch] = useState(false);

  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 4;
          if (prev < 70) return prev + 2;
          if (prev < 95) return prev + 0.5;
          return prev;
        });

        const texts = [
          "Konzept wird analysiert...", 
          useMarketResearch ? "Markt-Trends werden via Google gescannt..." : "Stil-Vorgaben werden geladen...",
          "Visuelle Hierarchie wird berechnet...", 
          "Typografie-Setup wird vorbereitet...",
          "Licht-Setup wird gerendert...", 
          "Psychologische Farbkorrektur...",
          "High-CTR Finish wird aufgetragen..."
        ];
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress, useMarketResearch]);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;

    const cost = 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt, sources } = await generateThumbnail(
        prompt, 
        selectedStyle, 
        '16:9', 
        useMarketResearch,
        overlayText
      );

      useCredits(cost);

      if (onSavePrompt) {
        onSavePrompt(prompt, selectedStyle);
      }

      setResults(prev => [{
        id: `res-${Date.now()}`,
        url,
        prompt: prompt,
        optimizedPrompt: optimizedPrompt,
        sources: sources
      }, ...prev]);

      setProgress(100);
      setPrompt('');
      setOverlayText('');
    } catch (err) {
      alert("Generierung fehlgeschlagen. Bitte versuche es erneut.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

  const handleSaveToFavorites = (res: GeneratedResult) => {
    if (onSaveDesign) {
      onSaveDesign({
        id: res.id,
        imageUrl: res.url,
        prompt: res.prompt,
        createdAt: new Date().toISOString(),
        style: selectedStyle,
        aspectRatio: '16:9'
      });
      setResults(prev => prev.map(r => r.id === res.id ? { ...r, isSaved: true } : r));
    }
  };

  const styles = [
    { label: 'MrBeast Style', icon: '🔴', value: 'MrBeast Style' },
    { label: 'Profi Studio', icon: '📸', value: 'Profi Studio' },
    { label: 'Gaming / Neon', icon: '⚡', value: 'Gaming / Neon' },
    { label: 'Story / Doku', icon: '📽️', value: 'Story / Doku' },
    { label: 'Vlog / Real', icon: '🤳', value: 'Vlog / Real' }
  ];

  return (
    <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-12 animate-in fade-in duration-700">

      {/* Input Sidebar: Die Schmiede */}
      <div className="w-full lg:w-[420px] space-y-6 shrink-0">
        <div className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 dark:border-white/10 shadow-2xl sticky top-28 overflow-hidden">
          <div className="absolute top-0 right-0 w-32 h-32 bg-orange-600/5 blur-3xl rounded-full" />

          {/* Header */}
          <div className="flex justify-between items-center mb-8 relative z-10">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-orange-600 rounded-xl shadow-lg shadow-orange-600/20">
                <Zap className="w-5 h-5 text-white fill-current" />
              </div>
              <div>
                <h2 className="text-xl font-black text-slate-900 dark:text-white leading-none">Die Schmiede</h2>
                <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">KI Design Engine</p>
              </div>
            </div>
            <div className="px-3 py-1.5 rounded-xl bg-orange-600/10 text-[10px] font-black uppercase tracking-widest text-orange-600 flex items-center gap-2 border border-orange-600/10">
              <Coins className="w-3.5 h-3.5" /> 10 Credits
            </div>
          </div>

          {!loading ? (
            <div className="space-y-6 animate-in fade-in duration-300 relative z-10">

              {/* Main Prompt Kasten */}
              <div className="space-y-3">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Thumbnail Vision</label>
                  <Tooltip text="Beschreibe was auf dem Bild passieren soll. Je detaillierter, desto besser.">
                    <HelpCircle className="w-3.5 h-3.5 text-slate-300 cursor-help" />
                  </Tooltip>
                </div>
                <div className="relative group">
                  <textarea 
                    value={prompt}
                    onChange={(e) => setPrompt(e.target.value)}
                    placeholder="z.B. Ein glücklicher Mann hält ein goldenes Ticket vor einem bunten Freizeitpark..."
                    className="w-full h-32 bg-slate-50 dark:bg-slate-800/50 border border-black/10 dark:border-white/10 rounded-2xl p-5 text-sm font-bold focus:ring-4 focus:ring-orange-600/10 outline-none transition-all resize-none placeholder:text-slate-400 text-slate-900 dark:text-white"
                  />
                  <div className="absolute right-4 bottom-4 text-slate-300">
                    <Target className="w-5 h-5 opacity-20" />
                  </div>
                </div>
              </div>

              {/* Title Input */}
              <div className="space-y-3">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Text auf dem Bild (Overlay)</label>
                <div className="relative group">
                  <input 
                    type="text"
                    value={overlayText}
                    onChange={(e) => setOverlayText(e.target.value)}
                    placeholder="z.B. GEWINNER! oder 1 MILLION"
                    className="w-full bg-slate-50 dark:bg-slate-800/50 border border-black/10 dark:border-white/10 rounded-2xl py-4 px-5 text-sm font-bold focus:ring-4 focus:ring-orange-600/10 outline-none transition-all placeholder:text-slate-400 text-slate-900 dark:text-white"
                  />
                  <div className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300">
                    <TypeIcon className="w-4 h-4 opacity-40" />
                  </div>
                </div>
              </div>

              {/* Market Research Toggle */}
              <button 
                onClick={() => setUseMarketResearch(!useMarketResearch)}
                className={`w-full p-4 rounded-2xl border flex items-center justify-between transition-all ${
                  useMarketResearch 
                    ? 'bg-blue-600/10 border-blue-600/30 text-blue-600' 
                    : 'bg-slate-50 dark:bg-slate-800/30 border-black/5 dark:border-white/5 text-slate-500'
                }`}
              >
                <div className="flex items-center gap-3">
                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${useMarketResearch ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-200 dark:bg-slate-700'}`}>
                    <Search className="w-4 h-4" />
                  </div>
                  <div className="text-left">
                    <p className="text-[10px] font-black uppercase tracking-widest leading-none mb-1">Markt-Recherche</p>
                    <p className="text-[8px] font-bold opacity-60 uppercase">Echtzeit Trends via Google</p>
                  </div>
                </div>
                <div className={`w-10 h-5 rounded-full relative transition-colors ${useMarketResearch ? 'bg-blue-600' : 'bg-slate-300'}`}>
                  <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${useMarketResearch ? 'left-6' : 'left-1'}`} />
                </div>
              </button>

              {/* Style Selection */}
              <div className="space-y-3">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Design Stil</label>
                <div className="grid grid-cols-2 gap-2">
                  {styles.map((style) => (
                    <button
                      key={style.value}
                      onClick={() => setSelectedStyle(style.value)}
                      className={`py-3 px-4 rounded-xl border text-[10px] font-black uppercase tracking-wider transition-all flex items-center gap-2 ${
                        selectedStyle === style.value 
                          ? 'bg-orange-600 border-orange-600 text-white shadow-lg shadow-orange-600/20' 
                          : 'bg-slate-50 dark:bg-slate-800 border-black/10 dark:border-white/10 text-slate-500 hover:border-orange-500/30'
                      }`}
                    >
                      <span className="text-sm">{style.icon}</span>
                      {style.label.split(' ')[0]}
                    </button>
                  ))}
                </div>
              </div>

              <button 
                disabled={!prompt.trim() || isLowCredits(10)}
                onClick={handleGenerate}
                className="w-full mt-4 py-5 bg-orange-600 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 shadow-xl shadow-orange-600/20 hover:bg-orange-700 transition-all active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed group"
              >
                Bild schmieden <Zap className="w-4 h-4 fill-current group-hover:scale-110 transition-transform" />
              </button>
            </div>
          ) : (
            <div className="py-20 flex flex-col items-center text-center space-y-8 animate-in zoom-in-95">
              <div className="relative">
                <div className="w-24 h-24 bg-orange-600/10 rounded-[2.5rem] flex items-center justify-center">
                  <Loader2 className="w-12 h-12 text-orange-600 animate-spin" />
                </div>
                <div className="absolute inset-0 bg-orange-500/20 blur-[30px] rounded-full animate-pulse"></div>
              </div>
              <div className="space-y-4">
                <div className="space-y-1">
                  <h3 className="text-sm font-black uppercase tracking-[0.3em] text-slate-900 dark:text-white leading-relaxed">{statusText}</h3>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Die KI arbeitet für deinen Erfolg</p>
                </div>
                <div className="w-48 h-1.5 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden mx-auto">
                  <div 
                    className="h-full bg-orange-600 transition-all duration-300 ease-out shadow-[0_0_15px_rgba(249,115,22,0.5)]" 
                    style={{ width: `${progress}%` }} 
                  />
                </div>
              </div>
            </div>
          )}
        </div>

        {/* History / Saved Prompts Preview */}
        {user?.savedPrompts && user.savedPrompts.length > 0 && (
          <div className="p-6 bg-white/50 dark:bg-slate-900/50 rounded-[2rem] border border-black/5 dark:border-white/5 backdrop-blur-md">
            <h3 className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 flex items-center gap-2">
              <History className="w-3.5 h-3.5" /> Letzte Prompts
            </h3>
            <div className="space-y-2">
              {user.savedPrompts.slice(0, 3).map((p) => (
                <button 
                  key={p.id}
                  onClick={() => { setPrompt(p.text); setSelectedStyle(p.style); }}
                  className="w-full text-left p-3 rounded-xl bg-white dark:bg-slate-800 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors border border-black/5"
                >
                  <p className="text-[10px] font-bold text-slate-600 dark:text-slate-300 line-clamp-1">{p.text}</p>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Results Section */}
      <div className="flex-1 space-y-12">
        {results.length > 0 ? (
          <div className="grid gap-12">
            {results.map((res, idx) => (
              <div 
                key={res.id} 
                className="group relative animate-in slide-in-from-bottom-8 duration-700"
                style={{ animationDelay: `${idx * 150}ms` }}
              >
                <div className="bg-white dark:bg-slate-900 rounded-[3.5rem] p-8 md:p-12 shadow-2xl border border-black/5 dark:border-white/10 overflow-hidden">
                  <div className="grid lg:grid-cols-2 gap-10">

                    {/* Image Result */}
                    <div className="space-y-6">
                      <div className="aspect-video rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-white dark:border-slate-800 relative group/img">
                        <img src={res.url} className="w-full h-full object-cover saturate-[1.1] contrast-[1.05]" alt="Thumbnail Result" />

                        {/* Status Overlay */}
                        <div className="absolute top-6 left-6 flex gap-2">
                           <div className="px-4 py-2 bg-black/60 backdrop-blur-md text-white text-[10px] font-black uppercase rounded-xl border border-white/10 flex items-center gap-2">
                             <Eye className="w-3.5 h-3.5 text-orange-500" /> High-CTR Render
                           </div>
                        </div>

                        {/* Hover Actions */}
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center gap-3">
                           <button 
                            onClick={() => handleSaveToFavorites(res)}
                            disabled={res.isSaved}
                            className={`p-4 rounded-2xl shadow-xl transition-all hover:scale-110 active:scale-90 ${res.isSaved ? 'bg-rose-500 text-white' : 'bg-white text-rose-500 hover:bg-rose-50'}`}
                           >
                             <Heart className={`w-6 h-6 ${res.isSaved ? 'fill-current' : ''}`} />
                           </button>
                           <button 
                            onClick={() => {
                              const link = document.createElement('a');
                              link.href = res.url;
                              link.download = `thumbcraft_${Date.now()}.png`;
                              link.click();
                            }}
                            className="p-4 bg-white text-slate-900 rounded-2xl shadow-xl transition-all hover:scale-110 active:scale-90"
                           >
                             <Download className="w-6 h-6" />
                           </button>
                        </div>
                      </div>

                      <div className="flex gap-4">
                        <button 
                          onClick={() => {
                            const link = document.createElement('a');
                            link.href = res.url;
                            link.download = `thumbcraft_4k_${Date.now()}.png`;
                            link.click();
                          }}
                          className="flex-1 py-5 bg-orange-600 hover:bg-orange-700 text-white rounded-2xl font-black text-sm uppercase tracking-widest flex items-center justify-center gap-3 shadow-xl transition-all active:scale-95"
                        >
                          <Download className="w-5 h-5" /> In 4K Herunterladen
                        </button>
                      </div>
                    </div>

                    {/* Insights & Strategy */}
                    <div className="flex flex-col h-full">
                      <div className="flex-1 space-y-8">
                        <div>
                          <h4 className="text-[10px] font-black uppercase tracking-widest text-orange-600 mb-3 flex items-center gap-2">
                            <Sparkles className="w-3.5 h-3.5" /> Design Strategie
                          </h4>
                          <p className="text-sm font-bold text-slate-700 dark:text-slate-300 leading-relaxed bg-slate-50 dark:bg-slate-800/50 p-6 rounded-[2rem] border border-black/5">
                            {res.optimizedPrompt}
                          </p>
                        </div>

                        {res.sources && res.sources.length > 0 && (
                          <div className="space-y-4">
                            <h4 className="text-[10px] font-black uppercase tracking-widest text-blue-500 flex items-center gap-2">
                              <Search className="w-3.5 h-3.5" /> Google Trends Insights
                            </h4>
                            <div className="grid gap-2">
                              {res.sources.map((source, sIdx) => (
                                <a 
                                  key={sIdx} 
                                  href={source.url} 
                                  target="_blank" 
                                  rel="noopener noreferrer"
