import React, { useState, useEffect } from 'react';
import { 
  Wand2, Sparkles, Loader2, Download, Coins, Heart, 
  Zap, Target, Eye, HelpCircle, Type as TypeIcon,
  Search, Info, History, Trash2, ArrowRight, ExternalLink,
  Image as ImageIcon
} from 'lucide-react';
import { generateThumbnail } from '../services/geminiService';
import { User, Design } from '../types';
import { Tooltip } from './Tooltip';

interface StudioGenerateProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  onGoToPricing?: () => void;
  onSaveDesign?: (design: Design) => void;
  onSavePrompt?: (promptText: string, style: string) => void;
  onDeletePrompt?: (id: string) => void;
}

interface GeneratedResult {
  id: string;
  url: string;
  prompt: string;
  optimizedPrompt: string;
  isSaved?: boolean;
  sources?: {title: string, url: string}[];
}

export const StudioGenerate: React.FC<StudioGenerateProps> = ({ 
  useCredits, 
  user, 
  onGoToPricing, 
  onSaveDesign,
  onSavePrompt,
  onDeletePrompt
}) => {
  const [prompt, setPrompt] = useState('');
  const [overlayText, setOverlayText] = useState('');
  const [selectedStyle, setSelectedStyle] = useState('MrBeast Style');
  const [useMarketResearch, setUseMarketResearch] = useState(false);

  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 4;
          if (prev < 70) return prev + 2;
          if (prev < 95) return prev + 0.5;
          return prev;
        });

        const texts = [
          "Konzept wird analysiert...", 
          useMarketResearch ? "Markt-Trends werden via Google gescannt..." : "Stil-Vorgaben werden geladen...",
          "Visuelle Hierarchie wird berechnet...", 
          "Typografie-Setup wird vorbereitet...",
          "Licht-Setup wird gerendert...", 
          "Psychologische Farbkorrektur...",
          "High-CTR Finish wird aufgetragen..."
        ];
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress, useMarketResearch]);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;

    const cost = 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt, sources } = await generateThumbnail(
        prompt, 
        selectedStyle, 
        '16:9', 
        useMarketResearch,
        overlayText
      );

      useCredits(cost);

      if (onSavePrompt) {
        onSavePrompt(prompt, selectedStyle);
      }

      setResults(prev => [{
        id: `res-${Date.now()}`,
        url,
        prompt: prompt,
        optimizedPrompt: optimizedPrompt,
        sources: sources
      }, ...prev]);

      setProgress(100);
      setPrompt('');
      setOverlayText('');
    } catch (err) {
      alert("Generierung fehlgeschlagen. Bitte versuche es erneut.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

  const handleSaveToFavorites = (res: GeneratedResult) => {
    if (onSaveDesign) {
      onSaveDesign({
        id: res.id,
        imageUrl: res.url,
        prompt: res.prompt,
        createdAt: new Date().toISOString(),
        style: selectedStyle,
        aspectRatio: '16:9'
      });
      setResults(prev => prev.map(r => r.id === res.id ? { ...r, isSaved: true } : r));
    }
  };

  const styles = [
    { label: 'MrBeast Style', icon: '🔴', value: 'MrBeast Style' },
    { label: 'Profi Studio', icon: '📸', value: 'Profi Studio' },
    { label: 'Gaming / Neon', icon: '⚡', value: 'Gaming / Neon' },
    { label: 'Story / Doku', icon: '📽️', value: 'Story / Doku' },
    { label: 'Vlog / Real', icon: '🤳', value: 'Vlog / Real' }
  ];

  return (
    <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-12 animate-in fade-in duration-700">

      {/* Input Sidebar: Die Schmiede */}
      <div className="w-full lg:w-[420px] space-y-6 shrink-0">
        <div className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 dark:border-white/10 shadow-2xl sticky top-28 overflow-hidden">
          <div className="absolute top-0 right-0 w-32 h-32 bg-orange-600/5 blur-3xl rounded-full" />

          {/* Header */}
          <div className="flex justify-between items-center mb-8 relative z-10">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-orange-600 rounded-xl shadow-lg shadow-orange-600/20">
                <Zap className="w-5 h-5 text-white fill-current" />
