import React, { useState, useEffect } from 'react';
import { 
  Wand2, Sparkles, Loader2, Download, Coins, Heart, 
  Zap, Target, Eye, HelpCircle, Type as TypeIcon,
  Search, Info, History, Trash2, ArrowRight, ArrowLeft,
  ExternalLink, Check, MessageSquare, Users, BrainCircuit,
  Image as ImageIcon
} from 'lucide-react';
import { generateThumbnail } from '../services/geminiService';
import { User, Design } from '../types';
import { Tooltip } from './Tooltip';

interface StudioGenerateProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  onGoToPricing?: () => void;
  onSaveDesign?: (design: Design) => void;
  onSavePrompt?: (promptText: string, style: string) => void;
  onDeletePrompt?: (id: string) => void;
}

interface GeneratedResult {
  id: string;
  url: string;
  prompt: string;
  optimizedPrompt: string;
  isSaved?: boolean;
  sources?: {title: string, url: string}[];
}

interface WizardStep {
  id: number;
  question: string;
  sub: string;
  key: keyof typeof initialFormData;
  icon: any;
  placeholder: string;
}

const initialFormData = {
  topic: '',
  audience: '',
  emotion: '',
  visuals: '',
  overlayText: '',
  notes: ''
};

export const StudioGenerate: React.FC<StudioGenerateProps> = ({ 
  useCredits, 
  user, 
  onGoToPricing, 
  onSaveDesign,
  onSavePrompt,
}) => {
  const [step, setStep] = useState(0);
  const [formData, setFormData] = useState(initialFormData);
  const [selectedStyle, setSelectedStyle] = useState('MrBeast Style');
  const [useMarketResearch, setUseMarketResearch] = useState(false);

  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);

  const steps: WizardStep[] = [
    { id: 0, question: "Was ist das Thema deines Videos?", sub: "Beschreibe kurz den Kerninhalt.", key: 'topic', icon: MessageSquare, placeholder: "z.B. 24 Stunden im Wald überleben..." },
    { id: 1, question: "Wer ist deine Zielgruppe?", sub: "Für wen ist dieser Content gemacht?", key: 'audience', icon: Users, placeholder: "z.B. Outdoor-Fans, Jugendliche, Survival-Interessierte..." },
    { id: 2, question: "Welche Emotion soll es auslösen?", sub: "Psychologischer Trigger (Schock, Freude, Neugier).", key: 'emotion', icon: BrainCircuit, placeholder: "z.B. Extremer Schock und Todesangst..." },
    { id: 3, question: "Welche visuellen Elemente sind wichtig?", sub: "Hauptperson, Hintergrund, spezielle Objekte.", key: 'visuals', icon: ImageIcon, placeholder: "z.B. Ich im Vordergrund mit zerrissenem Shirt, dunkler Wald im Hintergrund..." },
    { id: 4, question: "Welcher Text soll auf dem Bild stehen?", sub: "Kurz, knackig und gut lesbar.", key: 'overlayText', icon: TypeIcon, placeholder: "z.B. ICH GEBE AUF! oder 0% ÜBERLEBENSCHANCE" },
    { id: 5, question: "Spezielle Anmerkungen?", sub: "Gibt es noch etwas, das wir beachten sollen?", key: 'notes', icon: Sparkles, placeholder: "z.B. Bitte viel blauen Glow verwenden und mein Gesicht sehr hell machen..." }
  ];

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 4;
          if (prev < 70) return prev + 2;
          if (prev < 95) return prev + 0.5;
          return prev;
        });

        const texts = [
          "Informationen werden synthetisiert...", 
          "Visuelle Hierarchie wird berechnet...", 
          useMarketResearch ? "Markt-Trends werden via Google gescannt..." : "Stil-Vorgaben werden geladen...",
          "Psychologische Farbkorrektur wird angewendet...",
          "High-CTR Finish wird aufgetragen..."
        ];
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress, useMarketResearch]);

  const handleGenerate = async () => {
    const fullPrompt = `
      VIDEO TOPIC: ${formData.topic}
      TARGET AUDIENCE: ${formData.audience}
      EMOTIONAL HOOK: ${formData.emotion}
      VISUAL ELEMENTS: ${formData.visuals}
      ADDITIONAL NOTES: ${formData.notes}
    `.trim();

    const cost = 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt, sources } = await generateThumbnail(
        fullPrompt, 
        selectedStyle, 
        '16:9', 
        useMarketResearch,
        formData.overlayText
      );

      useCredits(cost);

      if (onSavePrompt) {
        onSavePrompt(formData.topic, selectedStyle);
      }

      setResults(prev => [{
        id: `res-${Date.now()}`,
        url,
        prompt: formData.topic,
        optimizedPrompt: optimizedPrompt,
        sources: sources
      }, ...prev]);

      setProgress(100);
      setFormData(initialFormData);
      setStep(0);
    } catch (err) {
      alert("Generierung fehlgeschlagen. Bitte versuche es erneut.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

  const nextStep = () => {
    if (step < steps.length - 1) setStep(step + 1);
  };

  const prevStep = () => {
    if (step > 0) setStep(step - 1);
  };

  const styles = [
    { label: 'MrBeast Style', icon: '🔴', value: 'MrBeast Style' },
    { label: 'Profi Studio', icon: '📸', value: 'Profi Studio' },
    { label: 'Gaming / Neon', icon: '⚡', value: 'Gaming / Neon' },
    { label: 'Story / Doku', icon: '📽️', value: 'Story / Doku' },
    { label: 'Vlog / Real', icon: '🤳', value: 'Vlog / Real' }
  ];

  return (
    <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-12 animate-in fade-in duration-700">

      {/* Input Sidebar: Der Wizard */}
      <div className="w-full lg:w-[450px] space-y-6 shrink-0">
        <div className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 dark:border-white/10 shadow-2xl sticky top-28 overflow-hidden">
          <div className="absolute top-0 right-0 w-32 h-32 bg-orange-600/5 blur-3xl rounded-full" />

          {/* Progress Header */}
          <div className="flex justify-between items-center mb-8 relative z-10">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-orange-600 rounded-xl shadow-lg shadow-orange-600/20">
                <Zap className="w-5 h-5 text-white fill-current" />
              </div>
              <div>
                <h2 className="text-xl font-black text-slate-900 dark:text-white leading-none">Die Schmiede</h2>
                <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">Geführter Design-Prozess</p>
              </div>
            </div>
            <div className="px-3 py-1.5 rounded-xl bg-orange-600/10 text-[10px] font-black uppercase tracking-widest text-orange-600 flex items-center gap-2">
              <Coins className="w-3.5 h-3.5" /> 10 Credits
            </div>
          </div>

          {!loading ? (
            <div className="space-y-8 animate-in fade-in duration-300 relative z-10">

              {/* Progress Bar Steps */}
              <div className="flex gap-1.5">
                {steps.map((_, i) => (
                  <div key={i} className={`h-1.5 flex-1 rounded-full transition-all duration-500 ${i <= step ? 'bg-orange-600' : 'bg-slate-100 dark:bg-slate-800'}`} />
                ))}
              </div>

              {/* Current Question */}
              <div className="space-y-4 animate-in slide-in-from-right-4 duration-500" key={step}>
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-orange-500/10 rounded-2xl flex items-center justify-center text-orange-600">
                    {React.createElement(steps[step].icon, { className: "w-6 h-6" })}
                  </div>
                  <div>
                    <h3 className="text-sm font-black text-slate-900 dark:text-white leading-tight uppercase tracking-wider">{steps[step].question}</h3>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">{steps[step].sub}</p>
                  </div>
                </div>

                <div className="relative group">
                  {step === 4 ? ( // Overlay Text Input
                    <input 
                      type="text"
                      value={formData[steps[step].key]}
                      onChange={(e) => setFormData({...formData, [steps[step].key]: e.target.value})}
                      placeholder={steps[step].placeholder}
                      className="w-full bg-slate-50 dark:bg-slate-800/50 border border-black/10 dark:border-white/10 rounded-2xl py-5 px-6 text-sm font-bold focus:ring-4 focus:ring-orange-600/10 outline-none transition-all placeholder:text-slate-400 text-slate-900 dark:text-white"
                      autoFocus
                    />
                  ) : (
                    <textarea 
                      value={formData[steps[step].key]}
                      onChange={(e) => setFormData({...formData, [steps[step].key]: e.target.value})}
                      placeholder={steps[step].placeholder}
                      className="w-full h-32 bg-slate-50 dark:bg-slate-800/50 border border-black/10 dark:border-white/10 rounded-2xl p-6 text-sm font-bold focus:ring-4 focus:ring-orange-600/10 outline-none transition-all resize-none placeholder:text-slate-400 text-slate-900 dark:text-white"
                      autoFocus
                    />
                  )}
                </div>
              </div>

              {/* Wizard Controls */}
              <div className="flex gap-3">
                {step > 0 && (
                  <button 
                    onClick={prevStep}
                    className="flex-1 py-4 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-slate-200 transition-all"
                  >
                    <ArrowLeft className="w-3.5 h-3.5" /> Zurück
                  </button>
                )}

                {step < steps.length - 1 ? (
                  <button 
                    onClick={nextStep}
                    disabled={!formData[steps[step].key].trim()}
                    className="flex-[2] py-4 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 hover:opacity-90 transition-all disabled:opacity-40"
                  >
                    Nächster Schritt <ArrowRight className="w-3.5 h-3.5" />
                  </button>
                ) : (
                  <div className="flex-[2] space-y-4">
                     {/* Market Research Toggle in Final Step */}
                     <button 
                      onClick={() => setUseMarketResearch(!useMarketResearch)}
                      className={`w-full p-4 rounded-2xl border flex items-center justify-between transition-all ${
                        useMarketResearch 
                          ? 'bg-blue-600/10 border-blue-600/30 text-blue-600' 
                          : 'bg-slate-50 dark:bg-slate-800/30 border-black/5 dark:border-white/5 text-slate-500'
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <Search className="w-4 h-4" />
                        <span className="text-[10px] font-black uppercase tracking-widest">Markt-Trends nutzen</span>
                      </div>
                      <div className={`w-10 h-5 rounded-full relative transition-colors ${useMarketResearch ? 'bg-blue-600' : 'bg-slate-300'}`}>
                        <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${useMarketResearch ? 'left-6' : 'left-1'}`} />
                      </div>
                    </button>

                    <button 
                      onClick={handleGenerate}
                      disabled={isLowCredits(10)}
                      className="w-full py-5 bg-orange-600 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 shadow-xl shadow-orange-600/20 hover:bg-orange-700 transition-all active:scale-95 disabled:opacity-40"
                    >
                      Bild schmieden <Zap className="w-4 h-4 fill-current" />
                    </button>
                  </div>
                )}
              </div>

              {/* Style Selection in Sidebar */}
              <div className="pt-6 border-t border-black/5 dark:border-white/5">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 block">Gewählter Stil</label>
                <div className="grid grid-cols-2 gap-2">
                  {styles.map((s) => (
                    <button
                      key={s.value}
                      onClick={() => setSelectedStyle(s.value)}
                      className={`py-2 px-3 rounded-xl border text-[9px] font-black uppercase tracking-wider transition-all flex items-center gap-2 ${
                        selectedStyle === s.value 
                          ? 'bg-orange-600 border-orange-600 text-white shadow-lg' 
                          : 'bg-slate-50 dark:bg-slate-800 border-black/10 dark:border-white/10 text-slate-500 hover:border-orange-500/30'
                      }`}
                    >
                      <span>{s.icon}</span> {s.label.split(' ')[0]}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          ) : (
            <div className="py-20 flex flex-col items-center text-center space-y-8 animate-in zoom-in-95">
              <div className="relative">
                <div className="w-24 h-24 bg-orange-600/10 rounded-[2.5rem] flex items-center justify-center">
                  <Loader2 className="w-12 h-12 text-orange-600 animate-spin" />
                </div>
                <div className="absolute inset-0 bg-orange-500/20 blur-[30px] rounded-full animate-pulse"></div>
              </div>
              <div className="space-y-4">
                <div className="space-y-1">
                  <h3 className="text-sm font-black uppercase tracking-[0.3em] text-slate-900 dark:text-white leading-relaxed">{statusText}</h3>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Perfektion braucht Zeit...</p>
                </div>
                <div className="w-48 h-1.5 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden mx-auto">
                  <div 
                    className="h-full bg-orange-600 transition-all duration-300 ease-out shadow-[0_0_15px_rgba(249,115,22,0.5)]" 
                    style={{ width: `${progress}%` }} 
                  />
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Results Section */}
      <div className="flex-1 space-y-12">
        {results.length > 0 ? (
          <div className="grid gap-12">
            {results.map((res, idx) => (
              <div 
                key={res.id} 
                className="group relative animate-in slide-in-from-bottom-8 duration-700"
                style={{ animationDelay: `${idx * 150}ms` }}
              >
                <div className="bg-white dark:bg-slate-900 rounded-[3.5rem] p-8 md:p-12 shadow-2xl border border-black/5 dark:border-white/10 overflow-hidden">
                  <div className="grid lg:grid-cols-2 gap-10">

                    {/* Image Result */}
                    <div className="space-y-6">
                      <div className="aspect-video rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-white dark:border-slate-800 relative group/img bg-slate-100 dark:bg-slate-800">
                        <img src={res.url} className="w-full h-full object-cover saturate-[1.1] contrast-[1.05]" alt="Thumbnail Result" />

                        {/* Status Overlay */}
                        <div className="absolute top-6 left-6 flex gap-2">
                           <div className="px-4 py-2 bg-black/60 backdrop-blur-md text-white text-[10px] font-black uppercase rounded-xl border border-white/10 flex items-center gap-2">
                             <Eye className="w-3.5 h-3.5 text-orange-500" /> High-CTR Render
                           </div>
                        </div>

                        {/* Hover Actions */}
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center gap-3">
                           <button 
                            className={`p-4 rounded-2xl shadow-xl transition-all hover:scale-110 active:scale-90 bg-white text-rose-500`}
                           >
                             <Heart className={`w-6 h-6`} />
                           </button>
                           <button 
                            onClick={() => {
                              const link = document.createElement('a');
                              link.href = res.url;
                              link.download = `thumbcraft_${Date.now()}.png`;
                              link.click();
                            }}
                            className="p-4 bg-white text-slate-900 rounded-2xl shadow-xl transition-all hover:scale-110 active:scale-90"
                           >
                             <Download className="w-6 h-6" />
                           </button>
                        </div>
                      </div>

                      <div className="flex gap-4">
                        <button 
                          onClick={() => {
                            const link = document.createElement('a');
                            link.href = res.url;
                            link.download = `thumbcraft_4k_${Date.now()}.png`;
                            link.click();
                          }}
                          className="flex-1 py-5 bg-orange-600 hover:bg-orange-700 text-white rounded-2xl font-black text-sm uppercase tracking-widest flex items-center justify-center gap-3 shadow-xl transition-all active:scale-95"
                        >
                          <Download className="w-5 h-5" /> In 4K Herunterladen
                        </button>
                      </div>
                    </div>

                    {/* Insights & Strategy */}
                    <div className="flex flex-col h-full">
                      <div className="flex-1 space-y-8">
                        <div>
                          <h4 className="text-[10px] font-black uppercase tracking-widest text-orange-600 mb-3 flex items-center gap-2">
                            <Sparkles className="w-3.5 h-3.5" /> Design Strategie
                          </h4>
                          <p className="text-sm font-bold text-slate-700 dark:text-slate-300 leading-relaxed bg-slate-50 dark:bg-slate-800/50 p-6 rounded-[2rem] border border-black/5">
                            {res.optimizedPrompt}
                          </p>
                        </div>

                        {res.sources && res.sources.length > 0 && (
                          <div className="space-y-4">
                            <h4 className="text-[10px] font-black uppercase tracking-widest text-blue-500 flex items-center gap-2">
                              <Search className="w-3.5 h-3.5" /> Google Trends Insights
                            </h4>
                            <div className="grid gap-2">
                              {res.sources.map((source, sIdx) => (
                                <a 
                                  key={sIdx} 
                                  href={source.url} 
                                  target="_blank" 
                                  rel="noopener noreferrer"
                                  className="flex items-center justify-between p-4 bg-blue-500/5 border border-blue-500/10 rounded-2xl hover:bg-blue-500/10 transition-colors group"
                                >
                                  <span className="text-xs font-bold text-slate-600 dark:text-slate-400 truncate pr-4">{source.title}</span>
                                  <ExternalLink className="w-3.5 h-3.5 text-blue-400 group-hover:scale-110 transition-transform" />
                                </a>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>

                      <div className="mt-8 pt-8 border-t border-black/5 flex items-center justify-between">
                         <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-400">
                               <Info className="w-5 h-5" />
                            </div>
                            <div>
                               <p className="text-[10px] font-black uppercase tracking-widest text-slate-900 dark:text-white">CTR Prognose</p>
                               <p className="text-[10px] font-bold text-slate-400">Basierend auf Nische</p>
                            </div>
                         </div>
                         <span className="text-3xl font-black text-emerald-500">8.4%</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="h-full flex flex-col items-center justify-center text-center p-12 min-h-[600px] animate-in fade-in duration-1000">
            <div className="relative mb-8">
              <div className="w-32 h-32 bg-slate-100 dark:bg-slate-900 rounded-[3rem] border border-black/5 dark:border-white/5 flex items-center justify-center text-slate-300">
                <ImageIcon className="w-16 h-16" />
              </div>
              <div className="absolute -top-4 -right-4 w-12 h-12 bg-orange-600/10 rounded-2xl flex items-center justify-center text-orange-600 animate-bounce">
                <ArrowRight className="w-6 h-6" />
              </div>
            </div>
            <h3 className="text-3xl font-black mb-4">Bereit für den nächsten Viral-Hit?</h3>
            <p className="text-slate-500 dark:text-slate-400 max-w-sm text-lg font-medium leading-relaxed">
              Beantworte die 6 Fragen links, damit wir dein perfektes Thumbnail schmieden können.
            </p>
            <div className="mt-12 grid grid-cols-2 gap-4 w-full max-w-md">
               <div className="p-4 bg-white/50 dark:bg-slate-900/50 rounded-2xl border border-black/5 text-left">
                  <div className="w-8 h-8 bg-orange-600/10 rounded-lg flex items-center justify-center text-orange-600 mb-3">
                    <Check className="w-4 h-4" />
                  </div>
                  <p className="text-[10px] font-black uppercase tracking-widest text-slate-900 dark:text-white mb-1">Geführt</p>
                  <p className="text-[10px] font-bold text-slate-400">Optimierte Eingaben</p>
               </div>
               <div className="p-4 bg-white/50 dark:bg-slate-900/50 rounded-2xl border border-black/5 text-left">
                  <div className="w-8 h-8 bg-blue-600/10 rounded-lg flex items-center justify-center text-blue-600 mb-3">
                    <Zap className="w-4 h-4" />
                  </div>
                  <p className="text-[10px] font-black uppercase tracking-widest text-slate-900 dark:text-white mb-1">KI-Design</p>
                  <p className="text-[10px] font-bold text-slate-400">CTR-Fokus</p>
               </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  Wand2, Sparkles, Loader2, Download, Coins, Heart, 
  Zap, Target, Eye, HelpCircle, Type as TypeIcon,
  Search, Info, History, Trash2, ArrowRight, ArrowLeft,
  ExternalLink, Check, MessageSquare, Users, BrainCircuit,
  Image as ImageIcon
} from 'lucide-react';
import { generateThumbnail } from '../services/geminiService';
import { User, Design } from '../types';
import { Tooltip } from './Tooltip';

interface StudioGenerateProps {
  useCredits: (amount: number) => boolean;
  user: User | null;
  onGoToPricing?: () => void;
  onSaveDesign?: (design: Design) => void;
  onSavePrompt?: (promptText: string, style: string) => void;
  onDeletePrompt?: (id: string) => void;
}

interface GeneratedResult {
  id: string;
  url: string;
  prompt: string;
  optimizedPrompt: string;
  isSaved?: boolean;
  sources?: {title: string, url: string}[];
}

interface WizardStep {
  id: number;
  question: string;
  sub: string;
  key: keyof typeof initialFormData;
  icon: any;
  placeholder: string;
}

const initialFormData = {
  topic: '',
  audience: '',
  emotion: '',
  visuals: '',
  overlayText: '',
  notes: ''
};

// Memoisiertes Ergebnis-Item zur Vermeidung unnötiger Re-Renders
const ResultItem = React.memo(({ 
  res, 
  onSave, 
  onDownload 
}: { 
  res: GeneratedResult; 
  onSave: (res: GeneratedResult) => void; 
  onDownload: (url: string) => void;
}) => {
  const [imgLoaded, setImgLoaded] = useState(false);

  return (
    <div className="group relative animate-in slide-in-from-bottom-8 duration-700">
      <div className="bg-white dark:bg-slate-900 rounded-[3.5rem] p-8 md:p-12 shadow-2xl border border-black/5 dark:border-white/10 overflow-hidden">
        <div className="grid lg:grid-cols-2 gap-10">

          <div className="space-y-6">
            <div className="aspect-video rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-white dark:border-slate-800 relative group/img bg-slate-100 dark:bg-slate-800">
              {!imgLoaded && (
                <div className="absolute inset-0 flex items-center justify-center bg-slate-100 dark:bg-slate-800 animate-pulse">
                  <Loader2 className="w-8 h-8 text-orange-600/20 animate-spin" />
                </div>
              )}
              <img 
                src={res.url} 
                onLoad={() => setImgLoaded(true)}
