  const steps = useMemo<WizardStep[]>(() => [
    { id: 0, question: "Worum geht es in deinem Video?", sub: "Beschreibe kurz das Thema deines Contents.", key: 'topic', icon: MessageSquare, placeholder: "z.B. 24 Stunden im Wald überleben..." },
    { id: 1, question: "Für wen ist das Video?", sub: "Wer soll auf dein Video klicken?", key: 'audience', icon: Users, placeholder: "z.B. Leute die Survival und Abenteuer lieben..." },
    { id: 2, question: "Was soll man auf dem Bild sehen?", sub: "Welche Personen oder Objekte sind wichtig?", key: 'visuals', icon: ImageIcon, placeholder: "z.B. Ein Zelt im dunklen Wald und ich mit einer Taschenlampe..." },
    { id: 3, question: "Soll Text auf dem Bild stehen?", sub: "Kurz & knackig (maximal 3-4 Wörter).", key: 'overlayText', icon: TypeIcon, placeholder: "z.B. 0% CHANCE oder GEHEIMNIS" },
    { id: 4, question: "Welche Stimmung wünschst du dir?", sub: "Soll es schockierend, lustig oder episch wirken?", key: 'emotion', icon: BrainCircuit, placeholder: "z.B. Sehr düster und gefährlich..." },
    { id: 5, question: "Hast du noch extra Wünsche?", sub: "Gibt es Farben oder Details, die wir beachten sollen?", key: 'notes', icon: Sparkles, placeholder: "z.B. Bitte viel blauen Glow und starken Kontrast..." }
  ], []);

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 4;
          if (prev < 70) return prev + 2;
          if (prev < 95) return prev + 0.5;
          return prev;
        });

        const texts = [
          "Informationen werden synthetisiert...", 
          "Visuelle Hierarchie wird berechnet...", 
          useMarketResearch ? "Markt-Trends werden via Google gescannt..." : "Stil-Vorgaben werden geladen...",
          "Psychologische Farbkorrektur wird angewendet...",
          "High-CTR Finish wird aufgetragen..."
        ];
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress, useMarketResearch]);

  const handleGenerate = async () => {
    const fullPrompt = `
      VIDEO TOPIC: ${formData.topic}
      TARGET AUDIENCE: ${formData.audience}
      EMOTIONAL MOOD: ${formData.emotion}
      VISUAL ELEMENTS: ${formData.visuals}
      ADDITIONAL NOTES: ${formData.notes}
    `.trim();

    const cost = 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt, sources } = await generateThumbnail(
        fullPrompt, 
        selectedStyle, 
        '16:9', 
        useMarketResearch,
        formData.overlayText
      );

      useCredits(cost);

      if (onSavePrompt) {
        onSavePrompt(formData.topic, selectedStyle);
      }

      setResults(prev => [{
        id: `res-${Date.now()}`,
        url,
        prompt: formData.topic,
        optimizedPrompt: optimizedPrompt,
        sources: sources
      }, ...prev]);

      setProgress(100);
      setFormData(initialFormData);
      setStep(0);
    } catch (err) {
      alert("Generierung fehlgeschlagen. Bitte versuche es erneut.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

  const handleDownload = useCallback((url: string) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = `thumbcraft_${Date.now()}.png`;
    link.click();
  }, []);

  const handleSaveToFavorites = useCallback((res: GeneratedResult) => {
    if (onSaveDesign) {
      onSaveDesign({
        id: res.id,
        imageUrl: res.url,
        prompt: res.prompt,
        createdAt: new Date().toISOString(),
        style: selectedStyle,
        aspectRatio: '16:9'
      });
      setResults(prev => prev.map(r => r.id === res.id ? { ...r, isSaved: true } : r));
    }
  }, [onSaveDesign, selectedStyle]);

  const styles = [
    { label: 'MrBeast Style', icon: '🔴', value: 'MrBeast Style' },
    { label: 'Profi Studio', icon: '📸', value: 'Profi Studio' },
    { label: 'Gaming / Neon', icon: '⚡', value: 'Gaming / Neon' },
    { label: 'Story / Doku', icon: '📽️', value: 'Story / Doku' },
    { label: 'Vlog / Real', icon: '🤳', value: 'Vlog / Real' }
  ];

  return (
    <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-12 animate-in fade-in duration-700">

      {/* Input Sidebar: Der Wizard */}
      <div className="w-full lg:w-[450px] space-y-6 shrink-0">
