          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Reviews />
            <Footer />
          </div>
        )}

        {currentView === 'examples' && (
          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Examples onNavigateToStudio={handleStartCreating} />
            <Footer />
          </div>
        )}
      </main>

      {showTour && currentView === 'studio' && <StudioTour onComplete={completeTour} />}

      {isAuthOpen && (
        <AuthModal 
          isOpen={isAuthOpen} 
          onClose={() => setIsAuthOpen(false)} 
          onLogin={handleLogin} 
        />
      )}

      {purchaseSuccess && (
        <div className="fixed bottom-12 left-1/2 -translate-x-1/2 z-[100] bg-blue-600 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-bottom-8 duration-500">
          <CheckCircle className="w-6 h-6" />
          <div>
            <p className="text-sm font-black uppercase tracking-widest">Kauf erfolgreich!</p>
            <p className="text-xs font-bold opacity-80">{purchaseSuccess.amount} Credits zum {purchaseSuccess.planName}-Plan hinzugefügt.</p>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { User, Design, SavedPrompt } from './types';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { PlatformOverview } from './components/PlatformOverview';
import { Pricing } from './components/Pricing';
import { Reviews } from './components/Reviews';
import { AuthModal } from './components/AuthModal';
import { Examples } from './components/Examples';
import { StudioSelection } from './components/StudioSelection';
import { StudioGenerate } from './components/StudioGenerate';
import { StudioChannelAnalyze } from './components/StudioChannelAnalyze';
import { StudioAnalyze } from './components/StudioAnalyze';
import { StudioRemake } from './components/StudioRemake';
import { StudioFavorites } from './components/StudioFavorites';
import { HowItWorks } from './components/HowItWorks';
import { ThumbnailShowcase } from './components/ThumbnailShowcase';
import { ComparisonTable } from './components/ComparisonTable';
import { Sidebar } from './components/Sidebar';
import { StudioTour } from './components/StudioTour';
import { Footer } from './components/Footer';
import { CheckCircle, ArrowLeft } from 'lucide-react';
import { PricingPlan } from './constants';

type MainView = 'home' | 'pricing' | 'reviews' | 'examples' | 'studio';
type StudioView = 'dashboard' | 'generate' | 'channel' | 'analyze' | 'clone' | 'favorites';

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [studioView, setStudioView] = React.useState<StudioView>('dashboard');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [purchaseSuccess, setPurchaseSuccess] = useState<{ planName: string, amount: number } | null>(null);
  const [showTour, setShowTour] = useState(false);
  const [isNavigating, setIsNavigating] = useState(false);
  const [prefilledImageForRemake, setPrefilledImageForRemake] = useState<string | null>(null);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') {
      setIsDarkMode(false);
    } else {
      setIsDarkMode(true);
    }

    const savedUser = localStorage.getItem('thumbcraft_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      document.documentElement.classList.remove('light');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      document.documentElement.classList.add('light');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  useEffect(() => {
    if (user) {
      localStorage.setItem('thumbcraft_user', JSON.stringify(user));
    }
  }, [user]);

  const handleLogin = (email: string) => {
    const newUser: User = { 
      id: '1', 
      email: email, 
      name: email.split('@')[0], 
      credits: 30, 
      isLoggedIn: true,
      plan: 'Starter',
      savedDesigns: [],
      savedPrompts: []
    };
    setUser(newUser);
    setIsAuthOpen(false);
    setCurrentView('studio');
    setStudioView('dashboard');

    const hasSeenTour = localStorage.getItem('hasSeenStudioTour');
    if (!hasSeenTour) {
      setTimeout(() => setShowTour(true), 1500);
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('thumbcraft_user');
    setCurrentView('home');
    setStudioView('dashboard');
    setShowTour(false);
  };

  const toggleTheme = () => setIsDarkMode(prev => !prev);

  const useCredits = (amount: number): boolean => {
    if (!user || user.credits < amount) {
      setCurrentView('pricing');
      return false;
    }
    setUser({ ...user, credits: user.credits - amount });
    return true;
  };

  const handlePurchase = (plan: PricingPlan) => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    setUser({ ...user, credits: user.credits + plan.credits, plan: plan.name as any });
    setPurchaseSuccess({ planName: plan.name, amount: plan.credits });
    setTimeout(() => setPurchaseSuccess(null), 5000);
    setCurrentView('studio');
  };

  const handleSaveDesign = (design: Design) => {
    if (!user) return;
    const favorites = user.savedDesigns || [];
    if (favorites.some(f => f.id === design.id)) return;

    setUser({
      ...user,
      savedDesigns: [...favorites, design]
    });
  };

  const handleSavePrompt = (promptText: string, style: string) => {
    if (!user || !promptText.trim()) return;
    const saved = user.savedPrompts || [];
    if (saved.some(p => p.text === promptText)) return;

    const newPrompt: SavedPrompt = {
      id: Math.random().toString(36).substr(2, 9),
      text: promptText,
      style: style,
      createdAt: new Date().toISOString()
    };

    setUser({
      ...user,
      savedPrompts: [newPrompt, ...saved]
    });
  };

  const handleDeletePrompt = (id: string) => {
    if (!user) return;
    setUser({
      ...user,
      savedPrompts: (user.savedPrompts || []).filter(p => p.id !== id)
    });
  };

  const handleRemoveFavorite = (id: string) => {
    if (!user) return;
    setUser({
      ...user,
      savedDesigns: (user.savedDesigns || []).filter(d => d.id !== id)
    });
  };

  const handleModifyFavorite = (design: Design) => {
    setPrefilledImageForRemake(design.imageUrl);
    setStudioView('clone');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleNavigate = (view: MainView) => {
    if (view === currentView) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    if (view === 'studio' && !user) {
      setIsAuthOpen(true);
      return;
    }

    setIsNavigating(true);
    setTimeout(() => {
      setCurrentView(view);
      if (view === 'studio') {
        setStudioView('dashboard');
        const hasSeenTour = localStorage.getItem('hasSeenStudioTour');
        if (user && !hasSeenTour) {
          setTimeout(() => setShowTour(true), 1000);
        }
      } else {
        setShowTour(false);
      }
      window.scrollTo({ top: 0, behavior: 'smooth' });
      setIsNavigating(false);
    }, 200);
  };

  const handleBack = () => {
    if (currentView === 'studio' && studioView !== 'dashboard') {
      setStudioView('dashboard');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
      handleNavigate('home');
    }
  };

  const handleStartCreating = () => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    handleNavigate('studio');
  };

  const handleSelectStudioTool = (tool: StudioView) => {
    setStudioView(tool);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const completeTour = () => {
    setShowTour(false);
    localStorage.setItem('hasSeenStudioTour', 'true');
  };

  return (
    <div className={`min-h-screen transition-all duration-500 selection:bg-blue-600 selection:text-white bg-slate-50 dark:bg-[#020617] dark:text-slate-100 relative overflow-x-hidden`}>

      {/* Immersives Hintergrundbild & Massive Blue Glows */}
      <div className="fixed inset-0 -z-50 pointer-events-none overflow-hidden">
        {currentView === 'home' && (
          <>
            <img 
              src="https://i.postimg.cc/R0Zm8Z08/IMG-7382.jpg" 
              className="w-full h-full object-cover scale-105 opacity-70 dark:opacity-30 blur-[3px]" 
              alt="ThumbCraft AI Background" 
            />
            {/* Blue-Overlays für den Look */}
            <div className="absolute inset-0 bg-gradient-to-br from-blue-900/40 via-transparent to-transparent opacity-80" />
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,rgba(30,58,138,0.3)_0%,transparent_70%)]" />

            {/* Orangefarbene Striche (Linienmuster) */}
            <div 
              className="absolute inset-0 opacity-[0.15]" 
              style={{
                backgroundImage: `
                  repeating-linear-gradient(45deg, #f97316 0px, #f97316 1px, transparent 1px, transparent 60px),
                  repeating-linear-gradient(-45deg, #f97316 0px, #f97316 1px, transparent 1px, transparent 120px)
                `
              }}
            />
          </>
        )}

        {/* Universelle Ambient Glows in Blue/Cyan - Für "Viel Blau" */}
        <div className="absolute top-[-15%] left-[-15%] w-[90%] h-[90%] bg-blue-600/25 blur-[220px] rounded-full animate-pulse-slow" />
        <div className="absolute bottom-[-15%] right-[-15%] w-[80%] h-[80%] bg-indigo-500/20 blur-[200px] rounded-full animate-glow-dance" />
        <div className="absolute top-[30%] right-[-10%] w-[60%] h-[60%] bg-blue-500/15 blur-[160px] rounded-full animate-pulse-slow" />
        <div className="absolute bottom-[20%] left-[5%] w-[40%] h-[40%] bg-cyan-400/10 blur-[130px] rounded-full" />

        {currentView === 'home' && (
          <div className="absolute inset-x-0 bottom-0 h-3/4 bg-gradient-to-t from-slate-50 dark:from-[#020617] via-transparent to-transparent" />
        )}
      </div>

      <main className={`relative z-10 transition-all duration-300 ${currentView === 'studio' ? 'lg:pl-72' : ''} ${isNavigating ? 'opacity-0 blur-sm' : 'opacity-100 blur-0'}`}>

        <Navbar 
          user={user} 
          currentView={currentView}
          onNavigate={handleNavigate} 
          onLoginClick={() => setIsAuthOpen(true)} 
          onLogout={handleLogout}
          isDarkMode={isDarkMode}
          toggleTheme={toggleTheme}
        />

        {/* Global Back Button */}
        {currentView !== 'home' && (
          <div className="fixed top-28 right-4 lg:right-12 z-50 animate-in fade-in slide-in-from-right-4 duration-500">
            <button 
              onClick={handleBack}
              className="flex items-center gap-2 px-5 py-2.5 bg-white/60 dark:bg-slate-800/80 backdrop-blur-md border border-white/40 dark:border-white/20 rounded-2xl shadow-xl hover:shadow-blue-500/20 hover:border-blue-500/40 group transition-all active:scale-95"
            >
              <ArrowLeft className="w-4 h-4 text-blue-600 group-hover:-translate-x-1 transition-transform" />
              <span className="text-xs font-black uppercase tracking-widest text-slate-800 dark:text-white">Zurück</span>
            </button>
          </div>
        )}

        {currentView === 'home' && (
          <div className="animate-in fade-in duration-500">
            <Hero onStartCreating={handleStartCreating} onViewPricing={() => handleNavigate('pricing')} />
            <PlatformOverview />
            <HowItWorks onExplore={() => handleNavigate('examples')} />
            <ThumbnailShowcase onStartCreating={handleStartCreating} />
            <ComparisonTable />
            <Reviews />
            <Pricing onPurchase={handlePurchase} />
            <Footer />
          </div>
        )}

        {currentView === 'studio' && (
          <div className="pt-24 min-h-screen">
            <Sidebar 
              activeView={studioView} 
              onSelect={setStudioView} 
              user={user}
              onUpgrade={() => handleNavigate('pricing')}
            />

            <div className="p-4 lg:p-12 pb-32">
              <div key={studioView} className="animate-in fade-in slide-up duration-400">
                {studioView === 'dashboard' && (
                  <StudioSelection 
                    user={user} 
                    onSelectMode={(mode) => handleSelectStudioTool(mode as StudioView)} 
                    onGoToPricing={() => handleNavigate('pricing')}
                  />
                )}

                {studioView === 'generate' && (
                  <StudioGenerate 
                    useCredits={useCredits} 
                    user={user} 
                    onGoToPricing={() => handleNavigate('pricing')} 
                    onSaveDesign={handleSaveDesign}
                    onSavePrompt={handleSavePrompt}
                    onDeletePrompt={handleDeletePrompt}
                  />
                )}

                {studioView === 'clone' && (
                  <StudioRemake 
                    useCredits={useCredits} 
                    user={user} 
                    isCloneMode={true} 
                    prefilledImage={prefilledImageForRemake}
                    onSaveDesign={handleSaveDesign}
                  />
                )}

                {studioView === 'analyze' && (
                  <StudioAnalyze useCredits={useCredits} user={user} />
                )}

                {studioView === 'channel' && (
                  <StudioChannelAnalyze useCredits={useCredits} user={user} />
                )}

                {studioView === 'favorites' && (
                  <StudioFavorites 
                    designs={user?.savedDesigns || []} 
                    onRemove={handleRemoveFavorite}
                    onModify={handleModifyFavorite}
                  />
                )}
              </div>
            </div>
          </div>
        )}

        {currentView === 'pricing' && (
          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Pricing onPurchase={handlePurchase} />
            <Footer />
          </div>
        )}

        {currentView === 'reviews' && (
          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Reviews />
            <Footer />
          </div>
        )}

        {currentView === 'examples' && (
          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Examples onNavigateToStudio={handleStartCreating} />
            <Footer />
          </div>
        )}
      </main>

      {showTour && currentView === 'studio' && <StudioTour onComplete={completeTour} />}

      {isAuthOpen && (
        <AuthModal 
          isOpen={isAuthOpen} 
          onClose={() => setIsAuthOpen(false)} 
          onLogin={handleLogin} 
        />
      )}

      {purchaseSuccess && (
        <div className="fixed bottom-12 left-1/2 -translate-x-1/2 z-[100] bg-blue-600 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-bottom-8 duration-500">
          <CheckCircle className="w-6 h-6" />
          <div>
            <p className="text-sm font-black uppercase tracking-widest">Kauf erfolgreich!</p>
            <p className="text-xs font-bold opacity-80">{purchaseSuccess.amount} Credits zum {purchaseSuccess.planName}-Plan hinzugefügt.</p>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

import React from 'react';
import { Wand2, ChevronRight, Coins, Target, Sparkles, TrendingUp, Zap, Youtube, Lock, Star, ArrowUpRight } from 'lucide-react';
import { User } from '../types';

interface StudioSelectionProps {
  user: User | null;
  onSelectMode: (mode: string) => void;
  onGoToPricing?: () => void;
}

export const StudioSelection: React.FC<StudioSelectionProps> = ({ user, onSelectMode, onGoToPricing }) => {
  const currentPlan = user?.plan || 'Starter';
  const userCredits = user?.credits || 0;

  const checkPlanPermission = (planRequired: string) => {
    if (planRequired === 'Starter') return true;
    if (planRequired === 'Creator Pro') return currentPlan === 'Creator Pro' || currentPlan === 'Production';
    return currentPlan === 'Production';
  };

  const suiteModes = [
    {
      id: 'generate',
      title: 'Thumbnail Generator',
      description: 'Erstelle klickstarke Designs basierend auf deiner Video-Idee.',
      icon: <Wand2 className="w-8 h-8" />,
      color: 'bg-orange-600',
      cost: 10,
      planRequired: 'Starter'
    },
    {
      id: 'clone',
      title: 'Stil klonen',
      description: 'Kopiere die Ästhetik erfolgreicher Thumbnails per Klick.',
      icon: <Sparkles className="w-8 h-8" />,
      color: 'bg-blue-600',
      cost: 30,
      planRequired: 'Starter'
    },
    {
      id: 'analyze',
      title: 'CTR Klick-Test',
      description: 'Prüfe dein Design gegen echte Klick-Daten vor dem Upload.',
      icon: <Target className="w-8 h-8" />,
      color: 'bg-emerald-600',
      cost: 50,
      planRequired: 'Creator Pro'
    },
    {
      id: 'channel',
      title: 'Kanal Deep-Check',
      description: 'KI-Analyse deines gesamten Branding-Stils auf YouTube.',
      icon: <Youtube className="w-8 h-8" />,
      color: 'bg-red-600',
      cost: 100,
      planRequired: 'Production'
    }
  ];

  return (
    <div className="max-w-6xl mx-auto py-8">
      {/* Header mit dem angeforderten Selektor: .flex.flex-col.lg:flex-row.gap-8.mb-16 */}
      <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-8 mb-16 relative">
        <div className="relative z-10">
          <h1 className="text-4xl md:text-5xl font-black tracking-tight mb-4">
            Willkommen, <span className="text-orange-600">{user?.name}</span>
          </h1>
          <div className="flex gap-4">
            <div className="px-4 py-1.5 bg-slate-100 dark:bg-slate-800 rounded-xl text-[11px] font-bold text-slate-500 uppercase tracking-widest border border-black/5">
              Plan: {user?.plan}
            </div>
            <div className="px-4 py-1.5 bg-emerald-600/10 rounded-xl text-[11px] font-bold text-emerald-600 uppercase tracking-widest border border-emerald-500/10">
              <Coins className="w-3.5 h-3.5 inline mr-1" /> {user?.credits} Credits
            </div>
          </div>
        </div>

        {/* Visuelle Gap-Betonung: Ein pulsierendes Trennelement, das den Abstand zwischen den Flex-Sektionen hervorhebt */}
        <div className="hidden lg:block absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-px h-12 bg-gradient-to-b from-transparent via-orange-500/30 to-transparent animate-pulse"></div>

        <div className="lg:text-right relative z-10">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2">Status</p>
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-orange-600/10 rounded-2xl border border-orange-500/20 text-orange-600">
            <div className="w-2 h-2 rounded-full bg-orange-600 animate-pulse"></div>
            <span className="text-[10px] font-black uppercase tracking-widest">Kreativ-Modus Aktiv</span>
          </div>
        </div>
      </div>

      <div className="grid md:grid-cols-2 gap-8">
        {suiteModes.map((mode) => {
          const hasPlanPermission = checkPlanPermission(mode.planRequired);
          const hasCredits = userCredits >= mode.cost;
          const isLocked = !hasPlanPermission || !hasCredits;

          return (
            <button
              key={mode.id}
              onClick={() => {
                if (!hasPlanPermission || !hasCredits) onGoToPricing?.();
                else onSelectMode(mode.id);
              }}
              className={`group relative p-8 glass-card rounded-[2.5rem] text-left transition-all hover:-translate-y-1 hover:border-orange-500/30 overflow-hidden ${
                isLocked ? 'opacity-70 grayscale-[0.5]' : ''
              }`}
            >
              <div className="flex justify-between items-start mb-8">
                <div className={`w-16 h-16 rounded-2xl ${mode.color} text-white flex items-center justify-center shadow-lg group-hover:scale-105 transition-transform`}>
                  {mode.icon}
                </div>
                <div className="flex flex-col items-end gap-2">
                   <div className="px-3 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg text-[10px] font-bold text-slate-500 uppercase">
                     {mode.cost} Credits
                   </div>
                   {!hasPlanPermission && (
                     <div className="px-3 py-1 bg-slate-900 text-white rounded-lg text-[10px] font-bold flex items-center gap-1 uppercase">
                       <Lock className="w-3 h-3" /> {mode.planRequired}
                     </div>
                   )}
                </div>
              </div>

              <h3 className="text-2xl font-black mb-3 text-slate-900 dark:text-white group-hover:text-orange-600 transition-colors">
                {mode.title}
              </h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 font-medium leading-relaxed mb-8">
                {mode.description}
              </p>

              <div className="flex items-center gap-2 text-[11px] font-black uppercase tracking-widest text-slate-400 group-hover:text-orange-600 transition-colors">
                Tool starten <ArrowUpRight className="w-4 h-4" />
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
};

