              <div className="p-2.5 bg-orange-600 rounded-xl shadow-lg shadow-orange-600/20">
                <Zap className="w-5 h-5 text-white fill-current" />
              </div>
              <div>
                <h2 className="text-xl font-black text-slate-900 dark:text-white leading-none">Die Schmiede</h2>
                <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">Einfach zum Klickwunder</p>
              </div>
            </div>
            <div className="px-3 py-1.5 rounded-xl bg-orange-600/10 text-[10px] font-black uppercase tracking-widest text-orange-600 flex items-center gap-2">
              <Coins className="w-3.5 h-3.5" /> 10 Credits
            </div>
          </div>

          {!loading ? (
            <div className="space-y-8 animate-in fade-in duration-300 relative z-10">

              <div className="flex gap-1.5">
                {steps.map((_, i) => (
                  <div key={i} className={`h-1.5 flex-1 rounded-full transition-all duration-500 ${i <= step ? 'bg-orange-600' : 'bg-slate-100 dark:bg-slate-800'}`} />
                ))}
