import { StudioTour } from './components/StudioTour';
import { Footer } from './components/Footer';
import { CheckCircle, ArrowLeft, Zap, Sparkles, Target, Star, PlayCircle, TrendingUp } from 'lucide-react';
import { PricingPlan } from './constants';

type MainView = 'home' | 'pricing' | 'reviews' | 'examples' | 'studio';
type StudioView = 'dashboard' | 'generate' | 'channel' | 'analyze' | 'clone' | 'favorites';

const FloatingDecorations = () => (
  <div className="fixed inset-0 pointer-events-none z-0 overflow-hidden">
    {/* Scattered Floating UI Elements */}
    <div className="absolute top-[15%] left-[5%] animate-float-slow opacity-20 hidden xl:block">
      <div className="p-4 glass-float rounded-2xl border-orange-500/20">
        <Sparkles className="w-8 h-8 text-orange-500" />
      </div>
    </div>
    <div className="absolute top-[40%] right-[8%] animate-float-delayed opacity-20 hidden xl:block">
      <div className="p-3 glass-float rounded-full border-blue-500/20">
        <Target className="w-6 h-6 text-blue-400" />
      </div>
    </div>
    <div className="absolute bottom-[20%] left-[10%] animate-float-reverse opacity-20 hidden xl:block">
      <div className="p-5 glass-float rounded-3xl border-emerald-500/20">
        <TrendingUp className="w-10 h-10 text-emerald-500" />
      </div>
    </div>
    <div className="absolute top-[70%] right-[15%] animate-float opacity-15 hidden xl:block">
      <div className="px-4 py-2 glass-float rounded-xl border-orange-500/20 flex items-center gap-2">
        <Zap className="w-4 h-4 text-orange-500 fill-current" />
        <span className="text-[10px] font-black uppercase text-white tracking-widest">Viral Engine</span>
      </div>
    </div>
    <div className="absolute top-[25%] right-[25%] animate-spin-slow opacity-5">
      <Zap className="w-64 h-64 text-orange-600" />
    </div>
  </div>
);

function App() {
  const [user, setUser] = React.useState<User | null>(null);
  const [currentView, setCurrentView] = React.useState<MainView>('home');
  const [studioView, setStudioView] = React.useState<StudioView>('dashboard');
  const [isAuthOpen, setIsAuthOpen] = React.useState(false);
  const [isDarkMode, setIsDarkMode] = React.useState(true);
  const [purchaseSuccess, setPurchaseSuccess] = useState<{ planName: string, amount: number } | null>(null);
  const [showTour, setShowTour] = useState(false);
  const [isNavigating, setIsNavigating] = useState(false);
  const [prefilledImageForRemake, setPrefilledImageForRemake] = useState<string | null>(null);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') {
      setIsDarkMode(false);
    } else {
      setIsDarkMode(true);
    }

    const savedUser = localStorage.getItem('thumbcraft_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      document.documentElement.classList.remove('light');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      document.documentElement.classList.add('light');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  useEffect(() => {
    if (user) {
      localStorage.setItem('thumbcraft_user', JSON.stringify(user));
    }
  }, [user]);

  const handleLogin = (email: string) => {
    const newUser: User = { 
      id: '1', 
      email: email, 
      name: email.split('@')[0], 
      credits: 30, 
      isLoggedIn: true,
      plan: 'Starter',
      savedDesigns: [],
      savedPrompts: []
    };
    setUser(newUser);
    setIsAuthOpen(false);
    setCurrentView('studio');
    setStudioView('dashboard');

    const hasSeenTour = localStorage.getItem('hasSeenStudioTour');
    if (!hasSeenTour) {
      setTimeout(() => setShowTour(true), 1500);
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('thumbcraft_user');
    setCurrentView('home');
    setStudioView('dashboard');
    setShowTour(false);
  };

  const toggleTheme = () => setIsDarkMode(prev => !prev);

  const useCredits = (amount: number): boolean => {
    if (!user || user.credits < amount) {
      setCurrentView('pricing');
      return false;
    }
    setUser({ ...user, credits: user.credits - amount });
    return true;
  };

  const handlePurchase = (plan: PricingPlan) => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    setUser({ ...user, credits: user.credits + plan.credits, plan: plan.name as any });
    setPurchaseSuccess({ planName: plan.name, amount: plan.credits });
    setTimeout(() => setPurchaseSuccess(null), 5000);
    setCurrentView('studio');
  };

  const handleSaveDesign = (design: Design) => {
    if (!user) return;
    const favorites = user.savedDesigns || [];
    if (favorites.some(f => f.id === design.id)) return;

    setUser({
      ...user,
      savedDesigns: [...favorites, design]
    });
  };

  const handleSavePrompt = (promptText: string, style: string) => {
    if (!user || !promptText.trim()) return;
    const saved = user.savedPrompts || [];
    if (saved.some(p => p.text === promptText)) return;

    const newPrompt: SavedPrompt = {
      id: Math.random().toString(36).substr(2, 9),
      text: promptText,
      style: style,
      createdAt: new Date().toISOString()
    };

    setUser({
      ...user,
      savedPrompts: [newPrompt, ...saved]
    });
  };

  const handleDeletePrompt = (id: string) => {
    if (!user) return;
    setUser({
      ...user,
      savedPrompts: (user.savedPrompts || []).filter(p => p.id !== id)
    });
  };

  const handleRemoveFavorite = (id: string) => {
    if (!user) return;
    setUser({
      ...user,
      savedDesigns: (user.savedDesigns || []).filter(d => d.id !== id)
    });
  };

  const handleModifyFavorite = (design: Design) => {
    setPrefilledImageForRemake(design.imageUrl);
    setStudioView('clone');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleNavigate = (view: MainView) => {
    if (view === currentView) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    if (view === 'studio' && !user) {
      setIsAuthOpen(true);
      return;
    }

    setIsNavigating(true);
    setTimeout(() => {
      setCurrentView(view);
      if (view === 'studio') {
        setStudioView('dashboard');
        const hasSeenTour = localStorage.getItem('hasSeenStudioTour');
        if (user && !hasSeenTour) {
          setTimeout(() => setShowTour(true), 1000);
        }
      } else {
        setShowTour(false);
      }
      window.scrollTo({ top: 0, behavior: 'smooth' });
      setIsNavigating(false);
    }, 200);
  };

  const handleBack = () => {
    if (currentView === 'studio' && studioView !== 'dashboard') {
      setStudioView('dashboard');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
      handleNavigate('home');
    }
  };

  const handleStartCreating = () => {
    if (!user) {
      setIsAuthOpen(true);
      return;
    }
    handleNavigate('studio');
  };

  const handleSelectStudioTool = (tool: StudioView) => {
    setStudioView(tool);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const completeTour = () => {
    setShowTour(false);
    localStorage.setItem('hasSeenStudioTour', 'true');
  };

  return (
    <div className={`min-h-screen transition-all duration-500 selection:bg-orange-600 selection:text-white bg-slate-50 dark:bg-[#334155] dark:text-slate-100 relative overflow-x-hidden`}>

      {/* Immersives Hintergrundbild & Massive Orange/Blue Glows */}
      <div className="fixed inset-0 -z-50 pointer-events-none overflow-hidden">
        {currentView === 'home' && (
          <>
            <img 
              src="https://i.postimg.cc/R0Zm8Z08/IMG-7382.jpg" 
              className="w-full h-full object-cover scale-105 opacity-90 dark:opacity-60 blur-[1px]" 
              alt="ThumbCraft AI Background" 
            />
            {/* Lighter Slate-Navy Base with intensified Orange Shine Overlays */}
            <div className="absolute inset-0 bg-gradient-to-br from-blue-600/20 via-orange-400/15 to-orange-800/50 opacity-100" />
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_40%,rgba(249,115,22,0.45)_0%,transparent_80%)]" />

            {/* Zentrale Orange-Aufhellung - Massiv verstärkt für extremen Glow */}
            <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full h-[90%] bg-orange-500/35 blur-[250px] rounded-full animate-pulse-slow" />

            {/* Orangefarbene Striche (Linienmuster) - Markant und hell */}
            <div 
              className="absolute inset-0 opacity-[0.35]" 
              style={{
                backgroundImage: `
                  repeating-linear-gradient(45deg, #f97316 0px, #f97316 1px, transparent 1px, transparent 60px),
                  repeating-linear-gradient(-45deg, #f97316 0px, #f97316 1px, transparent 1px, transparent 120px)
                `
              }}
            />
          </>
        )}

        {/* Universelle Ambient Glows - Heller und kräftiger in Orange */}
        <div className="absolute top-[-5%] left-[-5%] w-[120%] h-[120%] bg-orange-400/40 blur-[300px] rounded-full animate-pulse-slow" />
        <div className="absolute bottom-[-5%] right-[-5%] w-[110%] h-[110%] bg-blue-300/30 blur-[280px] rounded-full animate-glow-dance" />
        <div className="absolute top-[15%] right-[-5%] w-[90%] h-[90%] bg-orange-600/40 blur-[240px] rounded-full animate-pulse-slow" />
        <div className="absolute bottom-[5%] left-[-5%] w-[70%] h-[70%] bg-amber-200/30 blur-[200px] rounded-full" />

        {currentView === 'home' && (
          <div className="absolute inset-x-0 bottom-0 h-3/4 bg-gradient-to-t from-slate-50 dark:from-[#334155] via-transparent to-transparent" />
        )}
      </div>

      <FloatingDecorations />

      <main className={`relative z-10 transition-all duration-300 ${currentView === 'studio' ? 'lg:pl-72' : ''} ${isNavigating ? 'opacity-0 blur-sm' : 'opacity-100 blur-0'}`}>

        <Navbar 
          user={user} 
          currentView={currentView}
          onNavigate={handleNavigate} 
          onLoginClick={() => setIsAuthOpen(true)} 
          onLogout={handleLogout}
          isDarkMode={isDarkMode}
          toggleTheme={toggleTheme}
        />

        {/* Global Back Button */}
        {currentView !== 'home' && (
          <div className="fixed top-28 right-4 lg:right-12 z-50 animate-in fade-in slide-in-from-right-4 duration-500">
            <button 
              onClick={handleBack}
              className="flex items-center gap-2 px-5 py-2.5 bg-white/60 dark:bg-slate-800/80 backdrop-blur-md border border-white/40 dark:border-white/20 rounded-2xl shadow-xl hover:shadow-orange-500/20 hover:border-orange-500/40 group transition-all active:scale-95"
            >
              <ArrowLeft className="w-4 h-4 text-orange-600 group-hover:-translate-x-1 transition-transform" />
              <span className="text-xs font-black uppercase tracking-widest text-slate-800 dark:text-white">Zurück</span>
            </button>
          </div>
        )}

        {currentView === 'home' && (
          <div className="animate-in fade-in duration-500">
            <Hero onStartCreating={handleStartCreating} onViewPricing={() => handleNavigate('pricing')} />
            <PlatformOverview />
            <HowItWorks onExplore={() => handleNavigate('examples')} />
            <ThumbnailShowcase onStartCreating={handleStartCreating} />
            <ComparisonTable />
            <Reviews />
            <Pricing onPurchase={handlePurchase} />
            <Footer />
          </div>
        )}

        {currentView === 'studio' && (
          <div className="pt-24 min-h-screen">
            <Sidebar 
              activeView={studioView} 
              onSelect={setStudioView} 
              user={user}
              onUpgrade={() => handleNavigate('pricing')}
            />

            <div className="p-4 lg:p-12 pb-32">
              <div key={studioView} className="animate-in fade-in slide-up duration-400">
                {studioView === 'dashboard' && (
                  <StudioSelection 
                    user={user} 
                    onSelectMode={(mode) => handleSelectStudioTool(mode as StudioView)} 
                    onGoToPricing={() => handleNavigate('pricing')}
                  />
                )}

                {studioView === 'generate' && (
                  <StudioGenerate 
                    useCredits={useCredits} 
                    user={user} 
                    onGoToPricing={() => handleNavigate('pricing')} 
                    onSaveDesign={handleSaveDesign}
                    onSavePrompt={handleSavePrompt}
                    onDeletePrompt={handleDeletePrompt}
                  />
                )}

                {studioView === 'clone' && (
                  <StudioRemake 
                    useCredits={useCredits} 
                    user={user} 
                    isCloneMode={true} 
                    prefilledImage={prefilledImageForRemake}
                    onSaveDesign={handleSaveDesign}
                  />
                )}

                {studioView === 'analyze' && (
                  <StudioAnalyze useCredits={useCredits} user={user} />
                )}

                {studioView === 'channel' && (
                  <StudioChannelAnalyze useCredits={useCredits} user={user} />
                )}

                {studioView === 'favorites' && (
                  <StudioFavorites 
                    designs={user?.savedDesigns || []} 
                    onRemove={handleRemoveFavorite}
                    onModify={handleModifyFavorite}
                  />
                )}
              </div>
            </div>
          </div>
        )}

        {currentView === 'pricing' && (
          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Pricing onPurchase={handlePurchase} />
            <Footer />
          </div>
        )}

        {currentView === 'reviews' && (
          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Reviews />
            <Footer />
          </div>
        )}

        {currentView === 'examples' && (
          <div className="pt-24 min-h-screen animate-in fade-in duration-500">
            <Examples onNavigateToStudio={handleStartCreating} />
            <Footer />
          </div>
        )}
      </main>

      {showTour && currentView === 'studio' && <StudioTour onComplete={completeTour} />}

      {isAuthOpen && (
        <AuthModal 
          isOpen={isAuthOpen} 
          onClose={() => setIsAuthOpen(false)} 
          onLogin={handleLogin} 
        />
      )}

      {purchaseSuccess && (
        <div className="fixed bottom-12 left-1/2 -translate-x-1/2 z-[100] bg-orange-600 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-bottom-8 duration-500">
          <CheckCircle className="w-6 h-6" />
          <div>
            <p className="text-sm font-black uppercase tracking-widest">Kauf erfolgreich!</p>
            <p className="text-xs font-bold opacity-80">{purchaseSuccess.amount} Credits zum {purchaseSuccess.planName}-Plan hinzugefügt.</p>
          </div>
        </div>
      )}
    </div>
  );
}

