import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const getMimeType = (base64: string): string => {
  const match = base64.match(/^data:([^;]+);base64,/);
  return match ? match[1] : 'image/png';
};

const cleanBase64 = (base64: string): string => {
  return base64.includes(',') ? base64.split(',')[1] : base64;
};

/**
 * Optimiert den Nutzer-Prompt in Echtzeit für die UI.
 */
export const getQuickRefinement = async (userPrompt: string, style: string) => {
  if (userPrompt.trim().length < 3) return "";

  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `ACT AS AN ELITE YOUTUBE THUMBNAIL DESIGNER. 
      Optimiere NUR DIE TECHNISCHE BESCHREIBUNG des Prompts: "${userPrompt}" für den Stil "${style}".

      STRIKTE REGELN:
      - Erstelle eine Photoshop-Komposition mit extremem Fokus.
      - Nutze technische Fachbegriffe wie Rim Light, Depth of Field, Subsurface Scattering.
      - Antworte NUR mit dem optimierten Prompt-Text.`,
      config: {
        thinkingConfig: { thinkingBudget: 0 }
      }
    });
    return response.text?.replace(/^"|"$/g, '') || "";
  } catch (e) {
    return "";
  }
};

/**
 * Erstellt eine tiefgreifende Design-Strategie unter Einbeziehung von Markttrends.
 */
const optimizePromptWithMarketResearch = async (userPrompt: string, style: string, useSearch: boolean) => {
  const ai = getAI();

  let searchSources: any[] = [];
  let promptContext = "";

  if (useSearch) {
    const searchResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Identify high-CTR visual hooks, trending color palettes (e.g. orange/teal), and dominant thumbnail layouts for the niche: "${userPrompt}"`,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });
    promptContext = `MARKET RESEARCH DATA: ${searchResponse.text}`;
    searchSources = searchResponse.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Market Trend Analysis',
      url: chunk.web?.uri || ''
    })).filter((s: any) => s.url) || [];
  }

  const systemInstruction = `You are the World's Best YouTube Thumbnail Strategist. 
  Your goal is to engineer the highest possible Click-Through-Rate (CTR).
  Focus on high-contrast subjects, exaggerated expressions, and vibrant accents.
  Respond ONLY in JSON format.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Develop an elite high-conversion visual strategy for: "${userPrompt}" in the style of "${style}". 
      Incorporate these research insights: ${promptContext}`,
      config: {
        systemInstruction,
        thinkingConfig: { thinkingBudget: 4000 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            optimizedPrompt: { type: Type.STRING, description: "Highly technical prompt for image generation." },
            strategy: { type: Type.STRING, description: "The psychological reasoning behind the design." }
          },
          required: ["optimizedPrompt", "strategy"]
        }
      }
    });
    const parsed = JSON.parse(response.text || '{}');
    return { ...parsed, sources: searchSources };
  } catch (e) {
    return { 
      optimizedPrompt: `${userPrompt}, hyper-realistic photography, cinematic lighting, 8k, vibrant textures, rim light`, 
      strategy: "Optimiert auf Basis von globalen High-Performance Best-Practices.", 
      sources: [] 
    };
  }
};

/**
 * Die finale Bildgenerierung mit optimierten Parametern.
 */
export const generateThumbnail = async (prompt: string, style: string, aspectRatio: string = "16:9", useMarketResearch: boolean = false, overlayText: string = "") => {
  const ai = getAI();

  const { optimizedPrompt, strategy, sources } = await optimizePromptWithMarketResearch(prompt, style, useMarketResearch);

  const textDirective = overlayText ? `
    TEXT OVERLAY INSTRUCTIONS: 
    - The image MUST contain the text "${overlayText.toUpperCase()}".
    - Font: Extra-bold, massive, impact style.
    - Style: Glowing, 3D effect, high contrast against background.
  ` : '';

  const finalInstruction = `
    GOAL: GENERATE AN IRRESISTIBLE YOUTUBE THUMBNAIL.
    AESTHETIC: ${style} Professional Studio Quality.
    KEY DIRECTIVES: 
    - SUBJECT DOMINANCE (Subject should fill 60-70% of frame).
    - EXTREME RIM LIGHTING (Strong highlight along edges).
    - HYPER-DETAILED TEXTURES.
    - VIBRANT COLOR GRADING (Teal/Orange or high saturation).
    - DEPTH OF FIELD (Blurred background).
    ${textDirective}
    SCENE DESCRIPTION: ${optimizedPrompt}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: finalInstruction }] },
      config: { 
        imageConfig: { 
          aspectRatio: aspectRatio as any,
          imageSize: "1K"
        } 
      }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return {
        url: `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`,
        optimizedPrompt: strategy,
        sources: sources
      };
    }
    throw new Error("Generierung fehlgeschlagen.");
  } catch (e: any) {
    throw new Error(e.message || "Fehler in der Bildschmiede.");
  }
};

export const remakeThumbnail = async (sourceBase64: string, adjustmentPrompt: string) => {
  const ai = getAI();
  const instruction = `
    PROFESSIONAL RETOUCHING: 
    Modify this thumbnail while adhering to elite high-end YouTube aesthetics.
    ENHANCE lighting, contrast, and subject focus.
    MODIFICATION: "${adjustmentPrompt}"`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { 
        parts: [
          { inlineData: { data: cleanBase64(sourceBase64), mimeType: getMimeType(sourceBase64) } },
          { text: instruction }
        ] 
      },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData) {
      return `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`;
    }
    return null;
  } catch (e) {
    return null;
  }
};

