      icon: <Youtube className="w-8 h-8" />,
      color: 'bg-red-600',
      cost: 100,
      planRequired: 'Production'
    }
  ];

  return (
    <div className="max-w-6xl mx-auto py-8">
      {/* Header */}
      <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-8 mb-16 relative">
        <div className="relative z-10">
          <h1 className="text-4xl md:text-5xl font-black tracking-tight mb-4 text-slate-900 dark:text-white">
            Willkommen, <span className="text-orange-600">{user?.name}</span>
          </h1>
          <div className="flex gap-4">
            <div className="px-4 py-1.5 bg-slate-100 dark:bg-slate-800 rounded-xl text-[11px] font-bold text-slate-500 uppercase tracking-widest border border-black/5 dark:border-white/5">
              Plan: {user?.plan}
