            <div className="px-4 py-1.5 bg-emerald-600/10 rounded-xl text-[11px] font-bold text-emerald-600 uppercase tracking-widest border border-emerald-500/10">
              <Coins className="w-3.5 h-3.5 inline mr-1" /> {user?.credits} Credits
