export const StudioGenerate: React.FC<StudioGenerateProps> = ({ 
  useCredits, 
  user, 
  onGoToPricing, 
  onSaveDesign,
  onSavePrompt,
}) => {
  const [step, setStep] = useState(0);
  const [formData, setFormData] = useState(initialFormData);
  const [selectedStyle, setSelectedStyle] = useState('MrBeast Style');
  const [useMarketResearch, setUseMarketResearch] = useState(false);

  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<GeneratedResult[]>([]);
  const [zoomedImage, setZoomedImage] = useState<string | null>(null);

  const steps = useMemo<WizardStep[]>(() => [
    { 
      id: 0, 
      question: "Was ist dein Video-Thema?", 
      sub: "Beschreibe kurz den Kerninhalt deines Videos.", 
      key: 'topic', 
      icon: MessageSquare, 
      placeholder: "7 Tage ohne Schlaf experiment..." 
    },
    { 
      id: 1, 
      question: "Wer oder was soll im Fokus stehen?", 
      sub: "Person, Produkt oder ein spezielles Objekt?", 
      key: 'mainSubject', 
      icon: UserIcon, 
      placeholder: "Ich mit extrem müden Augen..." 
    },
    { 
      id: 2, 
      question: "Welchen Vibe soll das Bild haben?", 
      sub: "Z.B. Schockierend, Lustig, Mysteriös oder Episch.", 
      key: 'mood', 
      icon: BrainCircuit, 
      placeholder: "Extrem schockiert und gefährlich..." 
    },
    { 
      id: 3, 
      question: "Text-Einblendung im Bild?", 
      sub: "Maximal 3 Wörter für den ultimativen Klick-Reiz.", 
      key: 'overlayText', 
      icon: TypeIcon, 
      placeholder: "STARK GEFÄHRLICH!" 
    },
    { 
      id: 4, 
      question: "Wo spielt die Szene?", 
      sub: "Wähle den Hintergrund oder die Location.", 
      key: 'location', 
      icon: MapPin, 
      placeholder: "In einem dunklen, unordentlichen Schlafzimmer..." 
    },
    { 
      id: 5, 
      question: "Noch spezielle Wünsche?", 
      sub: "Licht, Farben oder besondere Effekte?", 
      key: 'notes', 
      icon: Sparkles, 
      placeholder: "Viel blauer Glow, Rim-Lighting, 4K Detail..." 
    }
  ], []);

  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 4;
          if (prev < 70) return prev + 2;
          if (prev < 95) return prev + 0.5;
          return prev;
        });

        const texts = [
          "Informationen werden synthetisiert...", 
          "Visuelle Hierarchie wird berechnet...", 
          useMarketResearch ? "Markt-Trends werden via Google gescannt..." : "Stil-Vorgaben werden geladen...",
          "Psychologische Farbkorrektur wird angewendet...",
          "High-CTR Finish wird aufgetragen..."
        ];
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress, useMarketResearch]);

  const handleGenerate = async () => {
    const fullPrompt = `
      VIDEO TOPIC: ${formData.topic}
      MAIN SUBJECT: ${formData.mainSubject}
      MOOD/FEELING: ${formData.mood}
      LOCATION/ENVIRONMENT: ${formData.location}
      ADDITIONAL DETAILS: ${formData.notes}
    `.trim();

    const cost = 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt, sources } = await generateThumbnail(
        fullPrompt, 
        selectedStyle, 
        '16:9', 
        useMarketResearch,
        formData.overlayText
      );

      useCredits(cost);

      if (onSavePrompt) {
        onSavePrompt(formData.topic, selectedStyle);
      }

      setResults(prev => [{
        id: `res-${Date.now()}`,
        url,
        prompt: formData.topic,
        optimizedPrompt: optimizedPrompt,
        sources: sources
      }, ...prev]);

      setProgress(100);
      setFormData(initialFormData);
      setStep(0);
    } catch (err) {
      alert("Generierung fehlgeschlagen. Bitte versuche es erneut.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

  const handleDownload = useCallback((url: string) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = `thumbcraft_${Date.now()}.png`;
    link.click();
  }, []);

  const handleSaveToFavorites = useCallback((res: GeneratedResult) => {
    if (onSaveDesign) {
      onSaveDesign({
        id: res.id,
        imageUrl: res.url,
        prompt: res.prompt,
        createdAt: new Date().toISOString(),
        style: selectedStyle,
        aspectRatio: '16:9'
      });
      setResults(prev => prev.map(r => r.id === res.id ? { ...r, isSaved: true } : r));
    }
  }, [onSaveDesign, selectedStyle]);

  const styles = [
    { label: 'MrBeast Style', icon: '🔴', value: 'MrBeast Style' },
    { label: 'Profi Studio', icon: '📸', value: 'Profi Studio' },
    { label: 'Gaming / Neon', icon: '⚡', value: 'Gaming / Neon' },
    { label: 'Story / Doku', icon: '📽️', value: 'Story / Doku' },
    { label: 'Vlog / Real', icon: '🤳', value: 'Vlog / Real' }
  ];

  return (
    <div className="max-w-[1400px] mx-auto flex flex-col lg:flex-row gap-12 animate-in fade-in duration-700">

      {/* Input Sidebar */}
      <div className="w-full lg:w-[450px] space-y-6 shrink-0">
        <div className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 dark:border-white/10 shadow-2xl sticky top-28 overflow-hidden">
          <div className="absolute top-0 right-0 w-32 h-32 bg-orange-600/5 blur-3xl rounded-full" />

          <div className="flex justify-between items-center mb-8 relative z-10">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-orange-600 rounded-xl shadow-lg shadow-orange-600/20">
                <Zap className="w-5 h-5 text-white fill-current" />
              </div>
              <div>
                <h2 className="text-xl font-black text-slate-900 dark:text-white leading-none">Die Schmiede</h2>
                <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">Einfach zum Klickwunder</p>
              </div>
            </div>
            <div className="px-3 py-1.5 rounded-xl bg-orange-600/10 text-[10px] font-black uppercase tracking-widest text-orange-600 flex items-center gap-2">
              <Coins className="w-3.5 h-3.5" /> 10 Credits
            </div>
          </div>

          {!loading ? (
            <div className="space-y-8 animate-in fade-in duration-300 relative z-10">
              <div className="flex gap-1.5">
                {steps.map((_, i) => (
                  <div key={i} className={`h-1.5 flex-1 rounded-full transition-all duration-500 ${i <= step ? 'bg-orange-600' : 'bg-slate-100 dark:bg-slate-800'}`} />
                ))}
              </div>

              <div className="space-y-4 animate-in slide-in-from-right-4 duration-500" key={step}>
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-orange-500/10 rounded-2xl flex items-center justify-center text-orange-600">
                    {React.createElement(steps[step].icon, { className: "w-6 h-6" })}
                  </div>
                  <div>
                    <h3 className="text-sm font-black text-slate-900 dark:text-white leading-tight uppercase tracking-wider">{steps[step].question}</h3>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">{steps[step].sub}</p>
                  </div>
                </div>

                <div className="relative group">
                  {step === 3 ? (
                    <input 
                      type="text"
                      value={formData[steps[step].key]}
                      onChange={(e) => setFormData({...formData, [steps[step].key]: e.target.value})}
                      placeholder={steps[step].placeholder}
                      className="w-full bg-slate-50 dark:bg-slate-800/50 border border-black/10 dark:border-white/10 rounded-2xl py-5 px-6 text-sm font-bold focus:ring-4 focus:ring-orange-600/10 outline-none transition-all placeholder:text-slate-400 text-slate-900 dark:text-white"
                      autoFocus
                    />
                  ) : (
                    <textarea 
                      value={formData[steps[step].key]}
                      onChange={(e) => setFormData({...formData, [steps[step].key]: e.target.value})}
                      placeholder={steps[step].placeholder}
                      className="w-full h-32 bg-slate-50 dark:bg-slate-800/50 border border-black/10 dark:border-white/10 rounded-2xl p-6 text-sm font-bold focus:ring-4 focus:ring-orange-600/10 outline-none transition-all resize-none placeholder:text-slate-400 text-slate-900 dark:text-white"
                      autoFocus
                    />
                  )}
                </div>
              </div>

              <div className="flex gap-3">
                {step > 0 && (
                  <button 
                    onClick={() => setStep(s => s - 1)}
                    className="flex-1 py-4 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-slate-200 transition-all hover:scale-[1.02] active:scale-95"
                  >
                    <ArrowLeft className="w-3.5 h-3.5" /> Zurück
                  </button>
                )}

                {step < steps.length - 1 ? (
                  <button 
                    onClick={() => setStep(s => s + 1)}
                    disabled={!formData[steps[step].key].trim()}
                    className="flex-[2] py-4 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 hover:opacity-90 transition-all hover:scale-[1.02] active:scale-95 disabled:opacity-40"
                  >
                    Nächster Schritt <ArrowRight className="w-3.5 h-3.5" />
                  </button>
                ) : (
                  <div className="flex-[2] space-y-4">
                     <button 
                      onClick={() => setUseMarketResearch(!useMarketResearch)}
                      className={`w-full p-4 rounded-2xl border flex items-center justify-between transition-all hover:scale-[1.02] active:scale-98 ${
                        useMarketResearch 
                          ? 'bg-blue-600/10 border-blue-600/30 text-blue-600' 
                          : 'bg-slate-50 dark:bg-slate-800/30 border-black/5 dark:border-white/5 text-slate-500'
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <Search className="w-4 h-4" />
                        <span className="text-[10px] font-black uppercase tracking-widest">Markt-Trends nutzen</span>
                      </div>
                      <div className={`w-10 h-5 rounded-full relative transition-colors ${useMarketResearch ? 'bg-blue-600' : 'bg-slate-300'}`}>
                        <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${useMarketResearch ? 'left-6' : 'left-1'}`} />
                      </div>
                    </button>

                    <button 
                      onClick={handleGenerate}
                      disabled={isLowCredits(10)}
                      className="group relative w-full py-5 bg-orange-600 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-3 shadow-xl shadow-orange-600/20 hover:bg-orange-700 transition-all hover:scale-[1.03] active:scale-95 disabled:opacity-40 overflow-hidden"
                    >
                      <span className="relative z-10 flex items-center gap-3">Bild schmieden <Zap className="w-4 h-4 fill-current" /></span>
                      <div className="absolute inset-0 z-0 bg-gradient-to-r from-transparent via-white/20 to-transparent -translate-x-full group-hover:animate-shimmer transition-transform" />
                    </button>
                  </div>
                )}
              </div>

              <div className="pt-6 border-t border-black/5 dark:border-white/5">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 block">Gewählter Stil</label>
                <div className="grid grid-cols-2 gap-2">
                  {styles.map((s) => (
                    <button
                      key={s.value}
                      onClick={() => setSelectedStyle(s.value)}
                      className={`py-2 px-3 rounded-xl border text-[9px] font-black uppercase tracking-wider transition-all flex items-center gap-2 hover:scale-[1.05] active:scale-95 ${
