    const newUser: User = { 
      id: '1', 
      email: email, 
      name: email.split('@')[0], 
      credits: 30, 
      isLoggedIn: true,
      plan: 'Starter',
      savedDesigns: [],
      savedPrompts: []
    };
    setUser(newUser);
    setIsAuthOpen(false);
    setCurrentView('studio');
    setStudioView('dashboard');

    const hasSeenTour = localStorage.getItem('hasSeenStudioTour');
    if (!hasSeenTour) setTimeout(() => setShowTour(true), 1500);
  };

