  const isLowCredits = (cost: number) => !user || user.credits < cost;

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setProgress(prev => {
          if (prev < 30) return prev + 4;
          if (prev < 70) return prev + 2;
          if (prev < 95) return prev + 0.5;
          return prev;
        });

        const texts = [
          "Strategie wird berechnet...", 
          "Visuelle Hierarchie...", 
          useMarketResearch ? "Trend-Scan..." : "Stil-Vorgaben...",
          "Psychologische Korrektur...",
          "High-CTR Finish..."
        ];
        setStatusText(texts[Math.floor((progress / 100) * texts.length)] || texts[texts.length-1]);
      }, 150);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [loading, progress, useMarketResearch]);

  const handleGenerate = async () => {
    const fullPrompt = `
      VIDEO TOPIC: ${formData.topic}
      MAIN SUBJECT: ${formData.mainSubject}
      MOOD/FEELING: ${formData.mood}
      LOCATION/ENVIRONMENT: ${formData.location}
      ADDITIONAL DETAILS: ${formData.notes}
    `.trim();

    const cost = 10;
    if (isLowCredits(cost)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(5);
    try {
      const { url, optimizedPrompt, sources } = await generateThumbnail(
        fullPrompt, 
        selectedStyle, 
        '16:9', 
        useMarketResearch,
        formData.overlayText
      );

      useCredits(cost);

      if (onSavePrompt) {
        onSavePrompt(formData.topic, selectedStyle);
      }

      setResults(prev => [{
        id: `res-${Date.now()}`,
        url,
        prompt: formData.topic,
        optimizedPrompt: optimizedPrompt,
        sources: sources
      }, ...prev]);

      setProgress(100);
      setFormData(initialFormData);
      setStep(0);
    } catch (err) {
      alert("Generierung fehlgeschlagen.");
    } finally {
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 300);
    }
  };

  const handleDownload = useCallback((url: string) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = `thumbcraft_${Date.now()}.png`;
    link.click();
  }, []);

  const handleSaveToFavorites = useCallback((res: GeneratedResult) => {
    if (onSaveDesign) {
      onSaveDesign({
        id: res.id,
        imageUrl: res.url,
        prompt: res.prompt,
        createdAt: new Date().toISOString(),
        style: selectedStyle,
        aspectRatio: '16:9'
      });
      setResults(prev => prev.map(r => r.id === res.id ? { ...r, isSaved: true } : r));
    }
