  const styles = [
    { label: 'MrBeast', icon: '🔴', value: 'MrBeast Style' },
    { label: 'Studio', icon: '📸', value: 'Profi Studio' },
    { label: 'Neon', icon: '⚡', value: 'Gaming / Neon' },
    { label: 'Doku', icon: '📽️', value: 'Story / Doku' }
  ];

  return (
    <div className="max-w-[1400px] mx-auto flex flex-col lg:flex-row gap-8 md:gap-12 animate-in fade-in duration-700">

      <div className="w-full lg:w-[400px] space-y-4 md:space-y-6 shrink-0">
        <div className="p-6 md:p-8 bg-white dark:bg-slate-900 rounded-[2rem] md:rounded-[2.5rem] border border-black/5 dark:border-white/10 shadow-2xl sticky top-28 overflow-hidden">
