              <h2 className="text-lg font-black text-slate-900 dark:text-white leading-none">Die Schmiede</h2>
            </div>
            <div className="px-3 py-1.5 rounded-xl bg-orange-600/10 text-[9px] font-black uppercase tracking-widest text-orange-600 flex items-center gap-2">
              <Coins className="w-3 h-3" /> 10 Credits
            </div>
          </div>

          {!loading ? (
            <div className="space-y-6 md:space-y-8 animate-in fade-in duration-300 relative z-10">
