                      className="w-full bg-slate-50 dark:bg-slate-800/50 border border-black/10 dark:border-white/10 rounded-xl py-4 px-5 text-sm font-bold focus:ring-4 focus:ring-orange-600/10 outline-none transition-all placeholder:text-slate-400 text-slate-900 dark:text-white"
