    {
      id: 0,
      question: "Was ist dein Video-Thema?",
      sub: "Beschreibe kurz worum es geht.",
      key: "topic",
      icon: MessageSquare,
      placeholder: "z.B. 24h im Wald überleben",
      tooltip: "Ein klares Thema hilft der KI den richtigen Kontext zu wählen."
    },
    {
      id: 1,
      question: "Wer oder was ist im Fokus?",
      sub: "Das Hauptsubjekt des Thumbnails.",
      key: "mainSubject",
      icon: Users,
      placeholder: "z.B. Ein schockierter Mann mit Rucksack",
      tooltip: "Subjekte machen 70% des Klick-Erfolgs aus."
    },
    {
      id: 2,
      question: "Welche Stimmung?",
      sub: "Emotionen triggern Klicks.",
      key: "mood",
      icon: Zap,
      placeholder: "z.B. Dramatisch, schockiert, episch",
      tooltip: "Emotionale Trigger erhöhen die CTR nachweislich."
    },
    {
      id: 3,
      question: "Text auf dem Bild?",
      sub: "Kurz, knackig, schlagkräftig.",
      key: "overlayText",
      icon: TypeIcon,
      placeholder: "z.B. UNGLAUBLICH",
      tooltip: "Maximal 3 Worte für beste Lesbarkeit."
    }
  ];

  const handleGenerate = async () => {
    if (!useCredits(10)) {
      onGoToPricing?.();
      return;
    }

    setLoading(true);
    setProgress(10);
    setStatusText("Analysiere Thema...");

    try {
      const res = await generateThumbnail(
        formData.topic,
        selectedStyle,
        "16:9",
        useMarketResearch,
        formData.overlayText
      );

      const newResult: GeneratedResult = {
        id: Math.random().toString(36).substr(2, 9),
        url: res.url,
        prompt: formData.topic,
        optimizedPrompt: res.optimizedPrompt,
        sources: res.sources
      };

      setResults([newResult, ...results]);
      if (onSavePrompt) onSavePrompt(formData.topic, selectedStyle);
    } catch (e) {
      alert("Fehler bei der Generierung.");
    } finally {
      setLoading(false);
      setProgress(0);
    }
  };

  const currentStepData = WIZARD_STEPS[step];

  return (
    <div className="max-w-6xl mx-auto py-8 px-4">
      {/* Zoom Modal */}
      {zoomedImage && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-xl animate-in fade-in duration-300">
           <button onClick={() => setZoomedImage(null)} className="absolute top-8 right-8 text-white hover:text-orange-500 transition-colors">
             <X className="w-10 h-10" />
           </button>
           <img src={zoomedImage} className="max-w-full max-h-full rounded-3xl shadow-2xl animate-in zoom-in-95 duration-500" alt="Zoomed" />
        </div>
      )}

      {results.length > 0 && !loading && (
        <div className="mb-20 space-y-12">
          <h2 className="text-3xl font-black text-slate-900 dark:text-white flex items-center gap-3">
            <History className="w-8 h-8 text-orange-600" /> Letzte Ergebnisse
          </h2>
          <div className="grid gap-12">
            {results.map(res => (
              <ResultItem 
                key={res.id} 
                res={res} 
                onZoom={setZoomedImage}
                onDownload={(url) => {
                  const link = document.createElement('a');
                  link.href = url;
                  link.download = 'thumbnail.png';
                  link.click();
                }}
                onSave={(res) => {
                  if (onSaveDesign) {
                    onSaveDesign({
                      id: res.id,
                      imageUrl: res.url,
                      prompt: res.prompt,
                      createdAt: new Date().toISOString(),
                      style: selectedStyle,
                      aspectRatio: '16:9'
                    });
                    setResults(results.map(r => r.id === res.id ? { ...r, isSaved: true } : r));
                  }
                }}
              />
            ))}
          </div>
          <div className="flex justify-center">
            <button 
              onClick={() => { setResults([]); setStep(0); }}
              className="flex items-center gap-2 text-xs font-black uppercase tracking-widest text-slate-400 hover:text-red-500 transition-colors"
            >
              <Trash2 className="w-4 h-4" /> Verlauf leeren
            </button>
          </div>
        </div>
      )}

      <div className="bg-white dark:bg-slate-900 rounded-[3rem] p-10 shadow-2xl border border-black/5 dark:border-white/10">
        <div className="flex justify-between items-center mb-12">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-orange-600 rounded-2xl flex items-center justify-center text-white shadow-lg">
                <Wand2 className="w-7 h-7" />
              </div>
              <div>
                <h3 className="text-2xl font-black">Design Wizard</h3>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Schritt {step + 1} von {WIZARD_STEPS.length}</p>
              </div>
           </div>
           <div className="flex items-center gap-2 px-4 py-2 bg-orange-600/10 rounded-xl text-orange-600 border border-orange-500/10 text-xs font-black uppercase tracking-widest">
              <Coins className="w-4 h-4" /> 10 Credits
           </div>
        </div>

        {loading ? (
          <div className="py-20 flex flex-col items-center justify-center space-y-8 animate-in fade-in">
             <div className="relative">
                <div className="absolute inset-0 bg-orange-600/20 blur-3xl animate-pulse rounded-full" />
                <Loader2 className="w-20 h-20 text-orange-600 animate-spin relative z-10" />
             </div>
             <div className="text-center space-y-2">
                <p className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-widest">{statusText}</p>
