             </div>
             <div className="w-full max-w-md h-2 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                <div className="h-full bg-orange-600 transition-all duration-500" style={{ width: `${progress}%` }} />
             </div>
          </div>
        ) : (
          <div className="space-y-10 animate-in slide-in-from-right-4">
             <div className="space-y-4">
                <div className="flex items-center gap-3 text-orange-600">
                   <currentStepData.icon className="w-6 h-6" />
                   <h4 className="text-xl font-black">{currentStepData.question}</h4>
                </div>
                <p className="text-slate-500 dark:text-slate-400 font-medium">{currentStepData.sub}</p>

                <Tooltip text={currentStepData.tooltip}>
                  <div className="relative group">
                    <textarea 
                      value={formData[currentStepData.key] as string}
                      onChange={(e) => setFormData({ ...formData, [currentStepData.key]: e.target.value })}
                      placeholder={currentStepData.placeholder}
                      className="w-full h-32 bg-slate-50 dark:bg-slate-800/50 border border-black/5 dark:border-white/5 rounded-3xl p-6 text-lg font-bold outline-none focus:ring-4 focus:ring-orange-600/10 transition-all"
                    />
                  </div>
                </Tooltip>
             </div>

             <div className="space-y-6">
                <h4 className="text-xs font-black uppercase tracking-widest text-slate-400">Stil & Marktforschung</h4>
                <div className="grid md:grid-cols-2 gap-4">
                   <div className="p-6 bg-slate-50 dark:bg-slate-800/50 rounded-2xl border border-black/5">
                      <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4">Design Stil</p>
                      <select 
                        value={selectedStyle}
                        onChange={(e) => setSelectedStyle(e.target.value)}
                        className="w-full bg-white dark:bg-slate-900 border border-black/5 dark:border-white/10 rounded-xl p-3 font-bold"
                      >
                        <option>MrBeast Style</option>
                        <option>Clean Minimalist</option>
                        <option>Epic Gaming</option>
                        <option>Professional Tech</option>
                        <option>Vibrant Vlog</option>
                      </select>
                   </div>
                   <button 
                    onClick={() => setUseMarketResearch(!useMarketResearch)}
                    className={`p-6 rounded-2xl border transition-all flex items-center justify-between group ${useMarketResearch ? 'bg-blue-600 border-blue-500 text-white' : 'bg-slate-50 dark:bg-slate-800/50 border-black/5 text-slate-500'}`}
                   >
                      <div className="flex items-center gap-4">
                        <Search className={`w-6 h-6 ${useMarketResearch ? 'text-white' : 'text-slate-400 group-hover:text-blue-500'}`} />
                        <div className="text-left">
                           <p className="text-xs font-black uppercase tracking-widest">Marktforschung</p>
                           <p className={`text-[10px] font-bold ${useMarketResearch ? 'text-blue-100' : 'text-slate-400'}`}>Trend-Analyse einbeziehen</p>
                        </div>
                      </div>
                      <div className={`w-10 h-6 rounded-full p-1 transition-colors ${useMarketResearch ? 'bg-white' : 'bg-slate-200 dark:bg-slate-700'}`}>
                         <div className={`w-4 h-4 rounded-full transition-all ${useMarketResearch ? 'bg-blue-600 ml-4' : 'bg-white'}`} />
                      </div>
                   </button>
                </div>
             </div>

             <div className="flex items-center justify-between pt-8 border-t border-black/5 dark:border-white/5">
                <button 
                  onClick={() => setStep(prev => Math.max(0, prev - 1))}
                  disabled={step === 0}
                  className="px-8 py-4 bg-slate-100 dark:bg-slate-800 text-slate-500 rounded-2xl font-black uppercase tracking-widest text-xs flex items-center gap-2 hover:bg-slate-200 transition-all disabled:opacity-0"
                >
